INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156000,'47212','Castillo de Villalba de los Alcores','monumento','monumentos_osm','El castillo de Villalba de los Alcores es una fortaleza militar situada sobre un alcor o colina en el municipio medieval de Villalba de los Alcores, anteriormente denominada Villalba del Alcor, en la provincia de Valladolid (Castilla y León, España).​ Desde el 4 de junio de 1931 tiene reconocida la condición de…',41.8631005,-4.8616707,'https://es.wikipedia.org/wiki/Castillo_de_Villalba_de_los_Alcores','BIC Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156001,'47212','Villalba de los Alcores','monumento','monumentos_osm','Villalba de los Alcores es un municipio y localidad española de la provincia de Valladolid en la comunidad autónoma de Castilla y León. Situado al nordeste de la provincia de Valladolid, está inmerso en el borde superior de la comarca de los Montes Torozos, rodeado por encinas y quejigos, y por interminables campos…',41.8636295,-4.859104,'https://es.wikipedia.org/wiki/Villalba_de_los_Alcores','BIC Nacional');
