INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156004,'47210','Villalar de los Comuneros','monumento','monumentos_osm','Villalar de los Comuneros​ es un municipio y localidad española de la provincia de Valladolid, en la comunidad autónoma de Castilla y León. Es célebre porque en sus alrededores tuvo lugar la batalla que supuso la derrota de los Comuneros de Castilla el 23 de abril de 1521.',41.5499934,-5.1384795,'https://es.wikipedia.org/wiki/Villalar_de_los_Comuneros','BIC Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156005,'46049','Cova Negra','monumento','monumentos_osm','El paraje natural municipal La Cova Negra se sitúa en el término municipal de Játiva, provincia de Valencia en España. En la Cova Negra se encuentra el yacimiento del Paleolítico medio en el cual han aparecido restos de Homo neandertalensis.',38.9651708,-0.4965661,'https://es.wikipedia.org/wiki/La_Cova_Negra','BIC Nacional');
