INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156012,'30041','Casa del Piñón','monumento','monumentos_osm','La Casa del Piñón es un edificio modernista de la ciudad española de La Unión (Región de Murcia), construido por el arquitecto murciano Pedro Cerdán en 1899, en plena época de esplendor de la Sierra minera de Cartagena-La Unión. Fue un encargo del empresario Joaquín Peñalver Nieto, como edificio de viviendas en…',37.6173225,-0.8782202,'https://es.wikipedia.org/wiki/Casa_del_Piñón','BIC Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156013,'30041','Mercado Público de La Unión','monumento','monumentos_osm','El antiguo mercado público de La Unión (Región de Murcia, España) es una obra de estilo modernista que, junto con el Gran hotel de Cartagena, es una de las más destacadas del modernismo en la Región de Murcia.',37.616313,-0.8755435,'https://es.wikipedia.org/wiki/Mercado_público_de_La_Unión','BIC Nacional');
