INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156017,'29903','Dolmen de La Giganta','monumento','monumentos_osm','El dolmen de la Giganta es una construcción megalítica situada en el término municipal de Ronda, cerca del monte del Higuerón y que fue descubierto en 1941. Muestra importante de la arquitectura megalítica en Andalucía, perteneciente al Eneolítico, durante el II milenio a.',36.7837827,-5.2712581,'https://es.wikipedia.org/wiki/Dolmen_de_la_Giganta','BIC Nacional');
