INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156042,'30026','Torre de Santa Isabel','monumento','monumentos_osm','La torre de Santa Isabel, también conocida como Torre de Las Cumbres o Torre Vieja del Puerto, es una torre de vigilancia costera del siglo XVI situada en el núcleo urbano del Puerto de Mazarrón (Región de Murcia, España).',37.5676305,-1.2623206,'https://es.wikipedia.org/wiki/Torre_de_Santa_Isabel','BIC Nacional');
