INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156056,'03015','la Illeta dels Banyets','monumento','monumentos_osm','El jaciment arqueològic de la Illeta, també anomenat Illeta dels Banyets i popularment Banyets de la Reina, correspon a l''època del bronze, orientalitzant, ibèric antic, ple i romà imperial; està situat al terme municipal del Campello (l''Alacantí, País Valencià). La Illeta va deixar de ser illa el 1944, amb la…',38.4320277,-0.3812116,'https://ca.wikipedia.org/wiki/Illeta_dels_Banyets','BIC Nacional');
