INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156058,'11004','Castell Vell','monumento','monumentos_osm','El Castell de Fadrell, també anomenat Castell Vell, Castell de la Magdalena, dels Moros o de Sas se situa al terme municipal de Castelló de la Plana, al País Valencià. Es tracta d''un castell d''origen musulmà construït entre els segles xi i xiii.',40.0348896,-0.0053797,'https://ca.wikipedia.org/wiki/Castell_de_Fadrell','BIC Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156059,'11004','Convent Nou del Desert de les Palmes','monumento','monumentos_osm','El Convent Carmelita o Monestir dels Pares Carmelites del Desert de les Palmes està situat en el terme municipal de Benicàssim. L''elecció d''aquest lloc privilegiat dels contraforts del massís del Maestrat, integrant del Sistema Ibèric, com a lloc d''assentament d''un dels “Deserts” de l''Orde del Carmel Descalç (OCD)…',40.0745414,0.0280144,'https://ca.wikipedia.org/wiki/Monestir_dels_Pares_Carmelites_del_Desert_de_les_Palmes','BIC Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156060,'11004','Ermita de la Magdalena','iglesia','monumentos_osm','L''Ermitori de la Magdalena és un edifici d''ús religiós del municipi de Castelló de la Plana (la Plana Alta), declarat Bé d''Interès Cultural (BIC) i situat a un turó als afores de la ciutat des d''on s''alça per sobre de la Plana de Castelló. L''edifici actual és del segle xv i forma un conjunt amb les restes del…',40.0346033,-0.0058228,'https://ca.wikipedia.org/wiki/Ermitori_de_la_Magdalena','BIC Nacional');
