INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156064,'31211','Done Jakueren eliza','iglesia','monumentos_osm','Done Jakueren eliza Orreaga udalerriko XIII. mendeko kristiau eliza bat da, gotiko estiloan. Donejakue Bidearen baitako ondare kontsideratzen da, Nafar Bideak Nafarroan egiten duen etaparen parte.',43.0088101,-1.3195173,'https://eu.wikipedia.org/wiki/Done_Jakueren_eliza_(Orreaga)');
