INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156068,'03009','Banys de la Reina','monumento','monumentos_osm','Els Banys de la Reina són un jaciment arqueològic situat al costat de les salines de Calp (Marina Alta, País Valencià). Constava d''un palau romà (no una simple vil·la o domus circular) amb un passadís, pati i huit habitacions.',38.6415009,0.0607014,'https://ca.wikipedia.org/wiki/Banys_de_la_Reina_(Calp)','BIC Nacional');
