INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156077,'90799','Castillo de Grajal de Campos','monumento','monumentos_osm','El Castillo de Grajal de Campos es una construcción militar del XVI situada en esta localidad leonesa, sobre los restos de otro castillo anterior del siglo X. Se le considera el primer castillo artillero en España. Es un impresionante edificio diseñado por el arquitecto Lorenzo de Aldonza, llevada a cabo entre los…',42.3220052,-5.0210787,'https://es.wikipedia.org/wiki/Castillo_de_Grajal_de_Campos','BIC Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156078,'90799','Palacio de los Condes de Grajal','monumento','monumentos_osm','El palacio de los Condes de Grajal es un inmueble de la localidad española de Grajal de Campos, en la provincia de León.',42.3212638,-5.019637,'https://es.wikipedia.org/wiki/Palacio_de_los_Condes_de_Grajal','BIC Nacional');
