INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156080,'24115','Basílica de Nuestra Señora de la Encina','iglesia','monumentos_osm','La basílica de La Encina es un templo cristiano situado en la localidad española de Ponferrada, en la comarca de El Bierzo, provincia de León, comunidad autónoma de Castilla y León.',42.5442124,-6.5917275,'https://es.wikipedia.org/wiki/Basílica_de_la_Virgen_de_la_Encina','BIC Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156081,'24115','Castillo de Ponferrada','monumento','monumentos_osm','El castillo de Ponferrada, también conocido como el castillo de los Templarios,​ es una fortaleza medieval situada en la ciudad española de Ponferrada, comarca de El Bierzo, provincia de León. Se alza sobre una colina en la confluencia de los ríos Boeza y Sil.',42.5440165,-6.5936667,'https://es.wikipedia.org/wiki/Castillo_de_Ponferrada','BIC Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156082,'24115','Iglesia de Santa María de Vizbayo','iglesia','monumentos_osm','La iglesia de Santa María de Vizbayo es un templo católico. Su edificio es de estilo románico y se encuentra situada en la falda del Monte Pajariel, en el pueblo de Otero, municipio de Ponferrada, comarca de El Bierzo (León, España).',42.5373942,-6.5944292,'https://es.wikipedia.org/wiki/Iglesia_de_Santa_María_de_Vizbayo','BIC Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156083,'24115','Convento de la Purísima Concepción','monumento','monumentos_osm','El convento de la Purísima Concepción es un convento situado en la céntrica Calle del Reloj de Ponferrada, en la comarca de El Bierzo, provincia de León, comunidad autónoma de Castilla y León.',42.5456665,-6.5916831,'https://es.wikipedia.org/wiki/Convento_de_la_Purísima_Concepción_(Ponferrada)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156084,'24115','Iglesia de San Andrés','iglesia','monumentos_osm','La iglesia de San Andrés de Ponferrada está situada a los pies del castillo de Ponferrada, en la comarca de El Bierzo (Castilla y León, España). Se comenzó a construir a finales del siglo XVII. En su interior se encuentra el retablo mayor de estilo barroco, obra de José Ovalle y Andrés de Benavente, y el Cristo de…',42.5431448,-6.5930418,'https://es.wikipedia.org/wiki/Iglesia_de_San_Andrés_(Ponferrada)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156085,'32054','Catedral de San Martiño de Ourense','iglesia','monumentos_osm','A catedral de Ourense, baixo a advocación de san Martiño, é un templo católico situado na cidade de Ourense, sede da diocese do mesmo nome. É de estilo románico de transición con influencias cistercienses nalgúns aspectos arquitectónicos e mateanos no eido escultural, pero no que se realizaron numerosas…',42.3364155,-7.863175,'https://gl.wikipedia.org/wiki/Catedral_de_Ourense','BIC Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156086,'32054','Ponte Maior','monumento','monumentos_osm','A ponte Maior de Ourense, tamén coñecida como ponte Romana ou ponte Vella, é un viaduto sobre o río Miño situado na cidade de Ourense. Por ela discorre o Camiño de Santiago.',42.3451825,-7.8687819,'https://gl.wikipedia.org/wiki/Ponte_Maior_de_Ourense','BIC Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156087,'32054','Ponte Romana','monumento','monumentos_osm','A ponte Maior de Ourense, tamén coñecida como ponte Romana ou ponte Vella, é un viaduto sobre o río Miño situado na cidade de Ourense. Por ela discorre o Camiño de Santiago.',42.3451921,-7.8687829,'https://gl.wikipedia.org/wiki/Ponte_Maior_de_Ourense','BIC Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156088,'32054','Fonte das Burgas','monumento','monumentos_osm','As Burgas son uns mananciais de augas termais que se localizan na cidade de Ourense. Deles brotan unhas augas silicatadas, fluoradas, líticas e hipertermais, a unha temperatura entre 64 e 68 °C cun caudal de 300 litros por minuto.',42.3346173,-7.8653065,'https://gl.wikipedia.org/wiki/As_Burgas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156089,'32054','Igrexa da Inmaculada de Montealegre','iglesia','monumentos_osm','La Parroquia de la Inmaculada de Montealegre es un templo católico de siglo XX ubicado en el barrio de A Inmaculada, en las faldas del Montealegre, en Orense (Galicia, España).',42.3318815,-7.8565351,'https://es.wikipedia.org/wiki/Parroquia_de_la_Inmaculada_de_Montealegre');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156090,'47175','Iglesia de Nuestra Señora de la Asunción','iglesia','monumentos_osm','La iglesia parroquial de la Asunción es un templo católico ubicado en la localidad de Tudela de Duero, provincia de Valladolid (Castilla y León, España).',41.5839813,-4.5798082,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Tudela_de_Duero)','BIC Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156091,'27066','Porta de Carlos V','monumento','monumentos_osm','A Porta de Carlos V, tamén chamada Porta Maior ou Porta do Castelo da Ponte (polo seu aspecto de fortaleza) é unha das tres portas que se conservan da antiga muralla da vila de Viveiro, na provincia de Lugo, edificada en 1548 por obra de Pedro Pedroso. Realizouse en homenaxe a Carlos V substituíndo outra anterior…',43.6623113,-7.5962684,'https://gl.wikipedia.org/wiki/Porta_de_Carlos_V','BIC Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156092,'27066','Capela da Misericordia','iglesia','monumentos_osm','A capela da Misericordia ou capela da Nosa Señora da Misericordia é un templo relixioso situado en Viveiro. Está situada no barrio da Misericordia, nos arrabaldes do núcleo urbano, do outro lado da ría de Viveiro, sobre a cal pasa a ponte da Misericordia.',43.6646676,-7.6019011,'https://gl.wikipedia.org/wiki/Capela_da_Misericordia_de_Viveiro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156093,'27066','Igrexa de Santa María do Campo','iglesia','monumentos_osm','A igrexa de Santa María do Campo é un templo relixioso situado en Viveiro, na provincia de Lugo. Está situada na parte máis alta do centro histórico, xunto ao Convento das Concepcionistas.',43.6615722,-7.5943459,'https://gl.wikipedia.org/wiki/Igrexa_de_Santa_María_do_Campo_de_Viveiro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156094,'27066','Igrexa do Convento de San Francisco','iglesia','monumentos_osm','A igrexa do Convento de San Francisco é o templo católico da parroquia de Santiago de Viveiro (concello de Viveiro). É unha construción erixida no século XIV, con nave única.',43.6631394,-7.5941203,'https://gl.wikipedia.org/wiki/Igrexa_de_San_Francisco_de_Viveiro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156095,'27066','Porta da Vila','monumento','monumentos_osm','A Porta da Vila ou Porta do Cristo do Amparo (tamén do Santo Cristo) é unha das tres portas actualmente en pé da antiga muralla da vila de Viveiro (tiña seis portas e catro portelos), na provincia de Lugo. Data do século XIII e é a entrada principal á cidade pola antiga calzada romana.',43.6605083,-7.5949995,'https://gl.wikipedia.org/wiki/Porta_da_Vila');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,nivel_sello) VALUES(156096,'17006','Fuente del Río','monumento','monumentos_osm','Monumento en Cabra (Córdoba). Declarado Bien de Interés Cultural.',37.4651949,-4.4230186,'BIC Nacional');
