INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156098,'90810','Iglesia de Santiago','iglesia','monumentos_osm','La iglesia de Santiago Apóstol es un templo católico ubicado en la localidad de Alcazarén, provincia de Valladolid, Castilla y León, España.',41.3706253,-4.6712149,'https://es.wikipedia.org/wiki/Iglesia_de_Santiago_Apóstol_(Alcazarén)','BIC Nacional');
