INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156103,'24180','Monasterio de San Miguel de Escalada','iglesia','monumentos_osm','El monasterio de San Miguel de Escalada es un templo mozárabe ubicado cerca del pueblo homónimo, en el municipio de Gradefes, provincia de León, España. Situado en el Camino de Santiago, a 27 kilómetros de la ciudad de León, formaba parte de un antiguo monasterio del que hoy sólo se conserva el templo.',42.5712908,-5.3027667,'https://es.wikipedia.org/wiki/Monasterio_de_San_Miguel_de_Escalada','BIC Nacional');
