INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156117,'47015','Puente y calzada romana de Becilla de Valderaduey','monumento','monumentos_osm','El puente de Becilla de Valderaduey es un puente que tradicionalmente ha sido considerado de origen romano –con su correspondiente calzada– sobre el río Valderaduey, aunque probablemente su origen sea posterior. Sus restos se encuentran en el municipio de Becilla de Valderaduey, en la provincia de Valladolid, de la…',42.0953359,-5.2142355,'https://es.wikipedia.org/wiki/Puente_y_calzada_romana_de_Becilla_de_Valderaduey','BIC Nacional');
