INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156119,'47054','Monasterio de Santa María de la Armedilla','monumento','monumentos_osm','El monasterio de Santa María de la Armedilla fue un monasterio de la Orden de San Jerónimo, hoy en ruinas, a unos 3,8 km de Cogeces del Monte (provincia de Valladolid, España).',41.5395321,-4.3413866,'https://es.wikipedia.org/wiki/Monasterio_de_Santa_María_de_la_Armedilla','BIC Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156120,'47054','Iglesia de Nuestra Señora de la Asunción','iglesia','monumentos_osm','La iglesia de Nuestra Señora de la Asunción es un templo de culto católico ubicado en Cogeces del Monte (Valladolid). Pertenece al periodo del gótico tardío, pues fue levantada en el siglo XVI, se compone de tres naves con bóvedas de arista en yesería y de crucería en la capilla mayor.',41.5112041,-4.3149351,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Cogeces_del_Monte)');
