INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156151,'47103','Iglesia de San Pelayo','iglesia','monumentos_osm','La iglesia de San Pelayo es un templo católico ubicado en la localidad de Olivares de Duero, Provincia de Valladolid, Castilla y León, España. Es de estilo gótico, de la segunda mitad del siglo XV, con tres naves con bóvedas de crucerías estrelladas.',41.638447,-4.3668162,'https://es.wikipedia.org/wiki/Iglesia_de_San_Pelayo_(Olivares_de_Duero)','BIC Nacional');
