INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156153,'47207','Colegiata de San Luis','iglesia','monumentos_osm','La colegiata de San Luis es un templo católico ubicado en la localidad de Villagarcía de Campos, provincia de Valladolid (Castilla y León, España). Ejemplo de la arquitectura renacentista del siglo XVI, es obra del arquitecto Rodrigo Gil de Hontañón.',41.7788812,-5.190901,'https://es.wikipedia.org/wiki/Colegiata_de_San_Luis','BIC Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156154,'47116','Pintia','monumento','monumentos_osm','Pintia es el nombre de una antigua ciudad vaccea, situada en la pedanía de Padilla de Duero (Peñafiel), en la actual provincia de Valladolid.​ En 1993 fue declarado bien de interés cultural como zona arqueológica.',41.6255647,-4.168679,'https://es.wikipedia.org/wiki/Pintia','BIC Nacional');
