INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156159,'17208','la Torre','monumento','monumentos_osm','La Torre és una antiga casa forta en un promontori a la Vall del Bac, al terme municipal de la Vall de Bianya, en una situació immillorable per a vigilar la ruta cap al Ripollès, enfront l''església de Sant Miquel. Com una munió de fortificacions fou declarada bé cultural d''interès nacional.',42.2643508,2.4533334,'https://ca.wikipedia.org/wiki/Torre_de_la_Vall_del_Bac','BIC Nacional');
