INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156163,'47142','Iglesia de San Cipriano','iglesia','monumentos_osm','La iglesia de San Cipriano o de San Cebrián,​​es un templo mozárabe prerrománico situado en el municipio de San Cebrián de Mazote, en la provincia de Valladolid, España. Se encuentra en el centro de la localidad y es la parroquia de la población, formando parte de la archidiócesis de Valladolid.',41.6809306,-5.1469642,'https://es.wikipedia.org/wiki/Iglesia_de_San_Cipriano_(San_Cebrián_de_Mazote)','BIC Nacional');
