INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156176,'39025','Iglesia de San Vicente Mártir','iglesia','monumentos_osm','La iglesia de san Vicente Mártir en Corrales de Buelna es un conjunto arquitectónico que cuenta con la Iglesia dedicada a San Vicente Mártir y un antiguo asilo. Actualmente se usa para la enseñanza de catequesis y tiene además un centro de ayuda social creado por Caritas.',43.2605732,-4.0666636,'https://es.wikipedia.org/wiki/Iglesia_de_San_Vicente_Mártir_y_asilo_de_San_José');
