INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(156179,'28501','Palacio de la Zarzuela','monumento','monumentos_osm','El Palacio de La Zarzuela​ es un recinto palaciego situado a las afueras de Madrid, en medio de un espacio natural conocido como monte de El Pardo. Es la residencia privada de la familia real española así como la sede de la Casa de Su Majestad el Rey.',40.483271,-3.8015174,'https://es.wikipedia.org/wiki/Palacio_de_la_Zarzuela','BIC Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156180,'28501','Puerta de Hierro','monumento','monumentos_osm','La Puerta de Hierro es un monumento de la segunda mitad del siglo XVIII ubicado en la parte noroccidental de Madrid (España), en las inmediaciones del Monte de El Pardo. Ocupa una isleta ajardinada, definida por varios ramales de las autopistas A-6 y M-30, que bordean un enclave de difícil acceso.',40.4556121,-3.7443376,'https://es.wikipedia.org/wiki/Puerta_de_Hierro_(Madrid)');
