INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156237,'28508','Acueducto de Amaniel','monumento','monumentos_osm','El canal Bajo es un canal de transporte de agua del Canal de Isabel II, empresa que suministra el agua a Madrid, que enlaza el depósito inferior de la central eléctrica de Torrelaguna con el depósito de Islas Filipinas (Tercer Depósito) en Madrid. Tiene una longitud de 58,1 km y una capacidad de conducción de 4 m³/s.',40.4509932,-3.7107431,'https://es.wikipedia.org/wiki/Canal_Bajo_de_Madrid');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156238,'28508','Iglesia Espíritu Santo','iglesia','monumentos_osm','La iglesia del Espíritu Santo es una iglesia ubicada en la calle Serrano de Madrid (España). Fue construida entre 1942 y 1943 por el arquitecto español Miguel Fisac.',40.4419614,-3.6863689,'https://es.wikipedia.org/wiki/Iglesia_del_Espíritu_Santo_(Madrid)');
