INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156240,'28508','Parroquia Hispanoamericana de la Merced','iglesia','monumentos_osm','La Basílica Hispanoamericana de la Merced se encuentra en la ciudad de Madrid, España, en la calle de Edgar Neville, 23. Fue proyectada por los arquitectos Francisco Javier Sáenz de Oiza y Luis Laorga.',40.4495105,-3.6973618,'https://es.wikipedia.org/wiki/Basílica_Hispanoamericana_de_Nuestra_Señora_de_la_Merced');
