INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156242,'48046','Gernikako Arbola','monumento','monumentos_osm','Gernikako arbola Gernikako (Bizkaia) Batzar Etxearen aurrean dagoen haritza (Quercus robur) da. Zuhaitz horrek bai bizkaitarren, bai euskal herritarren askatasun tradizionala eta Euskal Herriko foruak adierazten ditu.',43.3133603,-2.6800113,'https://eu.wikipedia.org/wiki/Gernikako_Arbola');
