INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156246,'25227','Mare de Déu de Far','iglesia','monumentos_osm','La Mare de Déu de Fa és una ermita del poble d''Espui, en el terme municipal de la Torre de Cabdella, del Pallars Jussà. Està situada a considerable alçada en un contrafort oriental del Tossal de la Collada Gran, damunt de la vall del Flamisell.',42.4462926,0.9838214,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Far');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156247,'25227','Sant Andreu','iglesia','monumentos_osm','Sant Andreu d''Astell és l''església parroquial, d''origen romànic, del poble d''Astell, en el terme municipal de la Torre de Cabdella a la comarca del Pallars Jussà. Està situada a la part més alta del poble, prop de la carretera.',42.4033942,0.9649585,'https://ca.wikipedia.org/wiki/Sant_Andreu_d''Astell');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156248,'25227','Sant Cristau','iglesia','monumentos_osm','L''ermita de sant Cristòfol o de sant Cristau està situada al serrat de les Cabanes, a uns 500 metres del poble d''Obeix, al terme municipal de la Torre de Cabdella, a la comarca del Pallars Jussà.',42.3950563,0.9553312,'https://ca.wikipedia.org/wiki/Sant_Cristòfol_d''Obeix');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156249,'25227','Sant Joan Baptista','iglesia','monumentos_osm','Sant Joan Baptista de Guiró és en el terme municipal de la Torre de Cabdella a la comarca del Pallars Jussà, en el poble de Aguiró. L''església de Sant Joan d''Idiro està documentada aparentment des del 986, però en uns documents falsos que en realitat pertanyen a la darreria del segle xi.',42.398379,0.9427056,'https://ca.wikipedia.org/wiki/Sant_Joan_Baptista_de_Guiró');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156250,'25227','Sant Julià','iglesia','monumentos_osm','Sant Julià d''Espui, o del Puig de Cabdella és l''església parroquial romànica del poble d''Espui, en el terme municipal de la Torre de Cabdella a la comarca del Pallars Jussà. Està documentada des del 1178, sovint amb l''expressió llatina podii Capdele (del puig de Cabdella).',42.4551282,0.9881127,'https://ca.wikipedia.org/wiki/Sant_Julià_d''Espui');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156251,'28509','Parroquia San Pedro Mártir (Padres Dominicos)','iglesia','monumentos_osm','La iglesia de San Pedro Mártir es un templo católico de la ciudad española de Madrid, obra del arquitecto Miguel Fisac. Forma parte del conjunto de edificios denominado convento, teologado e iglesia de San Pedro Mártir.',40.5023978,-3.6584981,'https://es.wikipedia.org/wiki/Iglesia_de_San_Pedro_Mártir_(Madrid)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156252,'28509','Santuario de Nuestra Señora de Valverde','iglesia','monumentos_osm','El santuario de Nuestra Señora de Valverde es un conjunto monumental situado en el distrito de Fuencarral-El Pardo de la villa de Madrid. Se encuentra en el km 12 de la carretera de Colmenar Viejo (antigua carretera de Francia).',40.5158745,-3.6862782,'https://es.wikipedia.org/wiki/Santuario_de_Nuestra_Señora_de_Valverde');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(156253,'28509','Fuente del Saceral','monumento','monumentos_osm','Monumento en Fuencarral (Madrid).',40.4971575,-3.7132087);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(156254,'28509','Hórreo','monumento','monumentos_osm','Monumento en Fuencarral (Madrid).',40.4867828,-3.7156609);
