INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156259,'07040','Ca n''Oleo','palacio','monumentos_osm','Can Oleo és una casa senyorial de Palma d''origen gòtic. Actualment l''edifici és propietat de la Universitat de les Illes Balears, que ho ha cedit al Govern per 20 anys.',39.5687433,2.6496068,'https://ca.wikipedia.org/wiki/Can_Oleo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156260,'07040','Can Catlar','palacio','monumentos_osm','Can Catlar és una casa senyorial situada al núm. 7 del carrer del Sol de Palma.',39.5682223,2.6524829,'https://ca.wikipedia.org/wiki/Can_Catlar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156261,'07040','El Temple','iglesia','monumentos_osm','El Temple, dit també Castell del Temple i, antigament, Almudaina de Gomera o Almudaina Gumara, és una antiga fortificació islàmica de la ciutat de Mallorca que després de la Conquesta Catalana passà a l''Orde del Temple, de la qual rebé el nom. Fou bastida el segle xii, després de la croada pisano-catalana de 1114,…',39.5674659,2.6556818,'https://ca.wikipedia.org/wiki/Castell_del_Temple');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156262,'07040','La Seu','iglesia','monumentos_osm','La catedral-basílica de Santa María en Palma, también llamada catedral de Mallorca, es el principal edificio religioso de la isla de Mallorca. En mallorquín, se la conoce como La Seu (Seu o Seo es el nombre que reciben las catedrales en la Corona de Aragón).',39.5674863,2.6482571,'https://es.wikipedia.org/wiki/Catedral_de_Santa_María_de_Palma_de_Mallorca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156263,'07040','Sant Antoniet','iglesia','monumentos_osm','El convent de Sant Antoni de Viana, dit també de Sant Antoniet, és un edifici conventual de la ciutat de Mallorca situat al carrer de Sant Miquel. Va ser fundat el 1230, i pertanyia a l''orde dels antonians.',39.5736194,2.6523613,'https://ca.wikipedia.org/wiki/Convent_de_Sant_Antoni_de_Viana');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156264,'28514','Parroquia Santa María de la Antigua','iglesia','monumentos_osm','La iglesia parroquial de Santa María la Antigua es la iglesia parroquial del distrito de Vicálvaro en Madrid. Se encuentra situada dentro del Casco Histórico de Vicálvaro en la calle Virgen de la Antigua, 9 (28032, Madrid).',40.4013957,-3.6048982,'https://es.wikipedia.org/wiki/Parroquia_de_Santa_María_la_Antigua');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156265,'28514','Parroquia de San Carlos Borromeo','iglesia','monumentos_osm','El centro pastoral San Carlos Borromeo es un templo católico en España que se encuentra en el barrio madrileño de Entrevías. Funcionó como parroquia hasta 2007, y actualmente está constituida en centro pastoral.',40.3829445,-3.6698789,'https://es.wikipedia.org/wiki/Centro_Pastoral_San_Carlos_Borromeo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156266,'28514','Parroquia de San Pedro ad Víncula','iglesia','monumentos_osm','La iglesia de San Pedro ad Víncula se encuentra en Madrid, emplazada en el extremo norte del barrio administrativo Casco histórico de Villa de Vallecas, en el antiguo pueblo de Vallecas, en la calle de Sierra Gorda, con vuelta a la plaza de Juan Malasaña, del distrito de Villa de Vallecas. La iglesia fue diseñada…',40.3804549,-3.6203894,'https://es.wikipedia.org/wiki/Iglesia_de_San_Pedro_ad_Víncula_(Vallecas)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156267,'28514','Templo de Madrid de la Iglesia de Jesucristo de los Santos de los Últimos Días','iglesia','monumentos_osm','El Templo de Madrid es uno de los templos construidos y operados por la Iglesia de Jesucristo de los Santos de los Últimos Días. Fue el 56.º templo construido por esta organización, y el primero de España, ubicado en su capital, Madrid.',40.40012,-3.6315382,'https://es.wikipedia.org/wiki/Templo_de_Madrid_(España)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(156268,'28514','Cabeza Olmeca','monumento','monumentos_osm','Monumento en Vallecas (Madrid).',40.3708958,-3.6274064);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156269,'12001','Catedral de la Asunción','iglesia','monumentos_osm','La catedral de Ceuta se encuentra situada en el espacio conocido desde época portuguesa como «La Ciudad», en un promontorio al sudeste de la zona interfosos y fue construida sobre una mezquita de la época de dominación árabe (711-1415). Durante el sitio de los 30 años fue hospital de sangre.',35.8878148,-5.3165945,'https://es.wikipedia.org/wiki/Catedral_de_la_Asunción_(Ceuta)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156270,'12001','Ermita de San Antonio','iglesia','monumentos_osm','La ermita de San Antonio Tojal es un edificio religioso consagrado a San Antonio de Padua. Se encuentra ubicado en el monte Hacho, en la Ciudad Autónoma de Ceuta (España).',35.8996449,-5.2938397,'https://es.wikipedia.org/wiki/Ermita_de_San_Antonio_(Ceuta)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156271,'12001','Fuerte Principe Alfonso','monumento','monumentos_osm','El Fuerte del Príncipe Alfonso es uno de los Fuertes Neomedievales del siglo XIX construidos para asegurar el linde fronterizo. Está situada en el Barrio del Príncipe de la ciudad española de Ceuta.',35.8779488,-5.3483989,'https://es.wikipedia.org/wiki/Fuerte_del_Príncipe_Alfonso');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156272,'12001','Iglesia de los Remedios','iglesia','monumentos_osm','La Iglesia de Santa María de los Remedios es una iglesia de la ciudad española de Ceuta. Se encuentra en la Calle Real, en la Península de La Almina, y es un Bien de Interés Cultural.',35.8883585,-5.3059701,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_los_Remedios_(Ceuta)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156273,'12001','Mezquita Muley El Mehdi','iglesia','monumentos_osm','La Mezquita de Muley El Medhi, también conocida cómo Mezquita Yemalquivir es una mezquita de la Ampliación de Ceuta de la ciudad española de Ceuta, ubicada en la Avenida de África.',35.8854313,-5.3247107,'https://es.wikipedia.org/wiki/Mezquita_Muley_El-Mehdi');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(156274,'11022','Baluarte de San Benito','monumento','monumentos_osm','Monumento en La Línea de la Concepción (Cádiz).',36.1604019,-5.3420199);
