INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156281,'20079','Frantzizkotarren eliza','iglesia','monumentos_osm','San Joan Bataiatzailearen komentua frantziskotar komentua da, Gipuzkoako Urola Kosta eskualdeko Zarautz udalerrian dagoena. 1964an Gipuzkoako kultura ondasuna izendatua izan zen.',43.2861554,-2.1733718,'https://eu.wikipedia.org/wiki/San_Joan_Bataiatzailearen_komentua_(Zarautz)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156282,'20079','Klarisen konbentua','iglesia','monumentos_osm','Santa Klara komentua Zarauzko eraikin nabarmenenetakoa da, Azken Portu auzoan kokatua dago. 1610ean sortu zuten eta gaur egun hutsik dago.',43.2838744,-2.1729063,'https://eu.wikipedia.org/wiki/Santa_Klara_komentua_(Zarautz)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156283,'20079','Narros Jauregia','palacio','monumentos_osm','El palacio de Narros, también llamado palacio de los Zarauz, está ubicado en la entrada oeste de la localidad guipuzcoana de Zarauz (Guipúzcoa), España. Está situado frente a la iglesia de Santa María la Real.',43.2871449,-2.1773181,'https://es.wikipedia.org/wiki/Palacio_de_Narros');
