INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156287,'08231','Sant Bartomeu i Santa Tecla','iglesia','monumentos_osm','Sant Bartomeu i Santa Tecla és una església parroquial del segle xvii amb nombroses modificacions posteriors a Sitges. La figura asimètrica, en un turó que presideix la platja és una de les imatges més característiques de la vila.',41.2346724,1.8116283,'https://ca.wikipedia.org/wiki/Sant_Bartomeu_i_Santa_Tecla');
