INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156294,'20064','San Frantzisko Xabier eliza','iglesia','monumentos_osm','San Frantzisko Xabier eliza (Donostia) 1980an eraikitako eliza da, Donostiako Bidebieta auzoko parrokia. Eraikuntza soila eta minimalista da, bere zorroztasunagatik eta funtzionalismoagatik arreta erakartzen duena.',43.3230152,-1.9433958,'https://eu.wikipedia.org/wiki/San_Frantzisko_Xabier_Eliza_(Donostia)');
