INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156299,'38049','Hautacuperche','monumento','monumentos_osm','Hautacuperche fue un guerrero aborigen gomero, protagonista de la conocida como «rebelión de los Gomeros» de 1488, así como ejecutor de Hernán Peraza el Joven, señor territorial de la isla.​​​​',28.0885944,-17.3393168,'https://es.wikipedia.org/wiki/Hautacuperche');
