INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156301,'12135','Ermita de Santa Quitèria','iglesia','monumentos_osm','L''Ermita de Santa Quitèria d''Almassora (Plana Alta) s''ubica a quatre km de l''esmentat terme municipal. Es troba aigües amunt i a l''esquerra del riu Millars i molt a prop del pont que duu el seu nom (Pont de Santa Quitèria).',39.9546669,-0.0950711,'https://ca.wikipedia.org/wiki/Ermita_de_Santa_Quitèria_d''Almassora');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156302,'12135','Ermitori de la Mare de Déu de Gràcia','iglesia','monumentos_osm','El Ermitorio de Nuestra Señora de Gracia, situado en el municipio de Villarreal (Provincia de Castellón, España), es un edificio representativo de la arquitectura popular mediterránea. Alberga, junto a una importante muestra de azulejería medieval, renacentista y barroca y un museo etnológico, un gabinete de…',39.9617941,-0.1162496,'https://es.wikipedia.org/wiki/Ermitorio_de_la_Virgen_de_Gracia');
