INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156309,'28510','Iglesia de San Matías','iglesia','monumentos_osm','La iglesia parroquial de San Matías es un templo católico de la ciudad de Madrid localizado en el distrito de Hortaleza. Se trata de uno de los primeros ejemplos de arquitectura neomudéjar.',40.4727748,-3.6406102,'https://es.wikipedia.org/wiki/Iglesia_de_San_Matías_(Madrid)');
