INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156313,'17079','Basilica de Sant Feliu','iglesia','monumentos_osm','Sant Feliu o Sant Fèlix és una basílica al Barri Vell de Girona col·legiata originària dels primers temps del cristianisme. Acull els oficis de la Parròquia Major de Sant Feliu del Bisbat de Girona, dita així perquè aquest era el temple principal de Girona abans de la construcció de la catedral.',41.9879799,2.8248903,'https://ca.wikipedia.org/wiki/Església_de_Sant_Feliu_de_Girona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156314,'17079','Església del Sagrat Cor','iglesia','monumentos_osm','El Sagrat Cor de Girona és una església del municipi de Girona d''estil neogòtic de començaments del s. XX inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9818728,2.8242981,'https://ca.wikipedia.org/wiki/Sagrat_Cor_de_Girona');
