INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156318,'17199','Capella del Roser','iglesia','monumentos_osm','La Capella del Roser és una església de Torroella de Montgrí (Baix Empordà) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.0447645,3.122489,'https://ca.wikipedia.org/wiki/Capella_del_Roser_(Torroella_de_Montgrí)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156319,'17199','Ermita de Santa Caterina','iglesia','monumentos_osm','L''ermita de Santa Caterina és una ermita de dimensions moderades al terme municipal de Torroella de Montgrí. L''ermita queda amagada a l''interior de la vall de Santa Caterina, al nord de les muntanyes d''Ullà, Montgrí i Montplà.',42.0581233,3.13446,'https://ca.wikipedia.org/wiki/Ermita_de_Santa_Caterina_(Torroella_de_Montgrí)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156320,'17199','Església de Sant Genís','iglesia','monumentos_osm','L''Església de Sant Genís és l''església parroquial de Torroella de Montgrí. És un dels edificis més voluminosos de la vil·la i destaca en la llunyania quan hom s''apropa a la vila essent visible des de bona part de la plana del Ter i un dels trets més característics del panorama de la vila.',42.0435848,3.1261698,'https://ca.wikipedia.org/wiki/Església_de_Sant_Genís_(Torroella_de_Montgrí)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156321,'17199','Santa Anna','iglesia','monumentos_osm','Santa Anna és una església parroquial al poble de l''Estartit, integrat a construccions annexes. L''església parroquial de Santa Anna, que ja existia anteriorment, va ser reconstruïda i eixamplada l''any 1920, segons consta a una placa de la façana, on s''indica que fou costejada pels familiars de Pere Coll i Rigau…',42.0554161,3.1991654,'https://ca.wikipedia.org/wiki/Santa_Anna_(l''Estartit)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156322,'17199','Santa Maria del Mar','iglesia','monumentos_osm','Santa Maria del Mar o Santa Maria dels Masos, antigament Santa Maria del Càrcer, és una ermita al municipi de Torroella de Montgrí (Baix Empordà). Està adossada a un mas inclòs actualment a l''interior de les instal·lacions d''un càmping en un planell a la falda sud del Torre Moratxa i el Tossal Gros.',42.0506704,3.1778956,'https://ca.wikipedia.org/wiki/Santa_Maria_dels_Masos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156323,'25120','Capella de la Sang','iglesia','monumentos_osm','La Capella de la Sang és un monument de la ciutat de Lleida protegit com a bé cultural d''interès nacional, en la categoria de Monument Històric.',41.6117703,0.6211277,'https://ca.wikipedia.org/wiki/Capella_de_la_Sang_(Lleida)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156324,'25120','Capella del Peu del Romeu','iglesia','monumentos_osm','La Capella de Sant Jaume o Peu del Romeu és un monument de la ciutat de Lleida protegit com a bé cultural d''interès nacional, en la categoria de monument històric. Es troba just a la cantonada entre els carrers Major i Cavallers.',41.6134514,0.6246555,'https://ca.wikipedia.org/wiki/Capella_de_Sant_Jaume_(Lleida)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156325,'25120','Catedral Nova','iglesia','monumentos_osm','La Catedral Nova de Lleida o Seu Nova és l''actual seu del Bisbat de Lleida. Se situa al bell mig de la ciutat, davant de l’Antic Hospital de Santa Maria, actual seu de l''Institut d''Estudis Ilerdencs.',41.6132316,0.6229413,'https://ca.wikipedia.org/wiki/Catedral_Nova_de_Lleida');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156326,'25120','Església de Sant Llorenç','iglesia','monumentos_osm','L''Església de Sant Llorenç de Lleida és una església de Lleida, d''estil romànic datada al segle xii, però amb ampliacions i acabaments gòtics. És la segona en importància de la ciutat després de la seu vella.',41.6143754,0.6215454,'https://ca.wikipedia.org/wiki/Església_de_Sant_Llorenç_de_Lleida');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156327,'25120','Església de Sant Martí','iglesia','monumentos_osm','L''església de Sant Martí és un temple catòlic d''estil romànic al nucli antic de la ciutat de Lleida. L''agost de 2016 va ser declarada bé cultural d''interès nacional, en la categoria de monument històric, a la vegada que la capella de Sant Jaume.',41.6177571,0.622056,'https://ca.wikipedia.org/wiki/Església_de_Sant_Martí_(Lleida)');
