INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156359,'07064','Església de Sant Josep','iglesia','monumentos_osm','L''Església de Sant Josep de Maó fou construïda l''any 1738 per la comunitat de mestres de cases, fusters i calefactors, dedicada a Sant Josep. És un edifici d''estil molt senzill, de nau única, amb petites capelles a cada banda.',39.8873844,4.2620527,'https://ca.wikipedia.org/wiki/Església_de_Sant_Josep_de_Maó');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156360,'07064','Església de Santa Eulàlia','iglesia','monumentos_osm','L''Església de Santa Eulàlia de Maó fou construïda entre 1879 i 1881. És un edifici de gran qualitat de llum; té una decoració de mosaics, però la resta és més senzilla.',39.8853375,4.2666537,'https://ca.wikipedia.org/wiki/Església_de_Santa_Eulàlia_de_Maó');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156361,'07064','Església de Santa Maria','iglesia','monumentos_osm','L''Església de Santa Maria és un temple catòlic de la ciutat de Maó, a les Illes Balears, dedicada a Santa Maria. A mitjan segle xiv s''hi va construir un primer temple, d''estil gòtic però de dimensions més reduïdes.',39.8894075,4.2647122,'https://ca.wikipedia.org/wiki/Església_de_Santa_Maria_de_Maó');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(156362,'07064','Es Molí Vell','monumento','monumentos_osm','Monumento en Villacarlos (Islas Baleares).',39.8806125,4.2837526);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(156363,'07064','Pont de Sant Roc','monumento','monumentos_osm','Monumento en Villacarlos (Islas Baleares).',39.8894821,4.2626833);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156364,'25086','Ermita de Sant Beado','iglesia','monumentos_osm','Sant Beado, de vegades esmentat com a Sant Beat, és una ermita romànica del terme municipal de la Guingueta d''Àneu, a la comarca del Pallars Sobirà. Pertany al territori de l''antic terme d''Unarre.',42.6595522,1.1556789,'https://ca.wikipedia.org/wiki/Sant_Beado');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156365,'25086','Església de Sant Esteve','iglesia','monumentos_osm','Sant Esteve de Gavàs és l''església parroquial romànica del poble de Gavàs, en el terme municipal de la Guingueta d''Àneu, a la comarca del Pallars Sobirà. Pertany al territori de l''antic terme d''Unarre.',42.6411953,1.1603283,'https://ca.wikipedia.org/wiki/Sant_Esteve_de_Gavàs');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156366,'25086','Església de Sant Serni','iglesia','monumentos_osm','Sant Serni de Cerbi és l''església parroquial romànica del poble de Cerbi, en el terme municipal de la Guingueta d''Àneu, a la comarca del Pallars Sobirà. Està situada a dins del nucli de població, en el seu sector oriental, i pertanyia al territori de l''antic terme d''Unarre.',42.6470191,1.1494655,'https://ca.wikipedia.org/wiki/Sant_Serni_de_Cerbi');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156367,'25086','Pont romànic','monumento','monumentos_osm','El Pont d''Esterri és un pont romànic del terme municipal d''Esterri d''Àneu, a la comarca del Pallars Sobirà. Està situat al bell mig de la població esmentada.',42.628053,1.123511,'https://ca.wikipedia.org/wiki/Pont_d''Esterri');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156368,'25086','Sant Joan','iglesia','monumentos_osm','Sant Joan de Burgo és l''església parroquial del poble de Burgo, en el terme municipal de la Guingueta d''Àneu, a la comarca del Pallars Sobirà. Pertany al territori de l''antic terme d''Unarre.',42.6159002,1.1522969,'https://ca.wikipedia.org/wiki/Sant_Joan_de_Burgo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156369,'09432','Iglesia de San Lorenzo','iglesia','monumentos_osm','La iglesia de San Lorenzo de Villafruela es un templo de culto cristiano de estilo gótico emplazado en la Calle San Lorenzo de Villafruela, provincia de Burgos, España. La fiesta en honor al patrón de la iglesia se celebra el 10 de agosto.',41.9186155,-3.9124985,'https://es.wikipedia.org/wiki/Iglesia_de_San_Lorenzo_(Villafruela)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(156370,'09432','Puerta de Odón','monumento','monumentos_osm','Puerta monumental en Villafruela (Burgos).',41.918824,-3.9120296);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156371,'14040','Ermita Madre de Dios','iglesia','monumentos_osm','La ermita de la Madre de Dios es una ermita situada en Montalbán de Córdoba (España) declarada monumento histórico-artístico el 9 de abril de 1981​ y Patrimonio Histórico Andaluz el 3 de julio de 1996.​',37.5790413,-4.7513339,'https://es.wikipedia.org/wiki/Ermita_de_la_Madre_de_Dios_(Montalbán_de_Córdoba)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(156372,'14040','Cruz del Calvario','monumento','monumentos_osm','Monumento en Montalbán de Córdoba (Córdoba).',37.5781616,-4.7519561);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156373,'15058','Che Guevara','monumento','monumentos_osm','A Estatua de Che Guevara en Oleiros é unha homenaxe ao Che Guevara na avenida que leva o seu nome en Oleiros, na rotonda á altura do parque de Nirvana, preto da praia de Bastiagueiro. A estatua está baseada na famosa fotografía Guerrillero Heroico de Alberto Korda.',43.3414101,-8.3694072,'https://gl.wikipedia.org/wiki/Estatua_de_Che_Guevara_en_Oleiros');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156374,'15058','Pazo de Lóngora','palacio','monumentos_osm','O Pazo de Lóngora é un pazo situado no lugar de Lóngora, da parroquia de Liáns do concello de Oleiros. Este pazo foi a residencia do matrimonio composto polo músico e compositor Marcial del Adalid e a escritora Francisca González Garrido (máis coñecida como Fanny Garrido).',43.3362672,-8.3520546,'https://gl.wikipedia.org/wiki/Pazo_de_Lóngora');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(156375,'15058','Pazo de Fontes','palacio','monumentos_osm','Casa señorial en Oleiros (A Coruña).',43.317545,-8.3170965);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(156376,'15058','Torre de Lorbé','monumento','monumentos_osm','Monumento en Oleiros (A Coruña).',43.3899749,-8.3077901);
