INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156380,'17095','Ermita de Santa Cristina','iglesia','monumentos_osm','L''Ermita de Santa Cristina està situada a 3,5 km del centre de la Vila de Lloret de Mar, sobre un monticle que domina la Platja de Santa Cristina. És una obra del municipi de Lloret de Mar (Selva) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.6878533,2.8162258,'https://ca.wikipedia.org/wiki/Ermita_de_Santa_Cristina');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156381,'17095','Mare de Déu de les Alegries','iglesia','monumentos_osm','El Santuari de la Mare de Déu de les Alegries va ser la primera parròquia de la vila de Lloret de Mar. Va ser parròquia de la vila des que va ser consagrada, el 1079, fins al 1522, quan es va inaugurar una nova parròquia a prop de la platja.',41.7175424,2.8295507,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_les_Alegries');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156382,'17095','Sant Romà','iglesia','monumentos_osm','Sant Romà de Lloret és una església del municipi de Lloret de Mar (Selva) que forma part de l''Inventari del Patrimoni Arquitectònic de Catalunya. La parròquia de Sant Romà està adscrita al Bisbat de Girona.',41.699686,2.8475319,'https://ca.wikipedia.org/wiki/Sant_Romà_de_Lloret_de_Mar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156383,'17095','l''Àngel','monumento','monumentos_osm','El Monument de l''Àngel és un grup escultòric del municipi de Lloret de Mar (Selva) que forma part de l''Inventari del Patrimoni Arquitectònic de Catalunya. Es troba emplaçat sobre una terrassa circular, amb escales obertes als quatre punts cardinals.',41.711371,2.8120329,'https://ca.wikipedia.org/wiki/Monument_de_l''Àngel');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(156384,'17095','Ca la Mare-no-ho-vol','palacio','monumentos_osm','Casa señorial en Lloret de Mar (Girona).',41.709587,2.8299599);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156385,'45121','Convento de Santa Catalina de Siena','iglesia','monumentos_osm','El convento de Santa Catalina de Siena, de estilo renacentista, es el tercero de religiosas coetáneo en Ocaña, erigido el 8 de junio de 1571 por Catalina de Guzmán y Vargas (viuda del insigne capitán Juan Maldonado, e hija de Manuel de Guzmán e Inés de Vargas), por registro, ante Juan Pérez del Hoyo, haciendo una…',39.9612192,-3.4940536,'https://es.wikipedia.org/wiki/Convento_de_Santa_Catalina_de_Siena_(Ocaña)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(156386,'45121','Fuente Grande','monumento','monumentos_osm','Monumento en Ocaña (Toledo).',39.9623683,-3.5009232);
