INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156390,'46194','Església de Sant Cristòfol','iglesia','monumentos_osm','L''església parroquial de Sant Cristòfol Màrtir o també Església de Sant Cristòfol és un temple catòlic situat a carrer Constitució, 3, en el municipi de Picassent. És Bé de Rellevància Local amb identificador nombre 46.16.194-001 segons la Disposició Addicional Quinta de la Llei 5/2007, de 9 de febrer, de la…',39.3623507,-0.4577596,'https://ca.wikipedia.org/wiki/Església_de_Sant_Cristòfol_de_Picassent');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156391,'46194','Església de la Miraculosa','iglesia','monumentos_osm','L''Església Parroquial de La Miraculosa és un temple catòlic situat en el municipi de Picassent. És Bé de Rellevància Local amb identificador nombre 46.16.194-008.',39.3608681,-0.4618726,'https://ca.wikipedia.org/wiki/Església_de_la_Miraculosa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(156392,'46194','Puente Barranco Picassent (2ª mitad s. XIX)','monumento','monumentos_osm','Monumento en Picasent (Valencia).',39.3611834,-0.455817);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156393,'17181','Església de Santa Cristina d''Aro','iglesia','monumentos_osm','L''església de Santa Cristina d''Aro està situada al peu de les Gavarres, dalt d''un pujol, a la part més alta del poble de Santa Cristina d''Aro. És un temple d''origen medieval, de notables proporcions i modificat en diverses ocasions, encara que l''arrebossat de calç que cobreix totalment l''exterior i l''interior…',41.8156464,3.0034618,'https://ca.wikipedia.org/wiki/Església_de_Santa_Cristina_d''Aro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156394,'17181','Sant Ampèlit','iglesia','monumentos_osm','Sant Ampèlit és una capella dedicada al culte de Sant Empèlit al veïnat de Panedes al terme municipal de Llagostera. Fins fa poc anys funcionava la rectoria existent al costat del temple.',41.839426,2.9526809,'https://ca.wikipedia.org/wiki/Sant_Ampèlit');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156395,'17181','Sant Martí de Romanyá','iglesia','monumentos_osm','Sant Martí de Romanyà és l''església parroquial de l''entitat de població de Romanyà de la Selva, al municipi baixempordanès de Santa Cristina d''Aro, dedicada a l''advocació de Sant Martí de Tours. És un monument protegit i inventariat dins el Patrimoni Arquitectònic Català.',41.8536977,2.9843909,'https://ca.wikipedia.org/wiki/Sant_Martí_de_Romanyà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156396,'17181','Santa Agnès de Solius','iglesia','monumentos_osm','El monestir de Santa Maria de Solius i l''església de Santa Agnès de Solius són un conjunt d''edificis del poble de Solius, al municipi de Santa Cristina d''Aro (Baix Empordà), que forma part de l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.8149231,2.9618459,'https://ca.wikipedia.org/wiki/Santa_Agnès_de_Solius');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156397,'17181','Santa Maria de Solius','monumento','monumentos_osm','El monestir de Santa Maria de Solius i l''església de Santa Agnès de Solius són un conjunt d''edificis del poble de Solius, al municipi de Santa Cristina d''Aro (Baix Empordà), que forma part de l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.8147019,2.9622475,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Solius');
