INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156405,'25103','Església de Sant Salvador','iglesia','monumentos_osm','Sant Salvador de Granyanella és una església de Granyanella (Segarra) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.6488509,1.2245367,'https://ca.wikipedia.org/wiki/Sant_Salvador_de_Granyanella');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156406,'25103','Sant Jaume','iglesia','monumentos_osm','Sant Jaume del Canós és l''església parroquial del Canós, al municipi dels Plans de Sió (Segarra), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.6885822,1.2057201,'https://ca.wikipedia.org/wiki/Sant_Jaume_del_Canós');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156407,'25103','Sant Jaume de la Móra','iglesia','monumentos_osm','Sant Jaume de la Móra és una església a l''entrada del poble de la Móra, al costat de l''antic fossar, al municipi de Granyanella (Segarra), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. L''indret on és aquesta església apareix documentat des del 1120.',41.6508358,1.1931643,'https://ca.wikipedia.org/wiki/Sant_Jaume_de_la_Móra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156408,'25103','Sant Pau','iglesia','monumentos_osm','Sant Pau és una església barroca al poble de Tordera al municipi de Granyanella (la Segarra) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. L''actual església de Tordera es construí durant la segona meitat del segle xviii damunt una antiga capella.',41.679518,1.2227851,'https://ca.wikipedia.org/wiki/Sant_Pau_de_Tordera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156409,'25103','Sant Pere','iglesia','monumentos_osm','Sant Pere és l''església parroquial del poble de la de la Curullada al municipi de Granyanella (la Segarra) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. És dalt d''un turó al costat de les restes del Castell de la Curullada.',41.6659223,1.2270747,'https://ca.wikipedia.org/wiki/Sant_Pere_de_la_Curullada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(156410,'28051','El Bombo','monumento','monumentos_osm','Monumento en Chapinería (Madrid).',40.3772508,-4.2120434);
