INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156413,'17050','Capella de Sant Llorenç de Perles','iglesia','monumentos_osm','Sant Llorenç de Perles és una capella romànica ubicada al veïnat de Perles, a prop del poble de Vilafreser, dins del municipi de Vilademuls (Pla de l''Estany). La capella conserva la porta d''entrada i l''absis exterior del segle XII. Es troba al darrere de la casa de can Pagès.',42.0793036,2.8722541,'https://ca.wikipedia.org/wiki/Sant_Llorenç_de_Perles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156414,'17050','Sant Genís','iglesia','monumentos_osm','Sant Genís és l''església parroquial de Cervià de Ter (Gironès) datada del XI apareix citada en l''acta de fundació del monestir de Cervià de Ter. Té una inscripció gravada en el frontó de la porta que revela el seu origen reculat i que diu així: "Esta parroquial iglesia es tant antiga que no se ha trobat nota alguna…',42.0676854,2.9100462,'https://ca.wikipedia.org/wiki/Sant_Genís_de_Cervià');
