INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156417,'23038','Antiguo Convento de Santo Domingo','monumento','monumentos_osm','La iglesia parroquial de Nuestra Señora de la Asunción y el antiguo convento de Santa María Magdalena de la Cruz forman parte del único conjunto que constituyó el convento fundado por la Orden de Santo Domingo en la localidad de La Guardia de Jaén en la provincia de Jaén (Andalucía, España). Sus obras se iniciaron…',37.7448429,-3.6937356,'https://es.wikipedia.org/wiki/Antiguo_convento_de_Santo_Domingo_de_La_Guardia_de_Jaén');
