INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156426,'43047','Aqüeducte de les Ferreres','monumento','monumentos_osm','El Pont del Diable (també anomenat Aqüeducte de les Ferreres) és un pont aqüeducte romà aixecat entre els costats del barranc dels Arcs al terme de Tarragona, que duia aigua del riu Francolí a l''antiga ciutat de Tàrragona. És un dels aqüeductes més monumentals i ben conservats de l''època romana i el més important…',41.1459284,1.2438975,'https://ca.wikipedia.org/wiki/Aqüeducte_de_les_Ferreres');
