INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156478,'90876','Pont d''en Pere Curt','monumento','monumentos_osm','El pont d''en Pere Curt o pont de Peu de Costa és un pont entre els municipis d''Aiguafreda (Osona) i Tagamanent (Vallès Oriental) que forma part de l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7705556,2.2725,'https://ca.wikipedia.org/wiki/Pont_d''en_Pere_Curt');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156479,'90876','Pont d''en Picamena','monumento','monumentos_osm','El Pont d''en Picamena és una obra del municipi d''Aiguafreda (Osona) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. És un pont d''un sol arc de pedra i maons, pla.',41.7888889,2.2891667,'https://ca.wikipedia.org/wiki/Pont_d''en_Picamena');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156480,'90876','Sant Martí del Congost','iglesia','monumentos_osm','Sant Martí del Congost o Església d''Aiguafreda de Dalt és una església del municipi d''Aiguafreda (Osona) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. La seva consagració, promoguda per l''abadessa Emma, filla del comte Guifré el Pelós, la va dur a terme el bisbe Gotmar de Vic el dia 5 d''agost del…',41.7886281,2.2574739,'https://ca.wikipedia.org/wiki/Sant_Martí_del_Congost');
