INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156484,'08279','Can Casanoves','palacio','monumentos_osm','Can Casanovas és una masia de Terrassa (Vallès Occidental) protegida com a bé cultural d''interès local. El cos principal té la coberta a dues aigües amb el carener paral·lel a la façana.',41.5409635,2.0255171,'https://ca.wikipedia.org/wiki/Can_Casanovas_(Terrassa)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156485,'08279','Can Guitard de la Riera','palacio','monumentos_osm','Can Guitard de la Riera és una masia del municipi de Terrassa, protegida com a bé cultural d''interès local. Està situada al sud de la ciutat, entre la riera del Palau, a l''est, i la via del ferrocarril de la línia Barcelona-Vallès de FGC, a l''oest.',41.5365033,2.0240185,'https://ca.wikipedia.org/wiki/Can_Guitard_de_la_Riera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156486,'08279','Catedral del Sant Esperit','iglesia','monumentos_osm','La catedral de Terrassa o basílica del Sant Esperit és un edifici religiós situat a la plaça Vella de Terrassa i dedicat al Sant Esperit. L''any 2004 el Vaticà va crear el nou bisbat de Terrassa, com a segregació del bisbat de Barcelona, i va decidir fer servir la basílica del Sant Esperit com a nova catedral.',41.5621292,2.0119501,'https://ca.wikipedia.org/wiki/Catedral_de_Terrassa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156487,'08279','Convent de les Germanes Josefines','iglesia','monumentos_osm','El convent de les Germanes Josefines, també conegut com la Casa del Malalt, és un edifici del municipi de Terrassa (Vallès Occidental), situat al barri de la Cogullada, protegit com a bé cultural d''interès local.',41.5553213,2.0060243,'https://ca.wikipedia.org/wiki/Convent_de_les_Germanes_Josefines_(Terrassa)');
