INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156489,'43129','Església de Sant Jaume','iglesia','monumentos_osm','Sant Jaume de Riudoms és una església de la vila de Riudoms (el Baix Camp) dedicada a Sant Jaume el Major. Adjudicada erròniament a Pere Blai, la traça fou dissenyada pels constructors de l''església d''Ulldemolins, dirigida pel mestre d''obres biscaí Joan Sans amb la col·laboració de Jaume Amigó.',41.13908,1.0511043,'https://ca.wikipedia.org/wiki/Sant_Jaume_de_Riudoms');
