INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156560,'17207','Sant Esteve','iglesia','monumentos_osm','Església parroquial de Sant Esteve d''en Bas és una església de la Vall d''en Bas (Garrotxa) protegida com a bé cultural d''interès local. L''església de Sant Esteve centra el poble del mateix nom, situat en un vessant de la muntanya de Murrià, sobre la vall d''en Bas.',42.1184746,2.4591714,'https://ca.wikipedia.org/wiki/Església_de_Sant_Esteve_d''en_Bas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156561,'17207','Sant Miquel de Castelló','iglesia','monumentos_osm','Sant Miquel de Castelló és una ermita al terme municipal de la Vall d''en Bas, a la comarca de la Garrotxa, justament al damunt del poble dels Hostalets d''en Bas. S''enlaira sobre un contrafort del Serrat de Sant Miquel dintre de la serra dels Llancers, als últims contraforts del nord-est del massís del Collsacabra.',42.1020702,2.4312739,'https://ca.wikipedia.org/wiki/Sant_Miquel_de_Castelló');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156562,'17207','Sant Pere de Falgars','iglesia','monumentos_osm','Sant Pere de Falgars és una església romànica situada en el petit nucli de Falgars d''en Bas, dins el terme municipal de la Vall d''en Bas (Garrotxa) protegida com a bé cultural d''interès local.',42.0858395,2.4385033,'https://ca.wikipedia.org/wiki/Sant_Pere_de_Falgars');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156563,'17207','Sant Quintí','iglesia','monumentos_osm','Sant Quintí és una església romànica del segle xiii amb modificacions al segle xviii que està situada al poble de Sant Esteve d''en Bas, que pertany al municipi de Vall d''en Bas (Garrotxa). És un monument protegit com a bé cultural d''interès local.',42.1163557,2.4418033,'https://ca.wikipedia.org/wiki/Sant_Quintí_d''en_Bas');
