INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156582,'27006','Catedral de Santa Maria d''Urgell','iglesia','monumentos_osm','La catedral de la Seu d''Urgell o de Santa Maria és un temple catòlic de la localitat homònima, declarat bé cultural d''interès nacional. És considerat com un exemplar únic dins el romànic català per les seves característiques italianitzants, altament visibles en l''ornamentació de la façana i la galeria oberta de la…',42.3577194,1.461987,'https://ca.wikipedia.org/wiki/Catedral_de_la_Seu_d''Urgell');
