INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156587,'23024','Castillo de Navas de Tolosa','monumento','monumentos_osm','El castillo de las Navas de Tolosa es una antigua fortificación española situada en el municipio de La Carolina, cerca de la población de Navas de Tolosa, en la provincia de Jaén, comunidad autónoma de Andalucía (España), visible desde la carretera N-IV, a la altura del kilómetro 265. Su denominación en las…',38.2994689,-3.5974883,'https://es.wikipedia.org/wiki/Castillo_de_las_Navas_de_Tolosa');
