INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156589,'08218','Església Vella de Sant Joan de Vilatorrada','iglesia','monumentos_osm','L''Església vella de Sant Joan de Vilatorrada és una església romànica del municipi de Sant Joan de Vilatorrada (Bages). Està situada dins el mas Sant Joan, un casal que hi ha dalt d''un puig a la riba dreta del Cardener a la part vella del poble.',41.742277,1.8028799,'https://ca.wikipedia.org/wiki/Església_vella_de_Sant_Joan_de_Vilatorrada');
