INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156591,'08218','Torre de Lluvià','palacio','monumentos_osm','La Vil·la Emília o Torre Lluvià és una casa senyorial, de caràcter residencial - rural, dissenyada per l''arquitecte Ignasi Oms i Ponsa l''any 1896. És una construcció modernista, catalogada com a bé cultural d''interès local del municipi del Manresa.',41.7251316,1.7896291,'https://ca.wikipedia.org/wiki/Torre_Lluvià');
