INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156594,'03119','Ermita de Santa Anna','iglesia','monumentos_osm','L''ermita de Santa Anna és un temple ubicat a la partida de Lloixa del terme municipal de Sant Joan d''Alacant (l''Alacantí, País Valencià). El seu origen es troba al segle xvi quan la família Salafranca erigeix un xicotet ermitori dins la seua finca.',38.4027313,-0.4453387,'https://ca.wikipedia.org/wiki/Ermita_de_Santa_Anna_(Sant_Joan_d''Alacant)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156595,'03119','Monolito en recuerdo de las victimas del campo de concentración de Los Almendros','monumento','monumentos_osm','El Campo de concentración de Los Almendros (también conocido como Campo de detención de Los Almendros o simplemente Campo de Los Almendros), fue un campo de concentración para militares y civiles al finalizar la guerra civil española creado por el bando sublevado dos días antes (30 de marzo de 1939) del último…',38.3573971,-0.4693176,'https://es.wikipedia.org/wiki/Campo_de_concentración_de_Los_Almendros');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156596,'03119','Torre de la Santa Faç','monumento','monumentos_osm','La Torre de Santa Faç és una torre-refugi situada en els voltants de l''Horta d''Alacant, en l''entitat de Santa Faç, pertanyent a la ciutat d''Alacant. Situada en la carretera d''Alacant en direcció a València, concretament en el quilòmetre 8.',38.3892715,-0.4427091,'https://ca.wikipedia.org/wiki/Torre_de_Santa_Faç');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156597,'03119','Torre de las Águilas','monumento','monumentos_osm','La torre de les Àguiles és una construcció defensiva situada al terme municipal d''Alacant (País Valencià) que es troba cap al nord, en direcció cap a la platja de Sant Joan fent cantonada entre els carrers Virgili i Horaci. Pertany al conjunt de torres de defensa de l''Horta d''Alacant.',38.368331,-0.4424478,'https://ca.wikipedia.org/wiki/Torre_de_les_Àguiles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156598,'03119','Torre del Xiprer','monumento','monumentos_osm','La Torre del Ciprer o Torre del Xiprer és una torre de defensa situada en el camí de la platja de Sant Joan, a Alacant. Va ser declarada Bé d''Interès Cultural en 1997.',38.3771668,-0.4307464,'https://ca.wikipedia.org/wiki/Torre_del_Ciprer');
