INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156664,'46013','Església de la Mare de Déu de l''Assumpció','iglesia','monumentos_osm','L''Església parroquial de l''Assumpció, sub invocatione Assumptionis Beatae Mariae Virginis, com era costum al S. XIII, és un temple catòlic situat a la plaça de la Constitució, 1, al municipi d''Alboraia. És un Bé de Rellevància Local amb identificador número 46.13.013-001.',39.5000675,-0.3497093,'https://ca.wikipedia.org/wiki/Església_parroquial_de_l''Assumpció_de_Nostra_Senyora_d''Alboraia');
