INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156669,'28507','Ermita de San Isidro','iglesia','monumentos_osm','La ermita de San Isidro (conocida también como ermita de San Isidro del Campo) es una ermita situada en el distrito de Carabanchel de la ciudad española de Madrid. Dedicada al santo patrón de la ciudad, Isidro Labrador (canonizado en 1622), se ubica en el paseo de la Ermita del Santo, al final del paseo del Quince…',40.4006292,-3.7258265,'https://es.wikipedia.org/wiki/Ermita_de_San_Isidro_(Madrid)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156670,'28507','Ermita de Santa María la Antigua','iglesia','monumentos_osm','La ermita de Santa María la Antigua, también conocida como ermita de Nuestra Señora de la Antigua o ermita del Cementerio de Carabanchel, es un templo católico situado en Carabanchel, uno de los veintiún distritos en los que se divide administrativamente la ciudad española de Madrid. Su origen se remonta al siglo…',40.3824224,-3.7525006,'https://es.wikipedia.org/wiki/Ermita_de_Santa_María_la_Antigua');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156671,'28507','Panteón Luisa Sancho Mata [Panteón Guirao]','monumento','monumentos_osm','El Panteón de Luisa Sancho Mata, más conocido como Panteón Guirao, es un mausoleo de estilo modernista situado en la Sacramental de San Isidro, en la ciudad española de Madrid, dentro del distrito de Carabanchel.',40.4007533,-3.7288467,'https://es.wikipedia.org/wiki/Panteón_Guirao');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156672,'28507','Puerta Bonita','monumento','monumentos_osm','La Puerta Bonita, cuyo antiguo nombre era el de Puerta de Madrid, era uno de los cuatro accesos que tenía la posesión real de la Finca de Vista Alegre en Madrid, también conocida como Finca de Salamanca. Debido a las parcelaciones para la edificación quedó aislada de la finca.',40.3864783,-3.7345634,'https://es.wikipedia.org/wiki/Puerta_Bonita');
