INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156679,'34180','Iglesia de San Hipólito el Real','iglesia','monumentos_osm','La iglesia de San Hipólito el Real, ​ es un templo católico situado en el municipio palentino de Támara de Campos. Se trata de un edificio de grandes proporciones, gótico del siglo XIV, con añadidos renacentistas y barrocos; presenta elementos decorativos propios de estos estilos.',42.2033067,-4.3930123,'https://es.wikipedia.org/wiki/Iglesia_de_San_Hipólito_el_Real_(Támara_de_Campos)');
