INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156724,'31256','Jauki','monumento','monumentos_osm','Jauki etxeko garaia edota Xauki etxeko garaia Nafarroa Garaiko Hiriberrin dagoen garai bat da. Izen bereko etxearen alboan dago, herriko sarreratik ezkerreko errepidea hartuz, Portal etxeko garaitik oso hurbil; biak ere herrigunearen ipar-mendebaldean daude.',42.9470017,-1.2312177,'https://eu.wikipedia.org/wiki/Jauki_etxeko_garaia');
