INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156785,'08046','Sant Julià del Fou','iglesia','monumentos_osm','Sant Julià del Fou, de vegades escrit com a forma antiga Sant Julià d''Alfou, és una parròquia del municipi de Sant Antoni de Vilamajor, a la comarca del Vallès Oriental (Baix Montseny), actualment envoltada per una urbanització que porta el seu nom. Té el cementiri a la banda de migdia i la rectoria al nord.',41.648201,2.3805118,'https://ca.wikipedia.org/wiki/Sant_Julià_del_Fou');
