INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156787,'90879','Mare de Déu de Fucimanya','iglesia','monumentos_osm','El Santuari de la Mare de Déu de Fucimanya (Fussimanya en versió antiga), és una església d''estil romànic del segle xii situada al municipi de Sallent (Bages). És un monument protegit i inventariat dins el Patrimoni Arquitectònic Català.',41.8217506,1.9439188,'https://ca.wikipedia.org/wiki/Santuari_de_la_Mare_de_Déu_de_Fucimanya');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156788,'90879','Santa Maria','iglesia','monumentos_osm','Santa Maria d''Artés és l''església parroquial d''Artés (Bages) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. És obra de Claudi Duran i Ventosa i de Josep Coll i Vilaclara.',41.7984945,1.9532825,'https://ca.wikipedia.org/wiki/Santa_Maria_d''Artés');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156789,'90879','Santa Maria d''Horta','iglesia','monumentos_osm','Santa Maria d''Horta és l''església parroquial del terme d''Horta (Avinyó), protegida com a bé cultural d''interès local. El territori de Santa Maria d''Horta o Horta, va ser un municipi des del 29 d''abril de 1636, que se separa del municipi d''Artés,fins al 25/12/1845, que passa a formar part del municipi d''Avinyó.',41.8255006,1.9684023,'https://ca.wikipedia.org/wiki/Santa_Maria_d''Horta');
