INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156881,'17080','Mare de Déu de Montgrony','iglesia','monumentos_osm','El santuari o capella de Santa Maria de Montgrony és un santuari marià del bisbat de Vic, situat al Montgrony. Es troba en el cingle de la serra de Sant Pere, a uns 1370 metres sobre el nivell del mar, en el municipi de Gombrèn, a la comarca catalana del Ripollès.',42.265654,2.0856468,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Montgrony');
