INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156883,'17080','Sant Joan de Mataplana','iglesia','monumentos_osm','Sant Joan de Mataplana és una església romànica del municipi de Gombrèn (Ripollès) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. Es troba a la vall de l''Espluga, isolada, davant de les restes del Castell de Mataplana, del qual n''era era la capella.',42.2620957,2.0613598,'https://ca.wikipedia.org/wiki/Sant_Joan_de_Mataplana');
