INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156901,'25215','Sant Llorenç','iglesia','monumentos_osm','Sant Llorenç de Sant Adrià és una capella romànica del poble de Sant Adrià, pertanyent a l''antic terme de Gurp de la Conca i a l''actual de Tremp. Era una capella depenent de la parroquial de Sant Adrià de Tendrui.',42.1890698,0.8353135,'https://ca.wikipedia.org/wiki/Sant_Llorenç_de_Sant_Adrià');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156902,'25215','Sant Martí','iglesia','monumentos_osm','Sant Martí de Gurp és una capella romànica del poble de Gurp, al municipi de Tremp. Està situada uns 200 metres al nord-est del poble, en un lloc de fàcil accés, ja que és el camí de Gurp a Sapeira, a prop de l''antic molí, al Forat del Toscar, i molt a prop del camí de Gurp a Santa Engràcia.',42.2286281,0.8534476,'https://ca.wikipedia.org/wiki/Sant_Martí_de_Gurp');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156903,'25215','Sant Miquel','iglesia','monumentos_osm','Sant Miquel de Gurp és una capella d''època romànica del poble de Gurp, en el municipi de Tremp. Està situada uns 2 quilòmetres al sud del poble, en un grup de bordes a prop de Montibarri.',42.2032574,0.8424329,'https://ca.wikipedia.org/wiki/Sant_Miquel_de_Gurp');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156904,'25215','Sant Sebastià','iglesia','monumentos_osm','Sant Sebastià de Talarn és una ermita de la vila de Talarn, pertanyent al terme d''aquest nom, del Pallars Jussà. Està situada al nord-oest de la vila i al sud-est de l''Acadèmia General Bàsica de Suboficials, dalt d''un turonet entre la llau dels Sabarissos (est) i la llau de les Maçanes (oest).',42.1895551,0.8850722,'https://ca.wikipedia.org/wiki/Sant_Sebastià_de_Talarn');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156905,'22039','Iglesia Parroquial de San Pedro Apóstol','iglesia','monumentos_osm','La iglesia de San Pedro, en Ayerbe (España), es una construcción de sillería, sillarejo, ladrillo y tapial que ofrece obra de varias épocas. Nave de cinco tramos y capilla mayor poligonal.',42.2747519,-0.6879907,'https://es.wikipedia.org/wiki/Iglesia_de_San_Pedro_(Ayerbe)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156906,'22039','Santuario de Nuestra Señora de Casbas','iglesia','monumentos_osm','El Santuario de Nuestra Señora de Casbas también conocido como Ermita de Nuestra Señora de Casbas se levanta en la población española de Ayerbe (Hoya de Huesca, provincia de Huesca, Aragón). El actual edificio se construyó a principios del siglo XVIII sobre una edificación anterior.',42.2517921,-0.7078668,'https://es.wikipedia.org/wiki/Santuario_de_Nuestra_Señora_de_Casbas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156907,'22039','Torre de San Pedro','iglesia','monumentos_osm','La torre de San Pedro, en Ayerbe, está situada al norte de la población, en una calleja sin salida. Es un edificio adosado a edificaciones particulares, alguna de las cuales son restos de la antigua iglesia; a principios del siglo XIX, con acuerdo afirmativo del Supremo Consejo de Castilla, tuvo que ser demolida…',42.2778151,-0.6891507,'https://es.wikipedia.org/wiki/Torre_de_San_Pedro_(Ayerbe)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156908,'22039','Palacio de los Marqueses de Urriés','palacio','monumentos_osm','El palacio de Ayerbe, también conocido como palacio de los Marqueses de Urriés, es un inmueble de la localidad española de Ayerbe, en la provincia de Huesca. Ejemplo de arquitectura civil aragonesa, forma parte del frente norte de la plaza que se configuró ante él.',42.276091,-0.6888782,'https://es.wikipedia.org/wiki/Palacio_de_Ayerbe');
