INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156958,'25126','Mare de Déu de Biuse','iglesia','monumentos_osm','La Mare de Déu de Biuse és una ermita de l''antic poble de Biuse, ara Bordes de Biuse, en el terme municipal de Llavorsí, a la comarca del Pallars Sobirà. Està situada a força alçada a l''esquerra de la Noguera Pallaresa, al nord-oest de la Torre de Biuse, restes del Castell de Biuse.',42.4755861,1.2128902,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Biuse');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156959,'25126','Sant Esteve','iglesia','monumentos_osm','Sant Esteve de Montenartró és l''església parroquial del poble de Montenartró, en el terme municipal de Llavorsí, a la comarca del Pallars Sobirà. És a l''entrada del poble des del nord-oest.',42.4497742,1.2257909,'https://ca.wikipedia.org/wiki/Sant_Esteve_de_Montenartró');
