INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(156987,'08138','Sant Andreu','iglesia','monumentos_osm','Santa Andreu de Clarà és la capella del Castell de Clarà, al terme municipal de Moià, catalogada com a bé cultural d''interès local. Està situada al cim del turó de Sant Andreu, a 200 m al migdia del castell, des d''on es pot contemplar una panoràmica amb Moià als peus i Castellterçol a l''horitzó.',41.8199566,2.080304,'https://ca.wikipedia.org/wiki/Sant_Andreu_de_Clarà_(Moià)');
