INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157024,'20059','Oñatiko "Sancti Spiritus" unibertsitatea','monumento','monumentos_osm','La Universidad de Oñate (en euskera: Oñatiko Unibertsitatea; en latín: Universitas Onnacensis), oficialmente Universidad del Espíritu Santo (en latín: Universitas Sancti Spiritus),​ fue una universidad española fundada en 1540 por bula de Paulo III. En la universidad llegó a contar con facultades de Leyes, Cánones,…',43.033955,-2.415349,'https://es.wikipedia.org/wiki/Universidad_de_Oñate');
