INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157055,'17048','Església de Nostra Senyora de l''Esperança','iglesia','monumentos_osm','Nostra Senyora de l''Esperança de s''Agaró és una església catòlica romana catalogada com a monument protegit amb el rang de bé cultural d''interès local,. Es troba dins del nucli urbà de s''Agaró (municipi de Castell d''Aro, Platja d''Aro i s''Agaró, Baix Empordà).',41.7949329,3.0588762,'https://ca.wikipedia.org/wiki/Nostra_Senyora_de_l''Esperança_de_s''Agaró');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157056,'17048','Sant Jordi de Treumal','iglesia','monumentos_osm','La capella ortodoxa del Comtat de Sant Jordi de Treumal (rus: Приход в честь святого великомученика Георгия и святой мученицы Анастасии, és una capella ortodoxa de Calonge (Baix Empordà) protegida com a Bé Cultural d''Interès Local.',41.8279072,3.0829831,'https://ca.wikipedia.org/wiki/Sant_Jordi_de_Treumal');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157057,'17048','Torre Valentina','monumento','monumentos_osm','La Torre Valentina és una antiga torre de defensa costenca i un monument protegit catalogat bé cultural d''interès nacional a Sant Antoni de Calonge al Baix Empordà. Als anys 60 va ser integrada en la urbanització homònima.',41.8373543,3.0927837,'https://ca.wikipedia.org/wiki/Torre_Valentina');
