INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157062,'31250','Itzea','palacio','monumentos_osm','Itzea Nafarroako Bortziriak eskualdeko Bera udalerrian dagoen jauregi bat da. Hain zuzen ere Altzate auzoan dago, Xantel errekaren aldamenean, Berako herrigunea amaitu eta Ibardin mendatera doan NA-1310 bidearen lehen malda hasten den lekuan.',43.2831278,-1.6785471,'https://eu.wikipedia.org/wiki/Itzea');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157063,'41067','Torre de Don Fadrique','monumento','monumentos_osm','La Torre de Don Fadrique de Albaida del Aljarafe fue construida en 1253 por el infante Fadrique de Castilla, que fue hijo de Fernando III de Castilla y de Beatriz de Suabia y hermano, por tanto, de Alfonso X de Castilla según consta en una piedra labrada de la propia torre, en la que se puede leer en caracteres…',37.4279307,-6.1670841,'https://es.wikipedia.org/wiki/Torre_de_don_Fadrique_(Albaida_del_Aljarafe)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(157064,'41067','Antiguo Pósito','monumento','monumentos_osm','Monumento en Olivares (Sevilla).',37.4182502,-6.1555985);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157065,'09017','Iglesia de Santa María','iglesia','monumentos_osm','La iglesia de Santa María, dedicada a la Virgen María, es un templo católico ubicado en Salas de los Infantes, en la provincia de Burgos, comunidad de Castilla y León, España. Fue construida en los siglos XV y XVI, y es de traza gótica.',42.0224509,-3.2821412,'https://es.wikipedia.org/wiki/Iglesia_de_Santa_María_de_Salas_de_los_Infantes_(Burgos)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(157066,'09017','Palacio de los Infantes','palacio','monumentos_osm','Casa señorial en Salas de los Infantes (Burgos).',42.0218472,-3.2858385);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157067,'12101','Església de Sant Antoni de Pàdua','iglesia','monumentos_osm','Sant Antoni de Pàdua és una església de petites dimensions al poble dels Valentins al terme municipal d''Ulldecona (Montsià) protegida com a bé cultural d''interès local. Edifici amb coberta a dos vessants, la façana principal no té cap decoració, l''únic element és la porta principal d''arc de mig punt.',40.6279511,0.3649845,'https://ca.wikipedia.org/wiki/Església_de_Sant_Antoni_de_Pàdua_(Ulldecona)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(157068,'12101','Molí de Fibla','monumento','monumentos_osm','Monumento en San Rafael del Río (Castellón).',40.6086749,0.3489058);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157069,'17901','Església de Sant Joan de Salelles','iglesia','monumentos_osm','L''església de Sant Joan de Salelles es troba en el municipi de Cruïlles, Monells i Sant Sadurní de l''Heura a la comarca del Baix Empordà. És un monument protegit i inventariat dins el Patrimoni Arquitectònic Català.',41.9482993,2.9993252,'https://ca.wikipedia.org/wiki/Església_de_Sant_Joan_de_Salelles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157070,'17901','Mare de Déu de l''Esperança','iglesia','monumentos_osm','La Mare de Déu d''Esperança és un santuari i ermita a poc menys d''un kilòmetre al nord de la vila de Cruïlles davant de la qual es dreça una creu de terme. El paratge és conegut popularment amb el nom d''"Esperança" (sense l''article).',41.9639073,3.0118574,'https://ca.wikipedia.org/wiki/Santuari_de_la_Mare_de_Déu_de_l''Esperança');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157071,'17901','Sant Miquel de Cruilles','iglesia','monumentos_osm','Sant Miquel de Cruïlles és un antic monestir romànic benedictí del veïnat de Sant Miquel de Cruïlles, al municipi de Cruïlles, Monells i Sant Sadurní de l''Heura (Baix Empordà). Es troba a 4 km de la Bisbal d''Empordà per la carretera de Cassà de la Selva.',41.9539687,3.0046204,'https://ca.wikipedia.org/wiki/Monestir_de_Sant_Miquel_de_Cruïlles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157072,'17901','Sant Sadurní de l''Heura','iglesia','monumentos_osm','Església de Sant Sadurní de l''Heura és un edifici del municipi de Cruïlles, Monells i Sant Sadurní de l''Heura (Baix Empordà). Té dins del seu terme l''ermita de Sant Joan de Salelles, que tenia sagrera el 1018.',41.9563354,2.990997,'https://ca.wikipedia.org/wiki/Església_de_Sant_Sadurní_de_l''Heura');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157073,'17901','Torre de Cruïlles','monumento','monumentos_osm','El Castell de Cruïlles fou un edifici a la vila de Cruïlles de la que, avui dia, només en resta la torre de l''homenatge. És al mig de la plaça de la Torre, al centre i punt més alt de la població.',41.956118,3.0111884,'https://ca.wikipedia.org/wiki/Castell_de_Cruïlles');
