INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157099,'90047','Ermita del Remei','iglesia','monumentos_osm','el Remei és una ermita a uns tres quilòmetres del nucli urbà d''Alcanar, sobre un petit tossal i al peu del puig de la Moleta del Remei on hi ha el Poblat ibèric de la Moleta del Remei. És una obra inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',40.5591894,0.4790813,'https://ca.wikipedia.org/wiki/El_Remei_(Alcanar)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157100,'90047','Església de Sant Miquel','iglesia','monumentos_osm','L''Església de Sant Miquel, al municipi d''Alcanar de la comarca catalana del Montsià, és un temple parroquial catòlic. Es tracta d''un edifici construït per substituir l''anterior temple datat ja des del 1363.',40.5439755,0.4813932,'https://ca.wikipedia.org/wiki/Església_de_Sant_Miquel_d''Alcanar');
