INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157102,'90047','Torre de Sòl de Riu','monumento','monumentos_osm','La torre de Sòl de Riu era una torre de guaita que estava situada a la desembocadura del riu de la Sénia, al municipi de Vinaròs (Baix Maestrat). Quan la torre va ser absorbida pel mar, una altra de similar, situada uns 300 metres terra endins va agafar el seu nom.',40.5228631,0.510362,'https://ca.wikipedia.org/wiki/Torre_de_Sòl_de_Riu');
