INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157107,'22122','Fuerte Santa Elena','monumento','monumentos_osm','El fuerte de Santa Elena es una enorme estructura militar situada en el municipio oscense de Biescas en el valle de Tena en la orilla izquierda del río Gállego sobre el monte Santa Elena dominando la carretera A-136 y el paso a Francia por el Portalet. Su construcción se inició en la época de Felipe II como parte…',42.6614772,-0.3209344,'https://es.wikipedia.org/wiki/Fuerte_de_Santa_Elena');
