INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157113,'15063','Igrexa de San Nicolao de Cis','iglesia','monumentos_osm','O mosteiro de San Nicolao de Cis, coñecido tamén como San Salvador de Cis debido á súa advocación, foi un mosteiro medieval situado na parroquia de San Nicolao de Cis, no concello coruñés de Oza Cesuras. Na actualidade só se conserva en pé a súa igrexa monacal.',43.221574,-8.2213522,'https://gl.wikipedia.org/wiki/Mosteiro_de_San_Nicolao_de_Cis');
