INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157138,'15048','Igrexa de San Xoán de Vilanova','iglesia','monumentos_osm','A igrexa de San Xoán de Vilanova é un templo relixioso de estilo románico da parroquia de Vilanova, no concello coruñés de Miño. A construción desta igrexa a mediados do século XI (1040) é un decidido paso adiante na introdución do románico en Galiza.',43.3789317,-8.2014208,'https://gl.wikipedia.org/wiki/Igrexa_de_San_Xoán_de_Vilanova');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157139,'15048','Pazo de Montecelo','palacio','monumentos_osm','O pazo de Montecelo é un pazo situado no lugar de Montecelo, na parroquia de San Pantaleón das Viñas, no concello coruñés de Paderne. Fica fronte á igrexa parroquial románica de San Pantaleón das Viñas, xunto á vía inglesa do Camiño de Santiago.',43.3268131,-8.195679,'https://gl.wikipedia.org/wiki/Pazo_de_Montecelo');
