INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157150,'15067','Torre de Xunqueiras','palacio','monumentos_osm','O Pazo Torre de Xunqueiras é unha casa señorial situada no lugar das Xunqueiras, na parroquia do Xobre, no concello coruñés da Pobra do Caramiñal. O edificio orixinal era unha fortaleza do antigo Reino de Galiza, do século XIII, que foi derrubada polos Irmandiños en 1467.',42.5950116,-8.9493694,'https://gl.wikipedia.org/wiki/Torre_de_Xunqueiras');
