INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157158,'17171','Santa Maria de l''Estela','iglesia','monumentos_osm','Santa Maria de l''Estela és una ermita al petit nucli de l''Estela, al nord-oest del municipi de Cabanelles al qual pertany. Es tracta d''un conjunt format per l''església i, adossada a aquesta per la banda de llevant, l''antiga rectoria actualment mig enrunada.',42.2832287,2.7824925,'https://ca.wikipedia.org/wiki/Santa_Maria_de_l''Estela');
