INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157217,'90009','Ermita de Sant Antoni Abat','iglesia','monumentos_osm','L''ermita de Sanç o ermita de Sant Antoni Abat és una ermita que es troba al terme municipal de Benidorm (la Marina Baixa). Va ser fundada el 1780 per Tomàs Sanç, procurador general dels senyorius de Polop i Benidorm, de qui prové el seu nom.',38.5606484,-0.0955965,'https://ca.wikipedia.org/wiki/Ermita_de_Sanç');
