INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157219,'90009','Torre de la Bombarda','monumento','monumentos_osm','La torre de la Bombarda és una torre defensiva del segle xvi que se situa en l''extrem nord de la serra Gelada, sobre un penya-segat, al costat del far de Punta Albir, a l''Alfàs del Pi. Té quatre metres d''alçària i servia per avisar dels freqüents atacs dels pirates barbarescs.',38.5635259,-0.0498097,'https://ca.wikipedia.org/wiki/Torre_Bombarda');
