INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157229,'08008','Santuari de la Misericordia','iglesia','monumentos_osm','El Santuari de la Mare de Déu de la Misericòrdia és una ermita promoguda santuari el 1907 que està dedicada a la patrona del Maresme. Està situada en una ampla esplanada ombrejada de pins que domina la vila de Canet de Mar.',41.59704,2.581288,'https://ca.wikipedia.org/wiki/Santuari_de_la_Mare_de_Déu_de_la_Misericòrdia');
