INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157255,'12045','Ermita de Sant Lluís Bertran','iglesia','monumentos_osm','L''ermita de Sant Lluís Bertrán situada dins de la població de Cinctorres (comarca dels Ports), al carrer que porta el seu nom, és un edifici construït probablement al segle xvii; l''atri s''hi afegí el 1678. Està catalogada com a Bé de Rellevància Local segons la Disposició Addicional Cinquena de la Llei 5/2007, de 9…',40.5834094,-0.2167421,'https://ca.wikipedia.org/wiki/Ermita_de_Sant_Lluís_Bertran');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157256,'12045','Ermita de Sant Marc','iglesia','monumentos_osm','La ermita de San Marcos de Cinctorres (los Puertos) es una ermita documentada en 1570 que se encuentra en unos 2 kilómetros de la población, orientada hacia el suroeste.​ La ermita con una planta rectangular, tiene unas dimensiones de 9 (ancho) x 20 (largo) metros. Tiene un tejado a dos vertientes, apoyada sobre…',40.5720384,-0.2192837,'https://es.wikipedia.org/wiki/Ermita_de_San_Marcos_de_Cinctorres');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157257,'12045','Ermita de Sant Pere','iglesia','monumentos_osm','L''ermita de Sant Pere, està ubicada uns 3 kilòmetres, al sud-oest de la població de Cinctorres, a la partida del seu nom, s''accedeix a l''ermita per la mateixa pista que duu a l''Ermita de Sant Marc.',40.5707935,-0.204691,'https://ca.wikipedia.org/wiki/Ermita_de_Sant_Pere_de_Cinctorres');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157258,'12045','Torre dels Moros','monumento','monumentos_osm','La torre dels Moros, en una lloma a escassos 2 quilòmetres de Cinctorres (els Ports, País Valencià), és una antiga torre de defensa d''època medieval. Tradicionalment ha estat considerada com una de les cinc torres a les quals es refereix el topònim de Cinctorres.',40.59298,-0.2111483,'https://ca.wikipedia.org/wiki/Torre_dels_Moros_(Cinctorres)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(157259,'12045','Torre Navalles','monumento','monumentos_osm','Torre histórica en Cinctorres (Castellón).',40.5711172,-0.2041632);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157260,'12052','Església Vella de Xert','iglesia','monumentos_osm','L''església vella de l''Assumpció de Xert, d''estil renaixentista amb vestigis gòtics, és un temple catòlic situat al centre històric de la població, seu d''una parròquia del bisbat de Tortosa fins a 1962, en què es va inaugurar la nova església de l''Assumpció, en la zona plana de la població. En aquest edifici encara…',40.5212496,0.1560744,'https://ca.wikipedia.org/wiki/Església_vella_de_Xert');
