INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157269,'45017','Església de Sant Feliu','iglesia','monumentos_osm','L''Església de Sant Feliu de Xàtiva és una ermita situada a Xàtiva (Costera), construïda en el segle xiii després de la reconquesta cristiana. És Bé d''Interès Cultural amb número de registre ministerial R-I-51-0000354 de data 4 de desembre de 1930.',38.9848248,-0.5191075,'https://ca.wikipedia.org/wiki/Església_de_Sant_Feliu_de_Xàtiva');
