INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157289,'17063','San Cristòfol de Cerdans','iglesia','monumentos_osm','L''església de Sant Cristòfol de Cerdans, centre del veïnat amb el mateix nom Cerdans, es troba emplaçada a l''extrem nord-occidental del terme municipal d''Arbúcies, dins la reserva del Parc Natural del Montseny, adossada a l''antiga rectoria que amaga el sector de la capçalera.',41.8427162,2.430886,'https://ca.wikipedia.org/wiki/Sant_Cristòfol_de_Cerdans');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157290,'17063','Sant Vicenç','iglesia','monumentos_osm','Sant Vicenç d''Espinelves és una església romànica d''Espinelves (Osona) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. L''església de Sant Vicenç és un edifici de dues naus, cadascuna amb un absis semicircular i cobertes amb una volta de canó, amb una capella lateral, que hi fou afegida més tardanament.',41.8688258,2.4174303,'https://ca.wikipedia.org/wiki/Sant_Vicenç_d''Espinelves');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(157291,'17063','Masjoan','palacio','monumentos_osm','Casa señorial en Espinelvas (Girona).',41.8699051,2.4111344);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157292,'09428','Iglesia de San Juan Bautista','iglesia','monumentos_osm','La iglesia de San Juan Bautista en la localidad de Guzmán (provincia de Burgos, Castilla y León, España) es un templo católico bajo la advocación de Juan el Bautista. Esta iglesia ha sido declarada por la Junta de Castilla y León, bien de interés cultural.',41.7562141,-3.9964001,'https://es.wikipedia.org/wiki/Iglesia_de_San_Juan_Bautista_(Guzmán)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(157293,'09428','Palacio de los Guzmán y Santoyo','palacio','monumentos_osm','Casa señorial en Villaescusa de Roa (Burgos).',41.7558699,-3.9975261);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157294,'36032','Igrexa de San Pedro de Rebón','iglesia','monumentos_osm','A igrexa de san Pedro de Rebón, é unha igrexa románica, dos séculos XII-XIV, da parroquia de Rebón (Moraña). Foi moi modificada por reformas posteriores, especialmente as realizadas no século XIX para ampliar a nave e construír o campanario.',42.5553576,-8.6037196,'https://gl.wikipedia.org/wiki/Igrexa_de_San_Pedro_de_Rebón');
