INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157300,'03067','Torre del Pla de la Casa','monumento','monumentos_osm','La torre del Pla de la Casa, també conegut com a castell de Xeroles, és un castell situat al municipi de Fageca (el Comtat), a la muntanya de la Serrella, a 1359 m. d''altitud, sent el castell més alt de la província d''Alacant.',38.7165863,-0.2746582,'https://ca.wikipedia.org/wiki/Torre_del_Pla_de_la_Casa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157301,'12015','Iglesia parroquial de Santa Ana','iglesia','monumentos_osm','La iglesia parroquial de San Ana, localizada en la plaza de la Iglesia de Argelita, en la comarca del Alto Mijares es un lugar de culto catalogado como Bien de relevancia local, según la Disposición Adicional Quinta de la Ley 5/2007, de 9 de febrero, de la Generalidad Valenciana, de modificación de la Ley 4/1998,…',40.0551413,-0.3498229,'https://es.wikipedia.org/wiki/Iglesia_de_Santa_Ana_(Argelita)');
