INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157304,'22188','Mare de Déu de Montserbós','iglesia','monumentos_osm','La Mare de Déu de Montserbós, altrament dita Santuari de les Capelles és un santuari d''origen romànic situat a 986 m d''altitud, prop del Tossal Gros, a ponent de Montllobar i, per tant, a prop del Pont de Montanyana. És dalt d''un turó que domina la carretera C-1311, que li fa pràcticament tota la volta.',42.1499882,0.7449527,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Montserbós');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157305,'22188','Mare de Déu del Roser','iglesia','monumentos_osm','La Mare de Déu del Roser del Mas de Pere és una capella romànica del Mas de Pere, al nucli de masies dispers dels Masions, en el poble de Castissent, de l''antic terme municipal Fígols de Tremp, integrat actualment en el de Tremp, de la comarca del Pallars Jussà. És una capella romànica molt senzilla.',42.136174,0.7349558,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Roser_del_Mas_de_Pere');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157306,'22188','Sant Joan Baptista','iglesia','monumentos_osm','Sant Joan Baptista de Castissent és una església romànica de Tremp (Pallars Jussà) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. En concret, està situada al poble de Castissent, de l''antic terme municipal Fígols de Tremp, integrat actualment en el de Tremp, de la comarca del Pallars Jussà.',42.1245126,0.7136231,'https://ca.wikipedia.org/wiki/Sant_Joan_Baptista_de_Castissent');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157307,'22188','Sant Pere de Claramunt','iglesia','monumentos_osm','Sant Pere de Claramunt és una església parroquial romànica del poble de Claramunt, de l''antic terme municipal Fígols de Tremp, integrat actualment en el de Tremp, de la comarca del Pallars Jussà. Com Castissent, aquesta parròquia no pertany al bisbat d''Urgell, sinó al de de Lleida, perquè aquest bisbat acollí les…',42.1791215,0.7827093,'https://ca.wikipedia.org/wiki/Sant_Pere_de_Claramunt');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157308,'22188','Sant Pere de Tercui','iglesia','monumentos_osm','Sant Pere de Tercui és l''església parroquial romànica del poble de Tercui. Sense que estigui desafectada, no s''hi celebra culte regularment, atesa la minsa quantitat d''habitants del lloc.',42.1792633,0.7223222,'https://ca.wikipedia.org/wiki/Sant_Pere_de_Tercui');
