INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157326,'25140','Sant Martí','iglesia','monumentos_osm','Sant Martí d''Albet és un antic monestir, actualment església sufragània, del veïnat d''Albet en el municipi de Montferrer i Castellbò (Alt Urgell). Està protegida com a bé cultural d''interès local.',42.4056329,1.3250789,'https://ca.wikipedia.org/wiki/Sant_Martí_d''Albet');
