INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157333,'12117','Església Parroquial de Sant Bartomeu','iglesia','monumentos_osm','La iglesia parroquial de San Bartolomé en Torreblanca (Provincia de Castellón, España) fue concebida por Juan Barceló en el siglo XVIII. El actual edificio es el sucesor de la segunda iglesia que se levantó en la población y que se inauguró en 1692.​ En el siglo XVIII, los fieles consideraron que era “sobradamente…',40.2208663,0.1959491,'https://es.wikipedia.org/wiki/Iglesia_de_San_Bartolomé_(Torreblanca)');
