INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157366,'27061','Santuario da Nosa Señora das Virtudes da Ponte','iglesia','monumentos_osm','O Santuario da Nosa Señora das Virtudes, tamén coñecido como Igrexa das Virtudes ou ermida de Santa María, é un templo relixioso situado no lugar da Ponte (Arante, Ribadeo). Arredor da capela celébrase a romaría das Cruces, declarada festa de interese turístico de Galicia (declarada no 2018).',43.496705,-7.1432101,'https://gl.wikipedia.org/wiki/Santuario_da_Nosa_Señora_das_Virtudes_da_Ponte');
