INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157409,'09362','Palacio de Saldañuela','palacio','monumentos_osm','El palacio de Saldañuela es una casa-palacio renacentista ubicada en el municipio español de Sarracín, en la provincia de Burgos. Uno de los más destacados exponentes de la arquitectura civil del Renacimiento en la provincia.',42.2524034,-3.6863415,'https://es.wikipedia.org/wiki/Palacio_de_Saldañuela');
