INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157411,'38042','Iglesia Nuestra Señora de la Luz','iglesia','monumentos_osm','La iglesia de Nuestra Señora de La Luz se encuentra en el municipio de Los Silos, en la isla de Tenerife (Islas Canarias, España). Es la iglesia parroquial del municipio.',28.3652565,-16.8167367,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_La_Luz_(Los_Silos)');
