INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157413,'17188','Monestir de Sant Pere de Rodes','iglesia','monumentos_osm','El monestir de Sant Pere de Rodes (o de Roda) fou un monestir benedictí de l''antic comtat d''Empúries, dins els límits del bisbat de Girona, situat a l''actual terme municipal del Port de la Selva (Alt Empordà). En concret, es troba al sud-oest de la població del Port de la Selva, al vessant de llevant de la muntanya…',42.3233443,3.1664303,'https://ca.wikipedia.org/wiki/Sant_Pere_de_Rodes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157414,'17188','Sant Fruitós','iglesia','monumentos_osm','Sant Fruitós de la Vall de Santa Creu és una església del municipi del Port de la Selva inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.3358718,3.1666391,'https://ca.wikipedia.org/wiki/Sant_Fruitós_de_la_Vall_de_Santa_Creu');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157415,'17188','Sant Sebastià','iglesia','monumentos_osm','Sant Sebastià de la Selva de Mar és una església de la Selva de Mar (Alt Empordà) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. Està situada als afores, a l''oest del nucli urbà de la població, en un replà una mica més enlairat sobre la vall de la riera de la Selva, en l''antic camí que porta a Sant…',42.3224858,3.1846398,'https://ca.wikipedia.org/wiki/Sant_Sebastià_de_la_Selva_de_Mar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157416,'17188','Santa Helena de Rodes','iglesia','monumentos_osm','Santa Creu de Rodes o Santa Helena és una església del municipi del Port de la Selva. Està situada a l''est de les ruïnes del poblat medieval de Santa Creu de Rodes, aproximadament a un quilòmetre al nord de distància del monestir de Sant Pere de Rodes.',42.3266367,3.1600722,'https://ca.wikipedia.org/wiki/Santa_Helena_de_Rodes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157417,'13020','Palacio del Marqués de Santa Cruz','monumento','monumentos_osm','El palacio del Marqués de Santa Cruz es un edificio situado en el municipio de Viso del Marqués (Ciudad Real), en la Comunidad autónoma de Castilla-La Mancha, en España. Fue construido a finales del siglo XVI por Álvaro de Bazán, primer marqués de Santa Cruz.​ Actualmente es la sede del Archivo General de la Marina.',38.5231419,-3.5631659,'https://es.wikipedia.org/wiki/Palacio_del_Marqués_de_Santa_Cruz_(Viso_del_Marqués)');
