INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157419,'46131','Alqueria del Duc','palacio','monumentos_osm','L''Alqueria del Duc, també anomenada alqueria del senyor Alfons és una alqueria-fortalesa que es troba al terme municipal de Gandia, la Safor, a la partida anomenada Font de Montaner, al peu del Castell de Bairén.',38.9903082,-0.1766426,'https://ca.wikipedia.org/wiki/Alqueria_del_Duc');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157420,'46131','Convento de Santa Clara','iglesia','monumentos_osm','El Convent de Santa Clara és un convent de clausura situat a la ciutat valenciana de Gandia (La Safor). Va ser fundat al segle xv i actualment està habitat per monges de l''Orde de les Clarisses Coletines.',38.9674669,-0.1780133,'https://ca.wikipedia.org/wiki/Convent_de_Santa_Clara_de_Gandia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157421,'46131','Ermita de Santa Anna','iglesia','monumentos_osm','L''ermita de Santa Anna és un santuari ubicat al barri de Santa Anna de la localitat de Gandia. Declarada Bé Immoble de Rellevància Local, per declaració genèrica de la Generalitat Valenciana, amb publicació al DOGV el 18 de juny de 1998.',38.9770288,-0.1871118,'https://ca.wikipedia.org/wiki/Ermita_de_Santa_Anna_(Gandia)');
