INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157423,'43124','Església de Sant Nicolau','iglesia','monumentos_osm','Sant Nicolau de la Riba és una església parroquial de la vila de la Riba (l''Alt Camp), protegida com a bé cultural d''interès local. La parròquia té com a sufragànies les de Sant Salvador de Picamoixons i Sant Simó de Fontscaldes, dos nuclis del municipi de Valls.',41.3188648,1.177957,'https://ca.wikipedia.org/wiki/Sant_Nicolau_de_la_Riba');
