INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157425,'12049','Església de la Transfiguració del Senyor de les Useres','iglesia','monumentos_osm','L''església de la Transfiguració del Senyor de les Useres és un temple catòlic del segle xvii, construït sobre les runes d''un antic castell, en la part més elevada de la població, i seu d''una parròquia del bisbat de Sogorb-Castelló.',40.1570243,-0.1648641,'https://ca.wikipedia.org/wiki/Església_de_la_Transfiguració_del_Senyor_de_les_Useres');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157426,'31259','San Juan Xar','iglesia','monumentos_osm','San Juan Xar («San Joan Zaharra») Nafarroa Garaiko iparraldeko Igantziko udalerrian dagoen eremu natural, erlijioso eta turistiko bat da, Igantzi eta Arantzaren arteko galtzada zaharrean kokatua. Eremu honetan dago Iberiar penintsulako xarma (Carpinus betulus) baso bakarra; horregatik, 1987.',43.2104193,-1.707837,'https://eu.wikipedia.org/wiki/San_Juan_Xar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157427,'12050','Ermita de Sant Vicent','iglesia','monumentos_osm','L''Ermita de Sant Vicent Ferrer (Les Coves de Vinromà), està situada al Pla de Sant Vicent, en el camí del Mas dels Arcs, abans d''arribar al cementeri, a uns 300 m de la població. Ha estat qualificada com a Bé de Rellevància Local amb la categoria de Monument d''Interès Local.',40.3155374,0.1188987,'https://ca.wikipedia.org/wiki/Ermita_de_Sant_Vicent_Ferrer_de_les_Coves_de_Vinromà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157428,'12050','Ermita del Calvari','iglesia','monumentos_osm','La Ermita del Calvario, en la localidad de Cuevas de Vinromá, en la comarca de la Plana Alta, en la provincia de Castellón, es una ermita que se encuentra en el mismo núcleo poblacional de Cuevas de Vinromá, al final de la calle de su mismo nombre.​​',40.3089284,0.1228157,'https://es.wikipedia.org/wiki/Ermita_del_Calvario_(Cuevas_de_Vinromá)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157429,'43092','Sant Joan Baptista','iglesia','monumentos_osm','L''Església de Sant Joan Baptista és una església barroca de Vilanova d''Escornalbou (Baix Camp) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.1055509,0.9619863,'https://ca.wikipedia.org/wiki/Església_de_Sant_Joan_Baptista_(l''Arbocet)');
