INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157443,'17233','Sant Esteve','iglesia','monumentos_osm','Sant Esteve de Vilobí és una església parroquial de Vilobí d''Onyar (Selva), catalogada com a bé cultural d''interès local. Està dedicada al patró del poble, Sant Esteve màrtir, i també hi reben veneració dos beats màrtirs de la parròquia.',41.8889096,2.7426845,'https://ca.wikipedia.org/wiki/Sant_Esteve_de_Vilobí');
