INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157472,'43146','Santuari del Tallat','iglesia','monumentos_osm','El santuari del Tallat és un antic priorat i actual santuari marià del municipi de Vallbona de les Monges (Urgell). Està situat al cim d''un turó de 787 metres d''altitud de la serra del mateix nom, al límit de les comarques de l''Urgell i la Conca de Barberà.',41.4821022,1.1377308,'https://ca.wikipedia.org/wiki/Santuari_del_Tallat');
