INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157485,'17183','Santa Maria','iglesia','monumentos_osm','Santa Maria de Granollers de Rocacorba és l''església parroquial de Granollers de Rocacorba, al municipi de Sant Martí de Llémena (Gironès), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.0685371,2.6519536,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Granollers_de_Rocacorba');
