INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157492,'17139','Mare de Déu de les Olletes','iglesia','monumentos_osm','El santuari de la Mare de Déu de les Olletes està situat a la Vall d''en Bas dins un barranc i es troba a 1.036 metres sobre el nivell del mar, al vessant nord del Puigsacalm just sota Santa Magdalena del Mont. La cova té cinc metres d''alçada per vuit de fondària i quatre d''amplada.',42.1344506,2.3952656,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_les_Olletes');
