INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157513,'25508','Sant Cristòfol','iglesia','monumentos_osm','Sant Cristòfol de la Vall és una església de Gavet de la Conca (Pallars Jussà) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.0687167,0.9421584,'https://ca.wikipedia.org/wiki/Sant_Cristòfol_de_la_Vall_(església)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157514,'25508','Sant Fruitós d''Aransís','iglesia','monumentos_osm','Sant Fruitós d''Aransís és una església romànica del terme d''Aransís, actualment englobat en el de Gavet de la Conca, pertanyent al Pallars Jussà. Està situada uns 500 metres a ponent i lleugerament al nord del poble d''Aransís.',42.088873,0.949884,'https://ca.wikipedia.org/wiki/Sant_Fruitós_d''Aransís');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157515,'25508','Sant Gervàs','iglesia','monumentos_osm','Sant Gervàs del Castelló Sobirà (més exactament Sant Gervàs i Sant Protàs del Castelló Sobirà) és una ermita molt poc documentada al llarg de la història. Malgrat ser clarament d''origen medieval, les primeres notícies que en tenim són dels segles xvii i XVIII. En un testament atorgat el 16 de novembre de 1684, es…',42.0708645,0.9706029,'https://ca.wikipedia.org/wiki/Sant_Gervàs_del_Castelló_Sobirà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157516,'25508','Sant Miquel','iglesia','monumentos_osm','Sant Miquel de la Vall és l''església romànica parroquial del poble del mateix nom, de l''antic terme d''Aransís i de l''actual de Gavet de la Conca, al Pallars Jussà. Nascuda possiblement com a capella del Castelló Jussà de Sant Miquel de la Vall, absorbí l''església de Santa Maria del Castelló Sobirà i també la de…',42.0698036,0.9630794,'https://ca.wikipedia.org/wiki/Sant_Miquel_de_la_Vall_(església)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157517,'12076','Ermita de Santa Bárbara','iglesia','monumentos_osm','La Ermita de Santa Bárbara de Matet, en la comarca del Alto Palancia, provincia de Castellón, España, es una ermita católica que está catalogada como Bien de Relevancia Local según consta en la Dirección General de Patrimonio Artístico de la Generalidad Valenciana, código 12.07.076-005.​​',39.9382567,-0.4670499,'https://es.wikipedia.org/wiki/Ermita_de_Santa_Bárbara_y_Calvario_de_Matet');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157518,'25906','Sant Bartomeu de Malgrat','iglesia','monumentos_osm','Sant Bartomeu de Malgrat és una església del municipi de les Valls d''Aguilar protegida com a bé cultural d''interès local.',42.299033,1.3058899,'https://ca.wikipedia.org/wiki/Sant_Bartomeu_de_Malgrat');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157519,'25906','Sant Climent','iglesia','monumentos_osm','Sant Climent de Saulet és l''església del poble de Saulet, al municipi de Montferrer i Castellbò (Alt Urgell), inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.3402268,1.3204112,'https://ca.wikipedia.org/wiki/Sant_Climent_de_Saulet');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157520,'25906','Sant Fruitós','iglesia','monumentos_osm','Sant Fruitós de Guils del Cantó és una església barroca del poble de Guils del Cantó, en el municipi de Montferrer i Castellbò (Alt Urgell), protegida com a bé cultural d''interès local.',42.3457406,1.2829622,'https://ca.wikipedia.org/wiki/Sant_Fruitós_de_Guils_del_Cantó');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157521,'25906','Sant Lluc d''Anyús','iglesia','monumentos_osm','Sant Lluc d''Anyús és una església del municipi de les Valls d''Aguilar protegida com a bé cultural d''interès local.',42.3138891,1.286778,'https://ca.wikipedia.org/wiki/Sant_Lluc_d''Anyús');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157522,'25906','Sant Martí','iglesia','monumentos_osm','Sant Martí de Berén és una església del municipi de les Valls d''Aguilar protegida com a bé cultural d''interès local. Sant Martí de Berén havia estat una Parròquia eclesiàstica.',42.3166417,1.3122461,'https://ca.wikipedia.org/wiki/Sant_Martí_de_Berén');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157523,'17185','Sant Joan les Fonts','iglesia','monumentos_osm','El Monestir de Sant Joan les Fonts és una obra de Sant Joan les Fonts (Garrotxa) declarada bé cultural d''interès nacional. L''església de Sant Joan les Fonts està situada sobre un promontori, vora un meandre del riu Fluvià, prop de la població.',42.2176097,2.5149974,'https://ca.wikipedia.org/wiki/Monestir_de_Sant_Joan_les_Fonts');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157524,'17185','Sant Josep Obrer','iglesia','monumentos_osm','Sant Josep Obrer de la Canya és una església de la Vall de Bianya (Garrotxa) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.2059263,2.4931188,'https://ca.wikipedia.org/wiki/Sant_Josep_Obrer_de_la_Canya');
