INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157526,'17185','Santa Maria de Castellar de Muntanya','iglesia','monumentos_osm','Santa Maria de Castellar de la Muntanya és una església romànica del segle xii molt modificada, situada a Castellar de la Muntanya, actualment al municipi de la Vall de Bianya, a la comarca catalana de la Garrotxa. És un monument inventariat a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.2379868,2.4999536,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Castellar_de_la_Muntanya');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157527,'43081','Ermita de Sant Antoni','iglesia','monumentos_osm','L''Ermita de Sant Antoni de Pàdua és una obra del municipi de Maspujols (Baix Camp) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.1810805,1.0436259,'https://ca.wikipedia.org/wiki/Ermita_de_Sant_Antoni_de_Pàdua_(Maspujols)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157528,'25111','Mare de Déu de Puig-aguilar','iglesia','monumentos_osm','El santuari de la Mare de Déu de Puig-aguilar és un santuari que s''aixeca dalt d''un esperó meridional del Puig Aguilar al terme de la Corriu, pertanyent al municipi de Guixers, a la comarca del Solsonès. És un monument protegit com a Bé Cultural d''Interès Local S''hi accedeix fàcilment per la carretera secundària,…',42.1554795,1.660178,'https://ca.wikipedia.org/wiki/Santuari_de_la_Mare_de_Déu_de_Puig-aguilar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157529,'25111','Sant Climent de Castelltort','iglesia','monumentos_osm','Sant Climent de Castelltort és una església d''estil romànic del municipi de Guixers (Solsonès), protegida com a bé cultural d''interès local',42.1273153,1.6285843,'https://ca.wikipedia.org/wiki/Sant_Climent_de_Castelltort');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157530,'25111','Sant Climent de la Selva','iglesia','monumentos_osm','Sant Climent de la Selva és una edificació religiosa que forma part de l''Inventari del Patrimoni Arquitectònic Català de Navès (Solsonès).',42.0807332,1.6473625,'https://ca.wikipedia.org/wiki/Sant_Climent_de_la_Selva');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157531,'25111','Sant Cristòfol de Busa','iglesia','monumentos_osm','Sant Cristòfol de Busa és l''església parroquial del nucli de Busa que forma part de l''Inventari del Patrimoni Arquitectònic Català de Navès (Solsonès). Es troba al nord del pla de Busa, damunt un turó, al peu de la muralla rocosa de la serra de Busa, molt visible des de qualsevol punt del pla.',42.102564,1.646825,'https://ca.wikipedia.org/wiki/Sant_Cristòfol_de_Busa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157532,'25111','Sant Martí de Guixers','iglesia','monumentos_osm','Sant Martí de Guixers, coneguda també com les Volianes o l''església de la Trinitat per celebrar-s''hi un aplec en aquesta festivitat, és una ermita romànica situada al poble de Guixers, a la Vall de Lord (comarca del Solsonès). És un monument protegit i inventariat dins el Patrimoni Arquitectònic Català S''hi…',42.1359,1.6441614,'https://ca.wikipedia.org/wiki/Sant_Martí_de_Guixers');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157533,'90909','Sant Bartomeu','iglesia','monumentos_osm','Sant Bartomeu, que dona nom a la plaça on aboca la seva entrada, és l''església parroquial d''Alió (Alt Camp), protegida com a bé cultural d''interès local.',41.2948286,1.3059624,'https://ca.wikipedia.org/wiki/Sant_Bartomeu_d''Alió');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157534,'90910','Sant Miquel','iglesia','monumentos_osm','L''església de Sant Miquel d''Almoster és un monument protegit com a bé cultural d''interès local del municipi d''Almoster (Baix Camp).',41.1979999,1.1137898,'https://ca.wikipedia.org/wiki/Sant_Miquel_d''Almoster');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157535,'25549','Mare de Déu de les Ares','iglesia','monumentos_osm','La Mare de Déu de les Ares és un santuari del terme municipal d''Alt Àneu, a la comarca del Pallars Sobirà. Pertanyia a l''antic terme de la Mancomunitat dels Quatre Pobles.',42.6477425,1.0073309,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_les_Ares');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157536,'25549','Sant Joan d''Isil','iglesia','monumentos_osm','Sant Joan d''Isil és l''església parroquial romànica del poble d''Isil, en el terme municipal d''Alt Àneu, a la comarca del Pallars Sobirà. Està situada mig quilòmetre al sud d''Isil, ran de les aigües de la Noguera Pallaresa, per la qual cosa és una de les construccions romàniques més notables i característiques de la…',42.6759231,1.084689,'https://ca.wikipedia.org/wiki/Sant_Joan_d''Isil');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157537,'25549','Sant Lliser','iglesia','monumentos_osm','Sant Lliser d''Alós és una església romànica del poble d''Alós, en el terme municipal d''Alt Àneu, a la comarca del Pallars Sobirà. La major part de l''església actual és de factura barroca, però conserva alguns elements de l''obra romànica.',42.7011719,1.1000714,'https://ca.wikipedia.org/wiki/Sant_Lliser_d''Alós');
