INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157539,'25549','Sant Martí','iglesia','monumentos_osm','Sant Martí de Borén és una església romànica del poble de Borén, en el terme municipal d''Alt Àneu, a la comarca del Pallars Sobirà. Pertanyia a l''antic terme de Sorpe.',42.6601852,1.0810549,'https://ca.wikipedia.org/wiki/Sant_Martí_de_Borén');
