INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157543,'43015','Santa Maria de Siurana','iglesia','monumentos_osm','Santa Maria de Siurana és una església d''època romànica situada al poble de Siurana, dins del terme municipal de Cornudella de Montsant, a la comarca del Priorat, i que es conserva íntegrament.',41.2575932,0.9322145,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Siurana');
