INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157546,'43082','Mare de Déu de les Pinyeres','iglesia','monumentos_osm','La Mare de Déu de les Pinyeres és una ermita romànica reconstruïda en època barroca situada als termes municipals del Masroig i Bellmunt del Priorat (Priorat) protegida com a bé cultural d''interès local. Tots dos municipis hi fan romeria el dia de la festivitat, el dissabte després de Dilluns de Pasqua.',41.1443468,0.7297021,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_les_Pinyeres');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157547,'90920','Sant Jaume de Vallespinosa','iglesia','monumentos_osm','Sant Jaume és una església parroquial al nucli urbà de Vallespinosa inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. Edifici d''una sola nau, amb presbiteri pla no diferenciat.',41.4447916,1.3496712,'https://ca.wikipedia.org/wiki/Sant_Jaume_de_Vallespinosa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157548,'90920','Sant Llorenç','iglesia','monumentos_osm','Sant Llorenç de Selmella és una antiga església del despoblat de Selmella situat al nord del municipi del Pont d''Armentera (Alt Camp). Està protegida com a bé cultural d''interès local.',41.4211334,1.3384894,'https://ca.wikipedia.org/wiki/Sant_Llorenç_de_Selmella');
