INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157551,'24207','Ermita de la Piedad','iglesia','monumentos_osm','La ermita de la Piedad es un templo católico situado a las afueras de la villa de Villademor de la Vega, construido originalmente para albergar la talla de la Virgen de la Piedad, patrona de la villa, aunque en la actualidad se encuentra en su interior ocasionalmente, estando la mayor parte del tiempo por motivos…',42.265968,-5.5609254,'https://es.wikipedia.org/wiki/Ermita_de_la_Piedad_(Villademor_de_la_Vega)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157552,'08304','Santa Maria de Vallformosa','iglesia','monumentos_osm','L''església del cementiri de Vilobí del Penedès, antiga església parroquial de Santa Maria de Vallformosa, és un edifici de Vilobí del Penedès (Alt Penedès) situat a la carretera de Vilafranca del Penedès a les Cabanyes. Està inclòs a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.3823483,1.6758751,'https://ca.wikipedia.org/wiki/Església_del_cementiri_de_Vilobí_del_Penedès');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157553,'08304','Santa María','iglesia','monumentos_osm','Santa Maria de Vallformosa és una església de Vilobí del Penedès (Alt Penedès) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. L''Església de Santa Maria de Vallformosa està situada en un lloc proper a la carretera que va de Guardiola a Vilafranca.',41.3913487,1.6631995,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Vallformosa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157554,'43177','Ermita de San Miguel','iglesia','monumentos_osm','Sant Miquel és una ermita situada a la serra del Tormo, o serra de les Aubagues, i a l''entrada del Pas de l''Ase, a la part meridional del terme municipal de Vinebre (Ribera d''Ebre) protegit com a bé cultural d''interès local. Molt proper a la capella de Sant Miquel hi ha el poblat ibèric que duu el mateix nom, motiu…',41.1758345,0.6085454,'https://ca.wikipedia.org/wiki/Ermita_de_Sant_Miquel_(Vinebre)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157555,'43126','Església vella d''Ardenya','iglesia','monumentos_osm','Església vella d''Ardenya és una obra romànica de la Riera de Gaià (Tarragonès) protegida com a Bé Cultural d''Interès Local.',41.1684319,1.3434313,'https://ca.wikipedia.org/wiki/Església_vella_d''Ardenya');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157556,'43126','Sant Jordi','iglesia','monumentos_osm','Sant Jordi d''Ardenya és una església barroca de la Riera de Gaià (Tarragonès) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.1687026,1.3438982,'https://ca.wikipedia.org/wiki/Sant_Jordi_d''Ardenya');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157557,'43137','Ermita De La Mare De Déu Dels Arquets','iglesia','monumentos_osm','Mare de Déu dels Arquets és un edifici religiósdel municipi de Sant Jaume dels Domenys (Baix Penedès) inclòs en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.2969802,1.5679852,'https://ca.wikipedia.org/wiki/Mare_de_Déu_dels_Arquets');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157558,'08170','Església de Sant Pere del Vim','iglesia','monumentos_osm','L''església de Sant Pere del Vim és una església del municipi de Veciana, a l''Anoia protegit com a bé cultural d''interès local. Es troba acompanyada d''un grup de cases, una de les quals se li adossa pel costat de migdia, es troba enlairada dalt d''un tossal.',41.6798391,1.5293031,'https://ca.wikipedia.org/wiki/Església_de_Sant_Pere_del_Vim');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157559,'08170','Mare de Deu del Portal','iglesia','monumentos_osm','La Mare de Déu del Portal és una església a la vila dels Prats de Rei (Anoia) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. L''actual edifici està situat al lloc que ocupà el Portal Major, de la vila dels Prats de Rei, sobre el qual, quan es van reedificar les muralles, entre els anys 1375 i 1377,…',41.7047529,1.5417651,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Portal');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157560,'08170','Sant Andreu de la Manresana','iglesia','monumentos_osm','Sant Andreu de la Manresana és una església de nucli de la Manresana als Prats de Rei (Anoia) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.6959769,1.5524829,'https://ca.wikipedia.org/wiki/Sant_Andreu_de_la_Manresana');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157561,'08170','Sant Gil','iglesia','monumentos_osm','Sant Gil és una església parroquial al nucli de Solanelles (Anoia) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. Possiblement aquesta església ocupi el lloc de l''antiga parròquia de Sant Gil, documentada des del 1138 i que junt amb la torre de Solanelles es considerava del terme del castell de…',41.7198611,1.536583,'https://ca.wikipedia.org/wiki/Sant_Gil_de_Solanelles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157562,'37297','Ermita de Nuestra Señora de Valparaíso','iglesia','monumentos_osm','La ermita de Nuestra Señora de Valparaíso es un templo del municipio de Santibáñez de Béjar, dónde se encuentra la patrona de la villa, la Virgen de Valparaíso. Es una ermita originalmente construida sobre un templo romano del que se conservan las bases.',40.4901699,-5.6050796,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_Valparaíso_(Santibáñez_de_Béjar)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157563,'37297','Iglesia Santiago Apóstol','iglesia','monumentos_osm','La iglesia de Santiago Apóstol es la única iglesia del municipio de Santibáñez de Béjar (Salamanca, España).',40.4874607,-5.6115753,'https://es.wikipedia.org/wiki/Iglesia_de_Santiago_Apóstol_(Santibáñez_de_Béjar)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157564,'43111','Mare de Déu de Montornès','iglesia','monumentos_osm','La Mare de Déu de Montornès és un monument del municipi de la Pobla de Montornès protegit com a bé cultural d''interès local. L''església parroquial de la Pobla de Montornès, dedicada a Santa Maria, és a un quart d''hora, aproximadament de la localitat, dalt d''un turó.',41.170706,1.4037532,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Montornès');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157565,'43170','Església de Santa Maria','iglesia','monumentos_osm','Santa Maria és una església parroquial neoclàssica del segle xviii protegida com a bé cultural d''interès local al centre de la vila de Vila-rodona (Alt Camp). Adscrita a l''arxiprestat de l''Alt Camp de l''arquebisbat de Tarragona, té com a sufragània la parròquia de Sant Jaume de Bràfim.',41.310816,1.3584855,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Vila-rodona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157566,'43170','Monestir de Santes Creus','iglesia','monumentos_osm','El Monestir de Santes Creus o Reial Monestir de Santa Maria de Santes Creus és una de les joies de l''art medieval català i està situat al poble de Santes Creus, Aiguamúrcia (Alt Camp, Tarragona). Actualment és l''únic monestir de la Ruta del Cister que no té vida monàstica.',41.346258,1.3643819,'https://ca.wikipedia.org/wiki/Reial_Monestir_de_Santa_Maria_de_Santes_Creus');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157567,'43170','Sant Pere de les Destres','iglesia','monumentos_osm','Sant Pere de les Destres és una església del municipi d''Aiguamúrcia (Alt Camp) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.3384044,1.3792014,'https://ca.wikipedia.org/wiki/Sant_Pere_de_les_Destres');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157568,'43170','Santa María','iglesia','monumentos_osm','Santa Maria d''Aiguamúrcia és una església d''Aiguamúrcia (Alt Camp) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.3290652,1.3583796,'https://ca.wikipedia.org/wiki/Santa_Maria_d''Aiguamúrcia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157569,'43034','Església de Sant Jaume','iglesia','monumentos_osm','Sant Jaume de Bràfim és l''església parroquial de Bràfim (Alt Camp). Està protegida com a bé cultural d''interès local.',41.2685969,1.3412597,'https://ca.wikipedia.org/wiki/Sant_Jaume_de_Bràfim');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157570,'43090','Església de Aiguaviva','iglesia','monumentos_osm','Sant Pere d''Aiguaviva és una església historicista del Montmell (Baix Penedès) protegida com a Bé Cultural d''Interès Local.',41.3522842,1.5042761,'https://ca.wikipedia.org/wiki/Sant_Pere_d''Aiguaviva');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157571,'43090','Sant Miquel','iglesia','monumentos_osm','Sant Miquel de Canferrer és una església del Montmell inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.3248202,1.4201277,'https://ca.wikipedia.org/wiki/Sant_Miquel_de_Canferrer');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157572,'43090','Sant Miquel del Montmell','iglesia','monumentos_osm','Sant Miquel del Montmell és una antiga església parroquial del municipi homònim (Baix Penedès), catalogada com a bé cultural d''interès local. Es troba a uns 640 m sobre el nivell del mar.',41.3301705,1.4563252,'https://ca.wikipedia.org/wiki/Sant_Miquel_de_Montmell');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157573,'90862','Santuari de la Mare de Déu de la Vallivana','iglesia','monumentos_osm','Santuari de la Verge de Vallivana (Llogaret i antic santuari de la província de Castelló, municipi de Morella. L''eremitori de Vallivana és un dels més grandiosos i històrics del País Valencià.',40.5399409,0.0535409,'https://ca.wikipedia.org/wiki/Santuari_de_la_Verge_de_Vallivana');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157574,'17204','Església de Santa Maria','iglesia','monumentos_osm','Santa Maria d''Ullà és un temple catòlic a la vila d''Ullà (Baix Empordà). La primitiva canònica era als afores de la població, propera al riu Ter.',42.0516711,3.1082585,'https://ca.wikipedia.org/wiki/Santa_Maria_d''Ullà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157575,'17204','Sant Andreu d''Ullà','iglesia','monumentos_osm','Sant Andreu d''Ullà és un edifici religiós del municipi d''Ullà inclòs en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.051803,3.1085448,'https://ca.wikipedia.org/wiki/Sant_Andreu_d''Ullà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157576,'08905','Església de Santa Maria','iglesia','monumentos_osm','Santa Maria i Sant Brici de la Palma és l''església parroquial del municipi de la Palma de Cervelló al Baix Llobregat, pertany a la diòcesi del bisbat de Sant Feliu de Llobregat i a l''arxiprestat de Sant Vicenç dels Horts. Forma un conjunt amb la casa rectoral i es troba emplaçada a l''extrem oest del nucli urbà,…',41.4119115,1.9704907,'https://ca.wikipedia.org/wiki/Santa_Maria_i_Sant_Brici_de_la_Palma');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157577,'08905','Sant Joan del Pla','iglesia','monumentos_osm','Sant Joan del Pla o Sant Joan de l''Erm de la Palma és una capella romànica del segle xi, possiblement d''origen preromànic, documentada el 1313 i que està situada al poble de la Palma de Cervelló a la comarca del Baix Llobregat.',41.4061097,1.9787661,'https://ca.wikipedia.org/wiki/Sant_Joan_del_Pla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157578,'08055','Mare de Déu de la Concepció','iglesia','monumentos_osm','La Mare de Déu de la Concepció del Bosc és l''antiga capella del mas el Bosc, del terme municipal de Castellcir, al Moianès. Està situada a prop del límit amb Sant Quirze Safaja.',41.7533998,2.1684911,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Concepció_del_Bosc');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157579,'08055','Sant Andreu de Castellcir','iglesia','monumentos_osm','Sant Andreu de Castellcir és l''antiga església parroquial del poble de Castellcir, en el terme municipal homònim, a la comarca del Moianès. És inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7601091,2.1606962,'https://ca.wikipedia.org/wiki/Sant_Andreu_de_Castellcir');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157580,'08055','Sant Martí de la Roca','iglesia','monumentos_osm','Sant Martí de la Roca, o Sant Martí del Castell, és l''antiga capella del Castell de Castellcir, al terme municipal de Castellcir, al Moianès. És al capdamunt del penyal que allotja el castell popularment conegut com la Popa, per la forma del mateix roc.',41.7742556,2.1769136,'https://ca.wikipedia.org/wiki/Sant_Martí_de_la_Roca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157581,'08055','Sant Miquel d''Argelaguer','iglesia','monumentos_osm','Sant Miquel d''Argelaguer és una antiga capella del terme municipal de Castellcir, al Moianès. Està situada al paratge de Vilacís, a prop i al nord-oest de Ca l''Antoja, al nord-est de l''actual poble de Castellcir i al nord de l''església parroquial antiga de Sant Andreu de Castellcir.',41.7670933,2.1594055,'https://ca.wikipedia.org/wiki/Sant_Miquel_d''Argelaguer');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157582,'25904','Sant Feliu de Guàrdia','iglesia','monumentos_osm','Sant Feliu de Guàrdia fou la primitiva església parroquial de Guàrdia de Tremp. Estava emplaçada en el lloc on hi hagué el poble primitiu, a mig aire de la serra on hi ha el Castell de Guàrdia.',42.1014817,0.8751365,'https://ca.wikipedia.org/wiki/Sant_Feliu_de_Guàrdia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157583,'25904','Sant Gregori','iglesia','monumentos_osm','L''església de Sant Gregori de Vilamolat de Mur fou una església del terme municipal de Castell de Mur, a l''antic terme de Mur. Estava situada al nord del poble de Vilamolat de Mur.',42.1305882,0.842139,'https://ca.wikipedia.org/wiki/Sant_Gregori_de_Vilamolat_de_Mur');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157584,'25904','Sant Miquel','iglesia','monumentos_osm','Sant Miquel de Moror és l''església parroquial, romànica, del poble de Moror, del terme municipal de Sant Esteve de la Sarga, al Pallars Jussà. Fou construïda entre els segles xi i xii, posteriorment modificada.',42.0790117,0.8348658,'https://ca.wikipedia.org/wiki/Sant_Miquel_de_Moror');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157585,'25904','Sant Miquel de Collmorter','iglesia','monumentos_osm','Sant Miquel de Collmorter és una església romànica tardana del lloc de Collmorter, a l''antic terme de Mur i actual de Castell de Mur, al Pallars Jussà. La capella de Sant Miquel de Casa Francisco és el que queda d''aquesta església, situada a l''extrem de ponent del poblet.',42.1035362,0.8633776,'https://ca.wikipedia.org/wiki/Sant_Miquel_de_Collmorter');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157586,'25904','Sant Salvador d''Estorm','iglesia','monumentos_osm','Sant Salvador d''Estorm és una església romànica del poble d''Estorm, en el terme municipal de Sant Esteve de la Sarga. És un temple de la segona meitat del segle xi, amb arcuacions llombardes i lesenes a l''absis.',42.08615,0.841072,'https://ca.wikipedia.org/wiki/Sant_Salvador_d''Estorm');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157587,'25196','Mare de Déu d''Arbul','iglesia','monumentos_osm','El santuari de la Mare de Déu d''Arbul pertany a l''antic terme de Fígols de Tremp, integrat actualment en el de Tremp, de la comarca del Pallars Jussà. És un temple d''origen romànic situat a 932 m d''altitud, a l''antic lloc d''Arbul, al sud-oest de Montllobar i, per tant, a prop de Fígols de Tremp.',42.1268903,0.785595,'https://ca.wikipedia.org/wiki/Mare_de_Déu_d''Arbul');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157588,'25196','Sant Esteve','iglesia','monumentos_osm','Sant Esteve de la Sarga és una església parroquial del terme municipal de Sant Esteve de la Sarga, situada en el poble del mateix nom. És una obra inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.0789324,0.7643616,'https://ca.wikipedia.org/wiki/Sant_Esteve_de_la_Sarga_(església)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157589,'25196','Sant Esteve de Castellnou de Montsec','iglesia','monumentos_osm','''Sant Esteve de Castellnou de Montsec és l''església parroquial, romànica, del poble de Castellnou de Montsec, del terme municipal de Sant Esteve de la Sarga, al Pallars Jussà. Fou construïda entre al segle xi, però fou posteriorment modificada del tot.',42.1020806,0.7655402,'https://ca.wikipedia.org/wiki/Sant_Esteve_de_Castellnou_de_Montsec');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157590,'25196','Sant Gregori del Mas d''Eloi','iglesia','monumentos_osm','L''església de Sant Gregori del Mas d''Eloi és una església de la caseria del Mas d''Eloi, pertanyent a l''antic terme de Mur, actualment inclòs en el de Castell de Mur. Està situada al costat del mas d''aquest nom, a l''extrem nord-oest del terme, prop del límit amb Tremp i del poble de Puigverd (Tremp), del terme de la…',42.1276319,0.7983126,'https://ca.wikipedia.org/wiki/Sant_Gregori_del_Mas_d''Eloi');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157591,'25196','Sant Martí','iglesia','monumentos_osm','L''església de Sant Martí del Meüll és una església del poble del Meüll, pertanyent a l''antic terme de Mur, actualment inclòs en el de Castell de Mur, al Pallars Jussà. És un temple romànic, situat en el lloc on hi hagué el Castell del Meüll.',42.118645,0.8130641,'https://ca.wikipedia.org/wiki/Sant_Martí_del_Meüll');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157592,'25039','Mare de Déu d''Arboló','iglesia','monumentos_osm','L''ermita de la Mare de Déu d''Arboló és una capella del terme municipal de Soriguera, a la comarca del Pallars Sobirà. Pertany al territori del poble d''Arcalís, dins de l''antic terme d''Estac.',42.3353599,1.0660912,'https://ca.wikipedia.org/wiki/Mare_de_Déu_d''Arboló');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157593,'25039','Sant Andreu','iglesia','monumentos_osm','Sant Andreu de Baén és una església parroquial romànica del poble de Baén, pertanyent al terme de Baix Pallars, del Pallars Sobirà. Formava part de l''antic terme de Baén.',42.326515,1.1056864,'https://ca.wikipedia.org/wiki/Sant_Andreu_de_Baén');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157594,'25039','Sant Clem','iglesia','monumentos_osm','Sant Clem -Sant Climent- de Mencui és l''església del poble de Mencui, en el terme municipal de Soriguera, a la comarca del Pallars Sobirà. Pertanyia a l''antic terme d''Estac.',42.3808108,1.0425431,'https://ca.wikipedia.org/wiki/Sant_Clem_de_Mencui');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157595,'25039','Sant Esteve d''Enseu','iglesia','monumentos_osm','Sant Esteve d''Enseu és una església romànica del poble d''Enseu, pertanyent al terme de Baix Pallars, del Pallars Sobirà. Pertangué a l''antic terme de Gerri de la Sal.',42.3251859,1.0836132,'https://ca.wikipedia.org/wiki/Sant_Esteve_d''Enseu');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157596,'25039','Sant Feliu','iglesia','monumentos_osm','Sant Feliu de Gerri de la Sal és l''església parroquial de la vila de Gerri de la Sal, de l''antic terme municipal del mateix nom, i de l''actual de Baix Pallars, a la comarca del Pallars Sobirà. Està situada a la mateixa vila de Gerri, a la dreta de la Noguera Pallaresa, dins de la vila vella.',42.3234048,1.065317,'https://ca.wikipedia.org/wiki/Sant_Feliu_de_Gerri_de_la_Sal');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157597,'17170','Santa Cecília de Ragort','iglesia','monumentos_osm','Santa Cecília de Ragort és una obra del municipi de Vallfogona de Ripollès (Ripollès) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.1965705,2.2922792,'https://ca.wikipedia.org/wiki/Santa_Cecília_de_Ragort');
