INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157599,'17170','Santa Maria del Pòpulo','iglesia','monumentos_osm','Santa Maria del Pòpulo era una església de Vallfogona de Ripollès, la torre de la qual està inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.1959282,2.3032426,'https://ca.wikipedia.org/wiki/Santa_Maria_del_Pòpulo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157600,'46074','Ermita de Sant Joan','iglesia','monumentos_osm','L''ermita de Sant Joan és un temple situat al municipi de Bonrepòs i Mirambell, en la comarca de l''Horta Nord (València). Está catalogada com a Bé de Rellevància Local amb identificador nombre 46.13.074-003.',39.5189421,-0.3702294,'https://ca.wikipedia.org/wiki/Ermita_de_Sant_Joan_de_Mirambell');
