INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157605,'17194','Mare de Déu del Far','iglesia','monumentos_osm','El Santuari del Far és una església de Susqueda (Selva) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. El Santuari de la Mare de Déu del Far corona la punta d''una colossal i impressionant cinglera, de silueta inconfusible, a 1.123 metres d''altitud.',42.0211767,2.5365991,'https://ca.wikipedia.org/wiki/Santuari_del_Far');
