INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157621,'20029','Santa Maria','iglesia','monumentos_osm','La parroquia de Nuestra Señora de la Asunción​ más conocida como iglesia de Santa María la Real o simplemente iglesia de Santa María (en euskera: Andra Mari Eliza) es un templo católico situando en la localidad guipuzcoana de Deva en el País Vasco, España. Es un gran edificio gótico-renacentista que se comenzó a…',43.2947753,-2.3533104,'https://es.wikipedia.org/wiki/Iglesia_de_Santa_María_(Deva)');
