INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157639,'17217','Mare de Deu de l''Om','iglesia','monumentos_osm','El santuari de Santa Maria de l''Om és una església de Ventalló (Alt Empordà) protegida com a bé cultural d''interès local. És un temple situat al nord-oest del petit nucli de Pelacalç, a llevant del municipi de Ventalló al qual pertany.',42.1500867,3.0636597,'https://ca.wikipedia.org/wiki/Santa_Maria_de_l''Om_(Ventalló)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157640,'07002','Santuari de Cura','iglesia','monumentos_osm','El santuari de Cura és el conjunt religiós situat al cim del puig de Randa i que, segons la tradició, ocupa el lloc on es va retirar i va rebre la il·luminació Ramon Llull. A més, s''hi ret culte a la Mare de Déu de Cura.',39.5276118,2.9260315,'https://ca.wikipedia.org/wiki/Santuari_de_Cura');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157641,'17076','Església de Sant Feliu de la Garriga','iglesia','monumentos_osm','Sant Feliu de la Garriga és una església al terme de Viladamat (l''Alt Empordà). Està situada al sud del terme, al peu del Puig Segalar, s''hi accedeix des del nucli urbà, des de Palau Borrell i des d''un camí que neix a la carretera C-31.',42.1191177,3.0532993,'https://ca.wikipedia.org/wiki/Sant_Feliu_de_la_Garriga');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157642,'17076','Església de Sant Sadurní de Garrigoles','iglesia','monumentos_osm','Sant Sadurní de Garrigoles es troba al bell mig de les masies que formen el poble de Garrigoles. És una obra inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.1072753,3.0305832,'https://ca.wikipedia.org/wiki/Sant_Sadurní_de_Garrigoles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157643,'17076','Sant Grau d''Albons','iglesia','monumentos_osm','Sant Grau és un santuari a uns 2km a l''oest del poble d''Albons, a la serra del seu nom, prop de la font de la Merla. A més de Sant Grau s''hi veneren Sant Roc i Sant Sebastià.',42.1093727,3.0591853,'https://ca.wikipedia.org/wiki/Sant_Grau_d''Albons');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157644,'08158','Ermita de la Salut','iglesia','monumentos_osm','L''Ermita de la Salut o Santa Eulàlia de Madrona és una església ubicada a la serra de Collserola vora el Puig Madrona, al municipi del Papiol (Baix Llobregat), catalogada com a bé cultural d''interès local.',41.4492883,2.0253058,'https://ca.wikipedia.org/wiki/Ermita_de_la_Salut_(el_Papiol)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157645,'08158','Santa Eulàlia del Papiol','iglesia','monumentos_osm','Santa Eulàlia del Papiol és l''església parroquial del Papiol i és inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. És la zona del nucli antic de la vila, concretament de l''anomenada plaça de l''Església.',41.4390951,2.0104738,'https://ca.wikipedia.org/wiki/Santa_Eulàlia_del_Papiol');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157646,'90841','Parroquia de San Pedro Apóstol','iglesia','monumentos_osm','La iglesia de San Pedro Apóstol es un inmueble de la localidad española de Aldeanueva de la Vera, en la provincia de Cáceres.',40.1301213,-5.6986726,'https://es.wikipedia.org/wiki/Iglesia_de_San_Pedro_Apóstol_(Aldeanueva_de_la_Vera)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157647,'03001','Ermita de las Santas Justa y Rufina','iglesia','monumentos_osm','La Ermita de las Santas Justa y Rufina se localiza en el municipio de Agost, Alicante, España. Fue construida en 1821, siendo reformada en 1912 y restaurada muy cuidadosamente en 1995.​ Es una ermita de pequeñas dimensiones situada entre medianeras que se muestra como la expresión del oficio de alfarero, cuyas…',38.441139,-0.6383762,'https://es.wikipedia.org/wiki/Ermita_de_las_Santas_Justa_y_Rufina_(Agost)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157648,'03001','Església Parroquial de Sant Pere','iglesia','monumentos_osm','La iglesia de San Pedro Apóstol de Agost (Provincia de Alicante) fue construida en el siglo XVI, si bien cuenta con reformas posteriores del siglo XVIII en el que se realizan la capilla de la comunión y la portada lateral. Se trata de un edificio exento con dos cúpulas: una que corona la torre, haciendo un extraño…',38.4395502,-0.6387965,'https://es.wikipedia.org/wiki/Iglesia_de_San_Pedro_Apóstol_(Agost)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157649,'03041','Església de la Puríssima Xiqueta','iglesia','monumentos_osm','La Basílica Menor de la Puríssima Concepció i Sant Pere Apòstol és un temple catòlic al municipi valencià de Benissa (Marina Alta).',38.7149466,0.0505238,'https://ca.wikipedia.org/wiki/Església_de_la_Puríssima_Xiqueta');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157650,'07042','Parroquia Mare de Déu Dels Àngels','iglesia','monumentos_osm','L''Església de Nostra Senyora dels Àngels és la parròquia del poble de Pollença. Segons els "Paborde de Tarragona", el Dr.',39.8773358,3.0158331,'https://ca.wikipedia.org/wiki/Església_de_Nostra_Senyora_dels_Àngels_de_Pollença');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157651,'90945','Santa Engrazia baseliza','iglesia','monumentos_osm','Santa Engrazia baseliza Gipuzkoako Zestoa udalerriko Aizarna auzoaren lursailetan dagoen baseliza bat da. Aizarnako herrigunetik urrun dago, Santa Engrazia muino edo mendiaren tontorrean.',43.2208198,-2.2085033,'https://eu.wikipedia.org/wiki/Santa_Engrazia_baseliza_(Aizarna)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157652,'47129','Iglesia de San Millán','iglesia','monumentos_osm','La iglesia de San Millán es un templo católico ubicado en la localidad de Quintanilla de Onésimo, provincia de Valladolid, Castilla y León, España.',41.6260091,-4.3652521,'https://es.wikipedia.org/wiki/Iglesia_de_San_Millán_(Quintanilla_de_Onésimo)');
