INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157654,'17175','Ermita de Sant Sebastià','iglesia','monumentos_osm','Ermita de Sant Sebastià és una església del municipi de Sant Miquel de Fluvià (Alt Empordà) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.1807297,2.9885773,'https://ca.wikipedia.org/wiki/Ermita_de_Sant_Sebastià_(Sant_Miquel_de_Fluvià)');
