INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157659,'11042','Iglesia de Santa María de la Mesa','iglesia','monumentos_osm','La iglesia de Santa María de la Mesa, también Santa María de la Meza (Carrasco Terriza 1992, 463​) es un templo de la localidad de Zahara de la Sierra, provincia de Cádiz, España, que constituye una destacada muestra de la arquitectura religiosa andaluza de la segunda mitad del siglo XVIII,​ marcada por la plenitud…',36.8404944,-5.3901565,'https://es.wikipedia.org/wiki/Iglesia_de_Santa_María_de_la_Mesa_(Zahara_de_la_Sierra)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157660,'08039','Ermita de Sant Guillem','iglesia','monumentos_osm','Sant Guillem és el conjunt format per una ermita i una masia al municipi de Campins (Vallès Oriental) que forma part de l''Inventari del Patrimoni Arquitectònic de Catalunya. A prop hi ha la Creu de Sant Guillem.',41.7197887,2.468837,'https://ca.wikipedia.org/wiki/Sant_Guillem_de_Campins');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157661,'08039','Ermita de Santa Fe del Montseny','iglesia','monumentos_osm','Santa Fe és una ermita al poble de Santa Fe del Montseny (Vallès Oriental) catalogada a l''Inventari del Patrimoni Arquitectònic de Catalunya. La capella de Santa Fe del Montseny és el centre històric de la vall i el que li ha donat el nom.',41.7738715,2.4648498,'https://ca.wikipedia.org/wiki/Ermita_de_Santa_Fe_del_Montseny');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157662,'90778','Basilica Nuestra Señora de Candelaria','iglesia','monumentos_osm','La Basílica​ y Real Santuario​ Mariano de Nuestra Señora de Candelaria es el primer templo mariano del Archipiélago Canario.​ Esta basílica se encuentra en el municipio de Candelaria en la isla de Tenerife (Canarias, España). Está situada a 20 kilómetros al sur de la capital de la isla, Santa Cruz de Tenerife.',28.3512166,-16.3699075,'https://es.wikipedia.org/wiki/Basílica_de_Nuestra_Señora_de_la_Candelaria');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157663,'90778','Iglesia de Santa Ana','iglesia','monumentos_osm','La parroquia de Santa Ana es la parroquia matriz del municipio de Candelaria (Tenerife, Islas Canarias, España).',28.3519506,-16.3712911,'https://es.wikipedia.org/wiki/Iglesia_de_Santa_Ana_(Candelaria)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157664,'47030','Iglesia de Santo Domingo de Guzmán','iglesia','monumentos_osm','La iglesia de Santo Domingo de Guzmán es una iglesia católica de la localidad de Campaspero, en la provincia de Valladolid, comunidad autónoma de Castilla y León, España.',41.4915305,-4.1949292,'https://es.wikipedia.org/wiki/Iglesia_de_Santo_Domingo_de_Guzmán_(Campaspero)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157665,'40081','Iglesia de San Juan Bautista','iglesia','monumentos_osm','La iglesia de san Juan Bautista en la localidad de Fuentes de Cuéllar (municipio de Cuéllar), (provincia de Segovia, Castilla y León, España) es un templo católico cuya construcción se inició en la Alta Edad Media, en estilo románico. Levantada hacia el segundo cuarto del siglo XIII, se trató inicialmente de un…',41.4145089,-4.215355,'https://es.wikipedia.org/wiki/Iglesia_de_San_Juan_Bautista_(Fuentes_de_Cuéllar)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157666,'40081','Iglesia de San Pedro Apóstol','iglesia','monumentos_osm','La iglesia de San Pedro Apóstol de Dehesa de Cuéllar, municipio de Cuéllar, provincia de Segovia, comunidad autónoma de Castilla y León, España; es un templo católico, de estilo románico con reformas del siglo XVI.',41.3970148,-4.2355738,'https://es.wikipedia.org/wiki/Iglesia_de_San_Pedro_Apóstol_(Dehesa_de_Cuéllar)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157667,'27047','Igrexa de San Xián de Veiga','iglesia','monumentos_osm','A Igrexa de San Xián de Veiga é un templo románico situado na parroquia de Veiga, no concello lugués da Pobra do Brollón, que data do século XII, sendo o máis antigo que se atopa nese concello.',42.5953222,-7.4115674,'https://gl.wikipedia.org/wiki/Igrexa_de_San_Xián_de_Veiga');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157668,'17180','Mare de Déu d''Argimon','iglesia','monumentos_osm','La Mare de Déu d''Argimon és una petita capella romànica que fou afegida al castell d''Argimon segurament ja al segle x. La primera referència, el 1050, esmenta la fortificació propietat de Ponç Guerau de Cabrera; Ramon Berenguer III, comte de Barcelona, va cedir a Guerau Ponç, vescomte de Cabrera, el territori que…',41.8305749,2.6359214,'https://ca.wikipedia.org/wiki/Mare_de_Déu_d''Argimon');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157669,'17180','Mare de Déu de Farners','iglesia','monumentos_osm','L''església de la Mare de Déu de Farners és una ermita construïda als peus del castell de Farners, a 5 quilòmetres de Santa Coloma de Farners. El seu estil és una barreja de romànic i barroc, a causa de l''ampliació que va patir l''ermita a posterior.',41.8600506,2.6328741,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Farners');
