INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157672,'17180','Sant Martí','iglesia','monumentos_osm','Sant Martí de l''Esparra és una església parroquial de Riudarenes (Selva) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. En concret, està situada al nucli de l''Esparra.',41.8263054,2.6575817,'https://ca.wikipedia.org/wiki/Sant_Martí_de_l''Esparra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157673,'47159','Iglesia de San Pedro','iglesia','monumentos_osm','La iglesia de San Pedro es una iglesia de España, situada en el municipio de Serrada, perteneciente a la provincia de Valladolid (comunidad autónoma de Castilla y León). La construcción del templo data del último tercio del siglo XVII, y se finaliza en 1773, fecha en la que se levantaron los últimos cuerpos de la…',41.457335,-4.8621531,'https://es.wikipedia.org/wiki/Iglesia_de_San_Pedro_(Serrada)');
