INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157678,'01027','iglesia de Santa Lucía','iglesia','monumentos_osm','La iglesia de Santa Lucía es un edificio en ruinas situado en el despoblado español de Izarza, en la provincia de Álava.',42.7805606,-2.558478,'https://es.wikipedia.org/wiki/Iglesia_de_Santa_Lucía_(Izarza)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157679,'90815','Iglesia de San Juan Evangelista','iglesia','monumentos_osm','La iglesia de San Juan Evangelista en Arroyo de la Encomienda, Valladolid es una iglesia de estilo románico, construida en el siglo XII. También se la conoce como iglesia de San Juan Ante Portam Latinam.',41.6090897,-4.7977679,'https://es.wikipedia.org/wiki/Iglesia_de_San_Juan_Evangelista_(Arroyo_de_la_Encomienda)');
