INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157681,'17166','Ermita de Sant Mateu','iglesia','monumentos_osm','Sant Mateu és una església al veïnat homònim al terme de Sant Jordi Desvalls (Gironès) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. És una petita capella de planta rectangular acabada en un absis semicircular, a nivell més baix, a la capçalera i teulada a doble vessant coberta de teula.',42.0899344,2.9604071,'https://ca.wikipedia.org/wiki/Sant_Mateu_de_Sant_Jordi_Desvalls');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157682,'17166','Església de Sant Jordi Desvalls','iglesia','monumentos_osm','L''Església de Sant Jordi Desvalls és una església barroca de Sant Jordi Desvalls (Gironès) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.0721087,2.9536973,'https://ca.wikipedia.org/wiki/Església_de_Sant_Jordi_Desvalls');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157683,'17166','Sant Feliu de Diana','iglesia','monumentos_osm','L''església de Sant Feliu de Diana es troba al veïnat de Diana, situat a la part septentrional del terme de Sant Jordi Desvalls, a una dos quilòmetres d''aquesta població.',42.085187,2.9536266,'https://ca.wikipedia.org/wiki/Sant_Feliu_de_Diana');
