INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157692,'25913','Santa Cecília de Beders','iglesia','monumentos_osm','Santa Cecília de Beders és una petita església romànica de Beders, al municipi de Bellver de Cerdanya (Cerdanya). Santa Cecília de Beders, que depèn de l''antiga parròquia de Coborriu de Bellver, és citada a l''Acta de consagració de la Catedral d''Urgell (839).',42.3530329,1.8051655,'https://ca.wikipedia.org/wiki/Santa_Cecília_de_Beders');
