INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157694,'08274','Sant Julià de Coaner','iglesia','monumentos_osm','Sant Julià de Coaner és una església del poble de Coaner, al municipi de Sant Mateu de Bages (Bages). És una església romànica inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya i protegida com Bé Cultural d''Interès Local.',41.8322651,1.7134022,'https://ca.wikipedia.org/wiki/Sant_Julià_de_Coaner');
