INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157702,'43061','Església de Sant Miquel','iglesia','monumentos_osm','Sant Miquel de Forès és una església romànica de Forès (Conca de Barberà) situada al cim del turó on s''assenta el poble. Es troba a un nivell més baix del carrer pel costat de migdia, cosa que fa que per accedir per la porta original calgui baixar unes escales.',41.494502,1.2383901,'https://ca.wikipedia.org/wiki/Sant_Miquel_de_Forès');
