INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157738,'17091','Mare de Déu del Roure','iglesia','monumentos_osm','La Capella del Roure és una petita capella de Camprodon (Ripollès). Originàriament era un petit oratori de camí situat a la sortida de la vila en direcció a Molló.',42.3152796,2.3782515,'https://ca.wikipedia.org/wiki/Capella_del_Roure_(Camprodon)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157739,'17091','Monestir de Sant Pere de Camprodon','iglesia','monumentos_osm','Sant Pere de Camprodon és un monestir benedictí situat a l''actual vila de Camprodon, al Ripollès.',42.314315,2.3695932,'https://ca.wikipedia.org/wiki/Sant_Pere_de_Camprodon');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157740,'17091','Sant Antoni','iglesia','monumentos_osm','Sant Antoni de Freixenet és una ermita o santuari al municipi de Camprodon (Ripollès) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. Es troba al cim de la muntanya de Sant Antoni Vell (1.361), just al sud del nucli urbà de Camprodon.',42.3051488,2.3757418,'https://ca.wikipedia.org/wiki/Sant_Antoni_de_Freixenet');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157741,'17084','Sant Iscle i Santa Victòria de Sanavastre','iglesia','monumentos_osm','Sant Iscle i Santa Victòria de Sanavastre és una església romànica del poble de Sanavastre, al municipi de Das, a la Cerdanya. Està protegida com a bé cultural d''interès local.',42.3851979,1.8497478,'https://ca.wikipedia.org/wiki/Sant_Iscle_i_Santa_Victòria_de_Sanavastre');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157742,'17084','Sant Pere','iglesia','monumentos_osm','L''església de Sant Pere d''Olopte es troba a la part alta d''un petit promontori a l''esquerra de l''entrada del poble d''Olopte, a la comarca de la Baixa Cerdanya. La parròquia era originalment sota l''advocació de Sant Feliu i com moltes de les esglésies d''aquesta zona està documentada a la falsa acta de consagració de…',42.3916402,1.8132951,'https://ca.wikipedia.org/wiki/Sant_Pere_d''Olopte');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157743,'17084','Sant Policarp de Cortàs','iglesia','monumentos_osm','Sant Policarp de Cortàs és l''església de l''entitat de població de Cortàs, pertanyent al municipi de Bellver de Cerdanya, a la comarca de la Baixa Cerdanya, inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya Surt anomenada, al costat de la parròquia d''Éller a la fi del segle x a l''acta de consagració de…',42.39887,1.8012761,'https://ca.wikipedia.org/wiki/Sant_Policarp_de_Cortàs');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157744,'17084','Santa Maria d''All','iglesia','monumentos_osm','Santa Maria d''All és una església de l''entitat de població d''All, pertanyent al municipi d''Isòvol (Cerdanya). Forma part de l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.3978419,1.8386262,'https://ca.wikipedia.org/wiki/Santa_Maria_d''All');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157745,'17084','Santa Maria de Quadres','iglesia','monumentos_osm','Santa Maria de Quadres és una església del municipi d''Isòvol (Cerdanya) protegida com a bé cultural d''interès local.',42.3864846,1.8370784,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Quadres');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157746,'18008','Mare de Déu dels Àngels','iglesia','monumentos_osm','L''església de la Mare de Déu dels Àngels de Llívia és una obra del municipi de Llívia (Cerdanya) que s''aixecà els segles xvi i xvii sobre d''una altra d''anterior, aprofitant-ne els materials. Ambdós edificis estan inventariats de manera separada: l''església forma part de l''Inventari del Patrimoni Arquitectònic de…',42.4652591,1.9821182,'https://ca.wikipedia.org/wiki/Mare_de_Déu_dels_Àngels_de_Llívia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157747,'08114','Església de Santa Maria','iglesia','monumentos_osm','Santa Maria de Martorell és una obra del municipi de Martorell (Baix Llobregat) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.4745946,1.9278593,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Martorell');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157748,'08239','Sant Quirze','iglesia','monumentos_osm','Sant Quirze i Santa Julita és l''església parroquial romànica del poble de Sant Quirze Safaja (Moianès) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. És al punt més elevat del poble de Sant Quirze Safaja, al capdamunt del carrer Major.',41.7278987,2.1550867,'https://ca.wikipedia.org/wiki/Església_de_Sant_Quirze_Safaja');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157749,'17196','Ermita de Santa Magdalena','iglesia','monumentos_osm','Ermita de Santa Magdalena és una església del municipi de Terrades (Alt Empordà) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.3244992,2.8258637,'https://ca.wikipedia.org/wiki/Ermita_de_Santa_Magdalena_(Terrades)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157750,'17196','Santuari de la Mare de Déu de la Salut','iglesia','monumentos_osm','Santuari de la Mare de Déu de la Salut és una església del municipi de Terrades (Alt Empordà) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.3253313,2.8342872,'https://ca.wikipedia.org/wiki/Santuari_de_la_Mare_de_Déu_de_la_Salut_(Terrades)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157751,'17202','Sant Vicenç','iglesia','monumentos_osm','Sant Vicenç de Tossa és una església del municipi de Tossa de Mar a la comarca de la Selva. És un edifici de grans dimensions al mig de la Vila Nova de Tossa que es basa en una nau central i capelles laterals.',41.7179482,2.9308284,'https://ca.wikipedia.org/wiki/Sant_Vicenç_de_Tossa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157752,'17212','Sant Bartomeu de Covildases','iglesia','monumentos_osm','Sant Bartomeu de Covildases és una antiga (segle xii) església romànica sufragània que pertany a la parròquia del municipi de Vidrà (Osona). Va rebre el nom de l''antiga vila de Covildases (960).',42.123646,2.3609098,'https://ca.wikipedia.org/wiki/Sant_Bartomeu_de_Covildases');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157753,'17212','Sant Jaume del Barretó','iglesia','monumentos_osm','Sant Jaume del Barretó és un església romànica i gòtica del terme municipal de Ripoll (Ripollès). Era una sufragània de la parroquial de Sant Bartomeu de Llaés.',42.1476465,2.2899015,'https://ca.wikipedia.org/wiki/Sant_Jaume_del_Barretó');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157754,'17212','Sant Nazari','iglesia','monumentos_osm','La Capella de Sant Nazari és una obra de Sant Pere de Torelló (Osona) protegida com a Bé Cultural d''Interès Local.',42.0981768,2.3739741,'https://ca.wikipedia.org/wiki/Capella_de_Sant_Nazari');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157755,'17212','Santa Margarida de Cabagés','iglesia','monumentos_osm','Santa Margarida de Cabagés és una església romànica de Vidrà (Osona) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.1523759,2.3197569,'https://ca.wikipedia.org/wiki/Santa_Margarida_de_Cabagés');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157756,'17212','Santuari de Bellmunt','iglesia','monumentos_osm','El santuari de Bellmunt és un santuari del municipi de Sant Pere de Torelló (Osona) que està situat al cim de la serra de Bellmunt, a 1.246 m d''altitud. Disposa d''un mirador des d''on es veu la plana de Vic, els Pirineus, la vall del Ges i el Bisaura.',42.1019094,2.2946878,'https://ca.wikipedia.org/wiki/Santuari_de_Bellmunt');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157757,'90891','Església de Sant Cebrià de Lledó','iglesia','monumentos_osm','L''Església de Sant Cebrià de Lledó o Església dels Metges és un temple del poble de Sant Cebrià de Lledó, al municipi de Cruïlles, Monells i Sant Sadurní de l''Heura (Baix Empordà). És un edifici inclòs en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9124674,2.9668452,'https://ca.wikipedia.org/wiki/Església_de_Sant_Cebrià_de_Lledó');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157758,'90891','Sant Cebrià dels Alls','iglesia','monumentos_osm','Sant Cebrià dels Alls, també anomenat Camós, és un poble (una parròquia) que forma part de l''antic municipi de Cruïlles, esdevingut per fusió a mitjans del Segle XX l''actual municipi de Cruïlles, Monells i Sant Sadurní de l''Heura. Situat a 400 metres d''altitud, és un dels molts poblets del massís de les Gavarres…',41.8873537,3.0146801,'https://ca.wikipedia.org/wiki/Sant_Cebrià_dels_Alls');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157759,'08276','Santa Maria de Tagamanent','iglesia','monumentos_osm','Santa Maria de Tagamanent és una església del municipi de Tagamanent (Vallès Oriental), situada al cim del turó de Tagamanent dins del castell de Tagamanent. Forma part de l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7476518,2.2960408,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Tagamanent');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157760,'17110','Sant Ramon d''Ermedàs','iglesia','monumentos_osm','Sant Ramon d''Ermedàs és una església d''Ermedàs (Baix Empordà), catalogada com a bé cultural d''interès local.',41.8944392,3.1636983,'https://ca.wikipedia.org/wiki/Sant_Ramon_d''Ermedàs');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157761,'17109','Mare de Déu del Cós','iglesia','monumentos_osm','Mare de Déu del Cós és una capella del municipi de Montagut i Oix (Garrotxa) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. Està situada a la muntanya del Cós dintre el recinte de l''antic Castell de Montagut.',42.2307481,2.5724641,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Cós');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157762,'17109','Sant Eudald de Jou','iglesia','monumentos_osm','L''ermita de Sant Eudald de Jou (també anomenat Sant Eudald dels Vilars), situada al terme municipal de Montagut i Oix, és d''origen romànic. És un edifici d''una sola nau amb un absis semicircular molt modificat el segle xvii.',42.2459688,2.5701954,'https://ca.wikipedia.org/wiki/Sant_Eudald_de_Jou');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157763,'17109','Sant Pere de Montagut','iglesia','monumentos_osm','Sant Pere de Montagut és una església del s. XII amb reformes posteriors que es troba al poble de Montagut, al municipi de Montagut i Oix, a la Garrotxa.',42.2301767,2.5964889,'https://ca.wikipedia.org/wiki/Sant_Pere_de_Montagut');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157764,'17109','Santa Bàrbara de Pruneres','iglesia','monumentos_osm','Santa Bàrbara de Pruneres és una església d''Oix, al municipi de Montagut i Oix (Garrotxa). Enclavada a la serra de Santa Bàrbara, al bell mig de l''Alta Garrotxa, s''hi observa una panoràmica excepcional sobre la vall d''Oix, el Bassegoda, el Ferran, etc.',42.2754308,2.55886,'https://ca.wikipedia.org/wiki/Santa_Bàrbara_de_Pruneres');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157765,'17109','Santa Cecília de Sadernes','iglesia','monumentos_osm','Santa Cecília de Sadernes és un monument del municipi de Sales de Llierca (Garrotxa) inclòs en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.270067,2.5961013,'https://ca.wikipedia.org/wiki/Santa_Cecília_de_Sadernes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157766,'17037','Sant Cristòfol','iglesia','monumentos_osm','Sant Cristòfol de Ventolà és una església romànica del municipi de Ribes de Freser, a la comarca catalana del Ripollès. És una obra inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.3176368,2.1373955,'https://ca.wikipedia.org/wiki/Sant_Cristòfol_de_Ventolà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157767,'25069','Sant Miquel de Castelló de Farfanya','iglesia','monumentos_osm','Sant Miquel de Castelló de Farfanya és l''església parroquial de la vila de Castelló de Farfanya, al municipi homònim de la Noguera.',41.8205702,0.72764,'https://ca.wikipedia.org/wiki/Sant_Miquel_de_Castelló_de_Farfanya');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157768,'25069','Santa Maria','iglesia','monumentos_osm','Santa Maria de Castelló de Farfanya és l''església del castell de Castelló de Farfanya, al municipi homònim de la Noguera, inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.8212164,0.7263744,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Castelló_de_Farfanya');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157769,'08201','Mare de Déu dels Munts','iglesia','monumentos_osm','El Santuari de la Mare de Déu dels Munts és una església barroca de Sant Agustí de Lluçanès (Osona) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.0784771,2.1523908,'https://ca.wikipedia.org/wiki/Santuari_de_la_Mare_de_Déu_dels_Munts');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157770,'08201','Sant Baldiri','iglesia','monumentos_osm','L''Església de Sant Boi de Lluçanès és una església catalogada com a monument del municipi de Sant Boi de Lluçanès (Osona) i inclosa en l''Inventari del Patrimoni Arquitectònic Català.',42.0577335,2.1517191,'https://ca.wikipedia.org/wiki/Església_de_Sant_Boi_de_Lluçanès');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157771,'08201','Sant Miquel de Gallifa','iglesia','monumentos_osm','Sant Miquel de Gallifa és una església romànica al veïnat de Gallifa al municipi de Sant Boi de Lluçanès (Osona) inclòs a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.0748245,2.1789194,'https://ca.wikipedia.org/wiki/Sant_Miquel_de_Gallifa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157772,'08152','Mare de Déu de Collbàs','iglesia','monumentos_osm','Mare de Déu de Collbàs o Santuari de Collbàs és una ermita dalt d''un turó de la Serra de Collbàs. Inicialment depenia de Santa Maria del castell de Claramunt, i des de 1779 va quedar vinculada a la parròquia de Sant Marti de Carme, terme municipal al qual pertany.',41.544271,1.6084173,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Collbàs');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157773,'08152','Sant Miquel d''Orpí','iglesia','monumentos_osm','Sant Miquel d''Orpí és una església del poble d''Orpí (Anoia), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.5191964,1.5754361,'https://ca.wikipedia.org/wiki/Sant_Miquel_d''Orpí');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157774,'08152','Santa Càndia','iglesia','monumentos_osm','Santa Càndia és un temple al terme municipal d''Orpí (Anoia) catalogat a l''Inventari del Patrimoni Arquitectònic de Catalunya. L''edifici, del 1368, forma part del nucli de les cases de Santa Càndia.',41.5222803,1.5748766,'https://ca.wikipedia.org/wiki/Santa_Càndia');
