INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157777,'21023','Iglesia de Santa María de Gracia','iglesia','monumentos_osm','La iglesia parroquial de Santa María de Gracia, situada en la plaza de España de El Cerro de Andévalo (Provincia de Huelva, España), es una conjunción de los dos estilos artísticos correspondientes a las dos etapas básicas de su historia constructiva: el manierista de la segunda mitad del siglo XVI y el barroco de…',37.7352872,-6.9388864,'https://es.wikipedia.org/wiki/Iglesia_de_Santa_María_de_Gracia_(El_Cerro_de_Andévalo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157778,'17195','Sant Climent de Tor','iglesia','monumentos_osm','Sant Climent de Tor és una església romànica al centre de Tor, nucli del municipi de la Tallada d''Empordà.',42.0889618,3.0672137,'https://ca.wikipedia.org/wiki/Sant_Climent_de_Tor');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157779,'17195','Sant Esteve de Maranyà','iglesia','monumentos_osm','Sant Esteve de Marenyà és una església al nucli de Marenyà del municipi de la Tallada d''Empordà, protegida com a bé cultural d''interès local. L''església de Sant Esteve està situada a la part més elevada del nucli de Marenyà.',42.0920252,3.0464814,'https://ca.wikipedia.org/wiki/Sant_Esteve_de_Maranyà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157780,'17195','Santa Maria','iglesia','monumentos_osm','Santa Maria és l''església parroquial romànica de la Tallada d''Empordà. Està situada dins el que era l''angle nord-est del recinte del castell.',42.0800701,3.0559162,'https://ca.wikipedia.org/wiki/Santa_Maria_de_la_Tallada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157781,'08189','Sant Pere Sallavinera','iglesia','monumentos_osm','L''església de Sant Pere Sallavinera és un temple parroquial del municipi homònim (Anoia), inclòs a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7363972,1.5744612,'https://ca.wikipedia.org/wiki/Sant_Pere_Sallavinera_(església)');
