INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157784,'43157','Santa Magdalena','iglesia','monumentos_osm','Santa Magdalena, anomenada la Catedral del Montsant, és una ermita al municipi d''Ulldemolins (Priorat) protegida com a bé cultural d''interès local. Santa Magdalena va ser fundada per Fra Llorenç Julià.',41.3081306,0.8646833,'https://ca.wikipedia.org/wiki/Santa_Magdalena_d''Ulldemolins');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157785,'43157','Santa Maria de Montsant','iglesia','monumentos_osm','Santa Maria de Montsant, o la Mare de Déu de Montsant, és una ermita del municipi de la Morera de Montsant (Priorat) inclosa en l''Inventari del Patrimoni Arquitectònic Català. Es troba a 1035 m d''altitud, a dalt de la carena de la Serra del Montsant, en el seu vessant nord, a prop de la localitat d''Albarca (poble…',41.2944964,0.8918553,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Montsant');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157786,'17092','Església de Sant Vicenç','iglesia','monumentos_osm','Sant Vicenç és una església al bell mig del nucli antic de la població de Llançà, a l''extrem sud-oest del nucli urbà. El temple ocupa en gran part el solar de l''antic castell-palau dels abats de Sant Pere de Rodes.',42.363028,3.1516279,'https://ca.wikipedia.org/wiki/Sant_Vicenç_de_Llançà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157787,'17092','Església del Port','iglesia','monumentos_osm','La Mare de Deu del Port és una església dins del nucli urbà de la població de Llançà, a l''extrem de ponent del barri del Port, delimitada entre l''avinguda Pau Casals i el carrer dels Xiprers. El temple pertany al veïnat del Port de Llançà, a la parròquia de Sant Vicenç i al mateix temps és la capella del cementiri,…',42.3685191,3.1583132,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Port');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157788,'34184','Iglesia de Nuestra Señora del Castillo','iglesia','monumentos_osm','La iglesia de Santa María del Castillo es un templo de culto católico situado en la pequeña localidad palentina de Torremormojón, en España. Hasta los trabajos de restauración de 1986 el edificio se consideraba como obra del siglo XVI con yeserías renacentistas y otros enmascaramientos.',41.9616581,-4.7770468,'https://es.wikipedia.org/wiki/Iglesia_de_Santa_María_del_Castillo_(Torremormojón)');
