INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157802,'25060','Santa Maria','iglesia','monumentos_osm','Santa Maria de Coscó és l''església parroquial del poble de Coscó, al municipi d''Oliola (Noguera), inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. És al nord-est del nucli urbà de Coscó, al vessant meridional de la serra del Pitxell.',41.8221408,1.1630228,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Coscó');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157803,'25060','Sant Joan Baptista','iglesia','monumentos_osm','Sant Joan Baptista de Cabanabona és una església barroca de Cabanabona (Noguera) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.8509753,1.2149371,'https://ca.wikipedia.org/wiki/Sant_Joan_Baptista_de_Cabanabona');
