INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157805,'25060','Sant Salvador','iglesia','monumentos_osm','Sant Salvador de Vilalta és una església neoclàssica del poble de Vilalta, a Vilanova de l''Aguda (Noguera) És al centre del nucli i afronta amb la plaça de l''Església. L''església, amb rectoria adossada, té una planta en forma de creu llatina i cos alt i esvelt.',41.8505743,1.2413599,'https://ca.wikipedia.org/wiki/Sant_Salvador_de_Vilalta');
