INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157809,'90908','Església de Sant Miquel','iglesia','monumentos_osm','Sant Miquel d''Alforja és l''església parroquial d''Alforja (Baix Camp) dedicada a sant Miquel Arcàngel. D''estil barroc del segle xvii, està protegida com a bé cultural d''interès local.',41.2099834,0.9746508,'https://ca.wikipedia.org/wiki/Sant_Miquel_d''Alforja');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157810,'90908','Mare de Déu de Puigcerver','iglesia','monumentos_osm','El santuari de la Mare de Déu de Puigcerver és un edifici religiós entre els termes de Riudecols i Alforja. Agafa el seu nom del no gaire llunyà Puigcerver (de 835 metres) i es troba a la vora del límit del terme amb el terme de Riudecols.',41.1932918,0.9363336,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Puigcerver');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157811,'25222','Façana de Sant Pere','iglesia','monumentos_osm','Sant Pere de Tiurana era una església amb elements renaixentistes i barrocs de Tiurana (Noguera) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. La seva façana es va traslladar al nou poble de Tiurana.',41.9760541,1.2560372,'https://ca.wikipedia.org/wiki/Sant_Pere_de_Tiurana');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157812,'25222','Mare de Déu dels Solés','iglesia','monumentos_osm','La Mare de Déu de Solers és un santuari del municipi noguerenc de Tiurana, al Segre Mitjà, inclòs en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9760852,1.2554491,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Solers');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157813,'25222','Sant Ermengol de Tiurana','iglesia','monumentos_osm','Sant Ermengol de Tiurana és una capella del municipi de Tiurana (Noguera) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. L''església s''assenta sobre un penyal de roques, al cap de la carena del serrat de les Moles, al marge esquerre del Segre i al sud-oest de l''actual nucli de Tiurana.',41.9650132,1.2479286,'https://ca.wikipedia.org/wiki/Sant_Ermengol_de_Tiurana');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157814,'25222','Sant Girvés','iglesia','monumentos_osm','Sant Girvés és una església de la Torre de Rialb, al municipi de la Baronia de Rialb (Noguera), que forma part de l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9818702,1.201408,'https://ca.wikipedia.org/wiki/Sant_Girvés_de_la_Torre_de_Rialb');
