INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157816,'38018','Ermita de Nuestra Señora del Coromoto','iglesia','monumentos_osm','La ermita de Nuestra Señora de Coromoto está situada en el municipio de La Guancha en la isla de Tenerife (Islas Canarias, España). Dicho templo está consagrado a Nuestra Señora de Coromoto, patrona de Venezuela y se encuentra en el barrio de La Guancha de Abajo.',28.3790304,-16.6543556,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_del_Coromoto_(La_Guancha)');
