INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157820,'25132','Sant Salvador','iglesia','monumentos_osm','Sant Salvador de Massoteres és l''església parroquial de la vila de Massoteres (Segarra) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. L''edifici que data de la fi del segle xviii, s''ha feten estil barroc auster, que contrasta amb la rica tradició ornamentista de la resta de l''estat.',41.7976502,1.3107915,'https://ca.wikipedia.org/wiki/Sant_Salvador_de_Massoteres');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157821,'43103','Església de Sant Pere','iglesia','monumentos_osm','Sant Pere de Perafort és un monument del municipi de Perafort (Tarragonès) protegit com a bé cultural d''interès local. És una església de planta basilical de tres naus amb tres trams cadascuna.',41.1908982,1.2555631,'https://ca.wikipedia.org/wiki/Sant_Pere_de_Perafort');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157822,'08308','Sant Esteve del Pujol de Planès','iglesia','monumentos_osm','Sant Esteve del Pujol de Planès és una església catòlica del nucli disseminat del Pujol de Planès, al municipi de Montmajor (Berguedà). És una obra inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9663688,1.7482365,'https://ca.wikipedia.org/wiki/Sant_Esteve_del_Pujol_de_Planès');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157823,'08308','Sant Joan de Montdarn','iglesia','monumentos_osm','Sant Joan de Montdarn és una església romànica al terme municipal de Viver i Serrateix, consagrada l''any 922. Sembla que fins a l''any 1017 hi va haver una petita comunitat monàstica, i de llavors ençà és només parròquia.',41.9795828,1.7813599,'https://ca.wikipedia.org/wiki/Sant_Joan_de_Montdarn');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157824,'08308','Sant Martí de Balaguer','iglesia','monumentos_osm','Sant Martí del Balaguer és una església romànica del municipi de Viver i Serrateix (Berguedà) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9729732,1.7678658,'https://ca.wikipedia.org/wiki/Sant_Martí_del_Balaguer');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157825,'08308','Sant Miquel','iglesia','monumentos_osm','Sant Miquel de Viver és l''església parroquial de Viver, al municipi de Viver i Serrateix, i és inclòs a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9560987,1.8127198,'https://ca.wikipedia.org/wiki/Sant_Miquel_de_Viver');
