INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157832,'43067','Sant Martí','iglesia','monumentos_osm','Sant Martí és una antiga església –catalogada a l''Inventari del Patrimoni Arquitectònic de Catalunya– a l''extrem més nord del nucli urbà de la població de Ginestar, al carrer de Carme Vidal. Amb la desamortització (segle xix) va passar a mans privades i durant molts anys es va utilitzar com a magatzem particular…',41.0418741,0.6325053,'https://ca.wikipedia.org/wiki/Església_de_Sant_Martí_de_Ginestar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157833,'31025','Itxasperriko Santiago ermita','iglesia','monumentos_osm','Itsasperriko Santiago eliza Nafarroako Arakil udalerriko Itsasperri kontzejuan dagoen eliza bat da. XIII. mendearen lehen erdialdean erromaniko berantiar estiloan eraiki zen.',42.9239061,-1.8589185,'https://eu.wikipedia.org/wiki/Itxasperriko_Santiago_eliza');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157834,'12100','Convent de Santa Anna','iglesia','monumentos_osm','La iglesia pertenece al convento de las Madres Agustinas de San Mateo (provincia de Castellón, España) con el que es limítrofe. Este convento fue formado en 1590 con monjas venidas del monasterio de Agustinas de Mirambel.',40.4638542,0.1788912,'https://es.wikipedia.org/wiki/Iglesia_de_las_Madres_Agustinas_(San_Mateo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157835,'12100','Església de Sant Pere','iglesia','monumentos_osm','L''església de Sant Pere és un temple catòlic, sense ús litúrgic regular al Pla de Sant Pere de Sant Mateu (Baix Maestrat). És un edifici gòtic amb remodelació barroca.',40.4647743,0.1777878,'https://ca.wikipedia.org/wiki/Església_de_Sant_Pere_de_Sant_Mateu');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157836,'18126','Iglesia Parroquial de la Inmaculada Concepción','iglesia','monumentos_osm','La iglesia de la Inmaculada Concepción es una iglesia parroquial de la localidad española de La Malahá, en Granada. Se trata de un templo del siglo XVI que tiene influencias mudéjares como se puede ver en el alfarje, además de armaduras de madera.',37.1016857,-3.7220019,'https://es.wikipedia.org/wiki/Iglesia_Parroquial_de_la_Inmaculada_(La_Malahá)');
