INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157838,'17209','Santa Coloma de Fitor','iglesia','monumentos_osm','Santa Coloma de Fitor és una església del nucli de Fitor, al municipi de Forallac (Baix Empordà), protegida com a Bé cultural d''interès local. Està dedicada a la verge i màrtir santa Coloma i s''hi celebra un aplec el tercer diumenge d''octubre.',41.9059977,3.08679,'https://ca.wikipedia.org/wiki/Santa_Coloma_de_Fitor');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157839,'17209','Santa Maria de Bell-lloc','iglesia','monumentos_osm','Santa Maria de Bell-lloc és una ermita al terme municipal de Palamós (Baix Empordà) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. És una capella d''una nau amb capçalera carrada, coberta amb volta de 4 trams d''arestes.',41.8815132,3.109126,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Bell-lloc_(Palamós)');
