INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157846,'25107','Santa Maria','iglesia','monumentos_osm','Santa Maria de Guàrdia de Tremp fou la primitiva església parroquial de la nova vila de Guàrdia de Tremp (l''actual Guàrdia de Noguera), quan aquesta es traslladà del lloc on era el poble castral inicial, on encara hi ha les ruïnes de l''antiga església parroquial de Sant Feliu de Guàrdia, al lloc actual. Amb el pas…',42.092468,0.8776911,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Guàrdia_de_Tremp');
