INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157851,'25523','Sant Andreu','iglesia','monumentos_osm','Sant Andreu de Biscarri és una església romànica del poble de Biscarri, pertanyent a l''antic municipi de Benavent de la Conca i a l''actual d''Isona i Conca Dellà. És una obra inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.1067345,1.0979788,'https://ca.wikipedia.org/wiki/Sant_Andreu_de_Biscarri');
