INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157869,'15052','Santuario de Nosa Señora da Barca','iglesia','monumentos_osm','O Santuario da Virxe da Barca é un templo católico situado no concello de Muxía. A súa situación na punta da península onde se asenta Muxía, fronte do mar, os ritos relixiosos asociados ao mesmo e a súa arquitectura e imaxinería fan del un dos máis singulares de Galicia.',43.1120047,-9.2196382,'https://gl.wikipedia.org/wiki/Santuario_da_Virxe_da_Barca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157870,'08252','Sagrada Familia','iglesia','monumentos_osm','La parròquia de la Sagrada Família és una parròquia catòlica de Sabadell situada al passeig Dos de Maig nº 35, al barri de les Termes. Es va crear l''any 1967.',41.5313209,2.1203273,'https://ca.wikipedia.org/wiki/Parròquia_de_la_Sagrada_Família_de_Sabadell');
