INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157873,'28160','Iglesia de Nuestra Señora de la Asunción','iglesia','monumentos_osm','La iglesia de Nuestra Señora de la Asunción es una iglesia parroquial católica que se encuentra situada en el municipio madrileño de Valdemorillo. Es el templo principal de la parroquia de Valdemorillo.',40.5022318,-4.0668674,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Valdemorillo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157874,'17213','Santa Susanna de Caulès','iglesia','monumentos_osm','Santa Susanna de Caulès és una ermita preromànica de Caulès (Vidreres, Selva), al massís de Cadiretes, protegida com a bé cultural d''interès local. És molt popular entre els aficionats a la BTT i la bicicleta de muntanya de la zona.',41.7730954,2.8471317,'https://ca.wikipedia.org/wiki/Santa_Susanna_de_Caulès');
