INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157881,'17169','Sant Vicenç de les Roquetes','iglesia','monumentos_osm','Sant Vicenç de les Roquetes és una capella romànica protegida com a bé cultural d''interès local al terme municipal de Sant Julià de Ramis (el Gironès). Establerta com a canònica agustiniana al segle xii passà a ser usada com a masia.',42.0270825,2.8503584,'https://ca.wikipedia.org/wiki/Sant_Vicenç_de_les_Roquetes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157882,'17192','Mare de Déu del Catllar','iglesia','monumentos_osm','L''ermita de Santa Maria del Catllar (o Nostra Senyora del Catllar) és una capella romànica d''una sola nau amb absis i volta de canó situada al municipi de Vilallonga de Ter (Ripollès), en un turó on hi hagué abans el castell del Catllar o «Castellario», del qual no se''n conserven restes, i que donà nom al llinatge…',42.3587276,2.2920144,'https://ca.wikipedia.org/wiki/Ermita_de_Santa_Maria_del_Catllar');
