INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157900,'15037','Igrexa de Santa María das Areas','iglesia','monumentos_osm','A igrexa de Santa María das Areas é o templo parroquial de Santa María de Fisterra. En 1985, xunto co monte e ermida de San Guillerme, foi declarada Conxunto Histórico e Ben de Interese Cultural..',42.9017796,-9.2637122,'https://gl.wikipedia.org/wiki/Igrexa_de_Santa_María_das_Areas_de_Fisterra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157901,'43051','Ermita de Sant Miquel','iglesia','monumentos_osm','Sant Miquel de Segur és una ermita del municipi de Calafell (Baix Penedès). Està situada a l''entrada de la urbanització de Segur de Calafell, a dalt d''un petit turó i a uns 150 metres de la carretera general del Vendrell a Vilanova.',41.1951019,1.60914,'https://ca.wikipedia.org/wiki/Sant_Miquel_de_Segur');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157902,'43051','Església de Sant Cristòfol','iglesia','monumentos_osm','Sant Cristòfol de Cunit és una església del municipi de Cunit (Baix Penedès). De l''edifici romànic només queda la capçalera trevolada i l''espai presbiteral.',41.1976998,1.6342355,'https://ca.wikipedia.org/wiki/Sant_Cristòfol_de_Cunit');
