INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157905,'25042','Sant Marc de Batlliu','iglesia','monumentos_osm','Sant Marc de Batlliu és una església del municipi d''Artesa de Segre (Noguera) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9556471,1.1320984,'https://ca.wikipedia.org/wiki/Sant_Marc_de_Batlliu');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157906,'25042','Sant Silvestre','iglesia','monumentos_osm','Sant Silvestre de Serra d''Alt és una església romànica, del segle xii, que es troba al llogaret de la Serra de Dalt dins del municipi d''Oliola, a la comarca de la Noguera. Sovint apareix citada com a Sant Silvestre de Serralta, però tant als goigs com al Bisbat d''Urgell s''utilitza la forma Serra d''Alt.',41.932618,1.224924,'https://ca.wikipedia.org/wiki/Sant_Silvestre_de_Serra_d''Alt');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157907,'25042','Santa Maria','iglesia','monumentos_osm','Santa Maria de la Serra de Rialb és l''església parroquial del nucli de la Serra de Rialb, al municipi de la Baronia de Rialb (Noguera) que forma part de l''Inventari del Patrimoni Arquitectònic de Catalunya. Es troba a l''entranda del poble, al costat del cementiri.',41.9484016,1.1761805,'https://ca.wikipedia.org/wiki/Santa_Maria_de_la_Serra_de_Rialb');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157908,'25042','Santa Maria de Gualter','iglesia','monumentos_osm','Santa Maria de Gualter és un monestir de l''art medieval català a l''entrada del poble de Gualter, capital del municipi de la Baronia de Rialb (la Noguera). La contrada del Rialb tenia construccions religioses ja de finals del segle ix.',41.9281529,1.1984238,'https://ca.wikipedia.org/wiki/Monestir_de_Santa_Maria_de_Gualter');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157909,'08022','Mare de Déu dels Arcs','iglesia','monumentos_osm','El Mare de Déu dels Arcs o Santa Maria dels Arcs és una església de Santa Pau (Garrotxa) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. El santuari dels Arcs és l''hostatgeria per a pelegrins bastida als segles xvii i XVIII i s''hi accedeix per una escalinata també d''època barroca.',42.1412238,2.58526,'https://ca.wikipedia.org/wiki/Mare_de_Déu_dels_Arcs');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157910,'08022','Sant Abdó i Sant Senén','iglesia','monumentos_osm','Sant Abdó i Sant Senen de Santa Pau és una església de Santa Pau (Garrotxa) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. Entre el coll de Boixedes i el coll de Palomeres, damunt un tossal conegut antigament amb el nom de Puigsacreu, està situada la petita capella d''aquests Sants règuls de Pèrsia.',42.1722816,2.5601607,'https://ca.wikipedia.org/wiki/Sant_Abdó_i_Sant_Senen_de_Santa_Pau');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157911,'08022','Sant Iscle','iglesia','monumentos_osm','Sant Iscle és un edifici religiós que, juntament amb altres cases, conforma un veïnat que havia estat el poble de Sant Iscle de Colltort al municipi de Sant Feliu de Pallerols (Garrotxa). Situat a la capçalera de la riera de Sant Iscle i al peu del castell de Colltort (845 m d''altitud).',42.1193886,2.5286034,'https://ca.wikipedia.org/wiki/Sant_Iscle_de_Colltort');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157912,'08022','Sant Julià de les Medes','iglesia','monumentos_osm','Sant Julià de les Medes és una obra de Sant Aniol de Finestres (Garrotxa) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. La capella de Sant Julià de les Medes està ubicada dalt de la Serra de Finestres i es troba mig amagada per la vegetació.',42.1167149,2.5545253,'https://ca.wikipedia.org/wiki/Sant_Julià_de_les_Medes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157913,'08022','Sant Martí Vell','iglesia','monumentos_osm','Sant Martí Vell de Santa Pau és una església de Santa Pau (Garrotxa) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.1544971,2.578981,'https://ca.wikipedia.org/wiki/Sant_Martí_Vell_de_Santa_Pau');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157914,'17174','Ermita de Sant Quirze i Santa Julita de Merlant','iglesia','monumentos_osm','L''ermita de Sant Quirze i Santa Julita de Merlant és situada a la muntanya de Ginestar que separa la vall del Tort i la de la riera de Garrumbert, al poble de Merlant, municipi de Porqueres.',42.1486455,2.7094551,'https://ca.wikipedia.org/wiki/Sant_Quirze_i_Santa_Julita_de_Merlant');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157915,'17174','Església de Sant Martí de Campmajor','iglesia','monumentos_osm','L''Església de Sant Martí de Campmajor o de Santa Quitèria és una església amb elements barrocs i neoclàssics de Sant Miquel de Campmajor (Pla de l''Estany) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.1316134,2.6888355,'https://ca.wikipedia.org/wiki/Església_de_Sant_Martí_de_Campmajor');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157916,'17174','Església de Santa Maria del Collell','iglesia','monumentos_osm','Santa Maria del Collell és una església i santuari al municipi de Sant Ferriol (la Garrotxa) inclòs en l''Inventari del Patrimoni Arquitectònic de Catalunya. Es troba a 13 quilòmetres de Banyoles, 5 de Mieres i 20 d''Olot.',42.151266,2.6575658,'https://ca.wikipedia.org/wiki/Santa_Maria_del_Collell');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157917,'17174','Sant Andreu del Torn','iglesia','monumentos_osm','Sant Andreu del Torn és una església del municipi de Sant Ferriol (Garrotxa). L''església actual i les restes de l''antiga església romànica formen part de manera singular de l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.1604686,2.645561,'https://ca.wikipedia.org/wiki/Sant_Andreu_del_Torn');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157918,'17177','el Remei de Creixenturri','iglesia','monumentos_osm','El Remei de Creixenturri és l''església parroquial del veïnat de Creixenturri del municipi de Camprodon, a la comarca catalana del Ripollès. Està inscrita en l''Inventari del Patrimoni Arquitectònic de Catalunya amb el codi IPA-3867.',42.2903423,2.3752515,'https://ca.wikipedia.org/wiki/El_Remei_de_Creixenturri');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157919,'08049','Mare de Déu de l''Antiguitat','iglesia','monumentos_osm','Mare de Déu de lʼAntiguitat de Casserres (o Santa Maria de l''Antiguitat) és una església del segle xix, bastida sobre una església més antiga, probablement romànica, del municipi de Casserres (Berguedà), inclosa en l''Inventari del Patrimoni Arquitectònic Català.',42.0155228,1.8441325,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_l''Antiguitat_de_Casserres');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157920,'08049','Sant Marçal','iglesia','monumentos_osm','Sant Marçal de Puig-reig és una església del municipi de Puig-reig (Berguedà) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9943031,1.8595585,'https://ca.wikipedia.org/wiki/Sant_Marçal_de_Puig-reig');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157921,'08049','Sant Miquel de Fonogedell','iglesia','monumentos_osm','Sant Miquel de Fonogedell és una església romànica del municipi de Casserres, al Berguedà, inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9893507,1.8147795,'https://ca.wikipedia.org/wiki/Sant_Miquel_de_Fonogedell');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157922,'08049','Sant Sadurní de Fonollet','iglesia','monumentos_osm','Sant Sadurní de Fonollet és una església del municipi de Puig-reig (Berguedà) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9911759,1.8354088,'https://ca.wikipedia.org/wiki/Sant_Sadurní_de_Fonollet');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157923,'03081','Església Parroquial de Santa Maria','iglesia','monumentos_osm','La iglesia de Santa María es el templo parroquial de Jalón, en la provincia de Alicante, y está situada entre la Plaza Mayor, la calle de su mismo nombre -donde tiene la puerta principal- y la calle Alicante.',38.7407754,-0.0119774,'https://es.wikipedia.org/wiki/Iglesia_de_Santa_María_(Jalón)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157924,'90877','Ermita de Sant Bartomeu de Mont-ras','iglesia','monumentos_osm','Sant Bartomeu de Mont-ras o de les Vespes, és una ermita romànica al terme municipal de Bigues i Riells, al Vallès Oriental. És al racó nord-oriental del terme municipal, en el vessant sud-oest del Puiggraciós.',41.6952708,2.2348817,'https://ca.wikipedia.org/wiki/Sant_Bartomeu_de_Mont-ras');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157925,'90877','Sant Nicolau','iglesia','monumentos_osm','L''ermita de Sant Nicolau de Puig Castellar, popularment coneguda senzillament com a Sant Nicolau, és una capella del terme municipal de l''Ametlla del Vallès, a la comarca del Vallès Oriental. Es troba a dalt d''un turó proper a l''Ametlla, uns 700 metres al nord, amb el campanar de l''església parroquial en primer pla.',41.6776893,2.2604463,'https://ca.wikipedia.org/wiki/Sant_Nicolau_de_Puig_Castellar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157926,'90899','Sant Martí','iglesia','monumentos_osm','Sant Martí de Fornells és una obra del municipi de Toses (Ripollès) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.3237076,2.0462573,'https://ca.wikipedia.org/wiki/Sant_Martí_de_Fornells');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157927,'32075','Igrexa de San Bernabeu da Valenzá','iglesia','monumentos_osm','A igrexa de San Bernabeu da Valenzá é un templo relixioso situado na parroquia da Valenzá (Barbadás). Está dedicada ao apóstolo Bernabeu, e no lintel da porta maior sinálase a data da súa consagración, 1576.',42.3161538,-7.884607,'https://gl.wikipedia.org/wiki/Igrexa_de_San_Bernabeu_da_Valenzá');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157928,'46218','Església Parroquial de Sant Bertomeu','iglesia','monumentos_osm','L''església parroquial de Sant Bartomeu és un temple catòlic del municipi de Ròtova (La Safor), es una obra del segle xviii, encara que la construcció s''inicia l''any 1534. La última rehabilitació es va fer a principis de segle XX. Des d''un punt de vista arquitectònic és d''estil neoclàssic valencià i va ser declarat…',38.9327177,-0.2560087,'https://ca.wikipedia.org/wiki/Església_de_Sant_Bartomeu_de_Ròtova');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157929,'46218','Monasterio de Sant Jeroni de Cotalba','iglesia','monumentos_osm','El Reial monestir de Sant Jeroni de Cotalba és un monestir fundat pel duc reial de Gandia Alfons el Vell en l''any 1388 i va acollir la primera comunitat jerònima de l''antiga corona d''Aragó. Està situat al terme municipal d''Alfauir, al costat de Ròtova, a la comarca de la Safor, País Valencià.',38.9406982,-0.2460768,'https://ca.wikipedia.org/wiki/Sant_Jeroni_de_Cotalba');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157930,'17058','Sant Llorenç','iglesia','monumentos_osm','Sant Llorenç d''Espinavessa és una església del municipi de Cabanelles (Alt Empordà) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.1888689,2.8446761,'https://ca.wikipedia.org/wiki/Sant_Llorenç_d''Espinavessa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157931,'17058','Santa Eulàlia','iglesia','monumentos_osm','L''església parroquial de Santa Eulàlia de Crespià es troba a Crespià (Pla de l''Estany), municipi situat a cada banda de la riera del mateix nom, just al vèrtex nord-oriental de la comarca banyolina, en contacte amb l''Alt Empordà i la Garrotxa. És una obra protegida com a bé cultural d''interès local.',42.1870607,2.7992235,'https://ca.wikipedia.org/wiki/Santa_Eulàlia_de_Crespià');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157932,'17058','Sants Just i Pastor de Pedrinyà','iglesia','monumentos_osm','L''església de Sants Just i Pastor de Pedrinyà es troba al costat de la gran masia de Can Teixidor de Pedrinyà, veïnat de masies disperses a l''extrem nord del municipi de Crespià. És una obra protegida com a bé cultural d''interès local.',42.2028402,2.7792429,'https://ca.wikipedia.org/wiki/Sants_Just_i_Pastor_de_Pedrinyà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157933,'90881','Sant Vicenç de Rus','iglesia','monumentos_osm','Sant Vicenç de Rus és una església al terme de Castellar de n''Hug (Berguedà) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.Sant Vicenç de Rus és una església aïllada situada en una zona muntanyosa de prats i boscos.',42.2739366,1.9925593,'https://ca.wikipedia.org/wiki/Sant_Vicenç_de_Rus');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157934,'36023','Capela de Santa Trega','iglesia','monumentos_osm','A ermida de Santa Trega é un templo medieval do século XII situado no monte de Santa Trega, no concello pontevedrés da Guarda. A ermida atópase dentro dun recinto amurallado, no que tamén se atopan varias vivendas e unha lápida con inscricións de cantaría na honra dos poboadores ou povoeiros de Póvoa de Varzim.',41.8889115,-8.8710153,'https://gl.wikipedia.org/wiki/Ermida_de_Santa_Trega_da_Guarda');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157935,'36023','Convento de San Bieito da Guarda','iglesia','monumentos_osm','O Convento de San Bieito da Guarda é un conxunto significativo, construído entre 1558 e 1561 como Mosteiro da Transfiguración do Señor.',41.8999975,-8.8735315,'https://gl.wikipedia.org/wiki/Convento_de_San_Bieito_da_Guarda');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157936,'17130','Església de Sant Andreu de Pedrinyà','iglesia','monumentos_osm','Sant Andreu és una església romànica dels segles xi i xii, si bé conserva mostres d''estructura posterior, al veïnat de Pedrinyà (la Pera), Baix Empordà.',42.0094924,2.9648214,'https://ca.wikipedia.org/wiki/Sant_Andreu_de_Pedrinyà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157937,'17130','Sant Isidor','iglesia','monumentos_osm','Sant Isidor de la Pera és un edifici religiós del municipi de la Pera inclòs en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.0204006,2.9736255,'https://ca.wikipedia.org/wiki/Sant_Isidor_de_la_Pera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157938,'08083','Mare de Déu de la Damunt','iglesia','monumentos_osm','L''ermita de la Damunt és un edifici de Folgueroles (Osona) inclòs a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9444551,2.3231133,'https://ca.wikipedia.org/wiki/Ermita_de_la_Damunt');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157939,'08083','Sant Jordi de Puigseslloses','iglesia','monumentos_osm','Sant Jordi de Puigseslloses és una ermita del municipi de Folgueroles (Osona) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9478109,2.296492,'https://ca.wikipedia.org/wiki/Sant_Jordi_de_Puigseslloses');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157940,'08083','Santa Maria de Folgueroles','iglesia','monumentos_osm','Santa Maria de Folgueroles és una església de Folgueroles (Osona), catalogada com a bé cultural d''interès local.',41.9389278,2.3194676,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Folgueroles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157941,'40148','Iglesia de San Esteban','iglesia','monumentos_osm','La iglesia de San Esteban es un templo de culto católico ubicado en el municipio de Nieva, en la provincia de Segovia (España). Construida en el siglo XIII, en su fábrica se mezclan los estilos románico y mudéjar, visible principalmente en la galería porticada de la entrada principal, en la que se conjugan arcos y…',41.0801887,-4.4267423,'https://es.wikipedia.org/wiki/Iglesia_de_San_Esteban_(Nieva)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157942,'24114','Ermita Del Buen Suceso','iglesia','monumentos_osm','El santuario o ermita del Buen Suceso es un templo católico del municipio español de Huergas de Gordon, en la provincia de León.',42.8312234,-5.6543778,'https://es.wikipedia.org/wiki/Santuario_del_Buen_Suceso');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157943,'42120','Ermita de la Virgen del Val','iglesia','monumentos_osm','La ermita de la Virgen del Val se encuentra situada a unos 200 metros al noroeste de la localidad de Pedro, a los pies de la sierra de Grado, en el término municipal de Montejo de Tiermes, al sur de la provincia de Soria (España). La ermita consta de una sola nave con ábside rectangular y pórtico al sur, formado…',41.3190789,-3.1943613,'https://es.wikipedia.org/wiki/Ermita_de_la_Virgen_del_Val_(Pedro)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157944,'50009','Iglesia de Elgea','iglesia','monumentos_osm','La iglesia de la Natividad de Nuestra Señora es un edificio situado en el concejo español de Elguea, en la provincia de Álava.',42.935681,-2.512926,'https://es.wikipedia.org/wiki/Iglesia_de_la_Natividad_de_Nuestra_Señora_(Elguea)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157945,'50009','Iglesia de San Cristóbal','iglesia','monumentos_osm','La iglesia de San Cristóbal es un edificio situado en el concejo español de Heredia, en la provincia de Álava.',42.8783096,-2.4439993,'https://es.wikipedia.org/wiki/Iglesia_de_San_Cristóbal_(Heredia)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157946,'50009','Iglesia de San Martín','iglesia','monumentos_osm','La iglesia de San Martín es un edificio situado en el concejo español de Maturana, en la provincia de Álava.',42.8965728,-2.5205495,'https://es.wikipedia.org/wiki/Iglesia_de_San_Martín_(Maturana)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157947,'50009','Iglesia de San Millán','iglesia','monumentos_osm','La iglesia de San Millán es un templo católico situado en el concejo de Larrea, en la provincia de Álava en el País vasco, en España. Conserva casi completa la traza románica del primitivo templo que fue ampliado a su lado derecho, mirando al altar mayor, el conocido como lado de la epístola, por una nueva…',42.9148778,-2.4629368,'https://es.wikipedia.org/wiki/Iglesia_de_San_Millán_(Larrea)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157948,'50009','Iglesia de San Pedro','iglesia','monumentos_osm','La iglesia de San Pedro es un edificio situado en el concejo de Hermua, en el municipio de Barrundia, en la provincia de Álava.',42.9154464,-2.4801801,'https://es.wikipedia.org/wiki/Iglesia_de_San_Pedro_(Hermua)');
