INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157993,'17146','Església','iglesia','monumentos_osm','Santa Maria de l''Esperança és una església a la Batllòria Sant Celoni, Vallès Oriental). Santa Maria de l''Esperança, nasqué a mitjans de segle xv, com a fracció de Montnegre.',41.7180322,2.5476078,'https://ca.wikipedia.org/wiki/Santa_Maria_de_l''Esperança');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157994,'17146','Sant Cebrià de Fuirosos','iglesia','monumentos_osm','Sant Cebrià de Fuirosos és una església al municipi de Sant Celoni (Vallès Oriental) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. Aquest edifici és conegut des del segle xiv, el lloc és esmentat des del 1020.',41.690298,2.5730743,'https://ca.wikipedia.org/wiki/Sant_Cebrià_de_Fuirosos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157995,'90951','Done Martie','iglesia','monumentos_osm','La iglesia de San Martín es un edificio situado en el municipio español de Morga, en la provincia de Vizcaya.',43.3154244,-2.7481987,'https://es.wikipedia.org/wiki/Iglesia_de_San_Martín_(Morga)');
