INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157997,'08082','Sant Cebrià de Fogars','iglesia','monumentos_osm','Sant Cebrià de Fogars és una obra del municipi de Fogars de la Selva (Selva) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. Es tracta de l''església parroquial.',41.7391431,2.6799785,'https://ca.wikipedia.org/wiki/Sant_Cebrià_de_Fogars');
