INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(157999,'17056','Sant Antoni','iglesia','monumentos_osm','L''església de Sant Antoni de Cornellà és situada dins el conjunt urbà de Cornellà del Terri, molt a prop de la plaça, a la banda llevant.',42.0898952,2.8176507,'https://ca.wikipedia.org/wiki/Sant_Antoni_de_Cornellà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158000,'17056','Sant Cugat de Ravós del Terri','iglesia','monumentos_osm','L''església parroquial de Sant Cugat de Ravós del Terri es troba a Ravós del Terri, en un petit turonet al marge dret del riu Terri, inclosa dins el recinte del castell de Ravós.',42.070989,2.8381741,'https://ca.wikipedia.org/wiki/Sant_Cugat_de_Ravós_del_Terri');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158001,'17056','Sant Esteve de Sords','iglesia','monumentos_osm','L''església parroquial de Sant Esteve de Sords és situada al costat esquerre del Terri, formant amb el comunidor, la rectoria i alguna casa més un conjunt esglaonat sobre el riu. La resta de cases del poblet de Sords són masies disseminades.',42.088664,2.8246215,'https://ca.wikipedia.org/wiki/Sant_Esteve_de_Sords');
