INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158021,'34237','Iglesia de San Juan','iglesia','monumentos_osm','La iglesia de San Juan es un templo religioso bajo la advocación de San Juan en la localidad de Villaumbrales, en la provincia de Palencia, comunidad autónoma de Castilla y León, en España. Fue construido en el siglo XIII en piedra y ladrillo.',42.0891726,-4.6128664,'https://es.wikipedia.org/wiki/Iglesia_de_San_Juan_(Villaumbrales)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158022,'08019','Mare de Déu de Montdois','iglesia','monumentos_osm','El santuari de la Mare de Déu de Montdois és una església del terme municipal de Rupit i Pruit catalogada a l''Inventari del Patrimoni Arquitectònic de Catalunya. L''edifici actual data del segle xviii, tot i que ja es menciona una capella de Santa Maria de "Mont Doys" a la parròquia de Fàbregues l''any 1263.',41.9859146,2.481626,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Montdois');
