INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158029,'17163','Església de Sant Pere','iglesia','monumentos_osm','Sant Pere de Montfullà és un monument del municipi de Bescanó (Gironès) inclòs en l''Inventari del Patrimoni Arquitectònic Català. Les primeres notícies referides a la parròquia daten del 882 quan el bisbe Teuter donà diversos delmes d''aquesta església a la Seu de Girona.',41.9683886,2.7595889,'https://ca.wikipedia.org/wiki/Sant_Pere_de_Montfullà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158030,'17163','Sant Bartomeu de Segalars','iglesia','monumentos_osm','Sant Bartomeu de Segalars és una església catalogada com a monument del municipi de Sant Gregori (Gironès) i protegida com a bé cultural d''interès local. En el lloc de Segalars apareix documentat l''any 1901, encara que de la capella no n''hi ha notícies fins a l''any 1401, quan consta que tenia una confraria i un…',41.977932,2.7481091,'https://ca.wikipedia.org/wiki/Sant_Bartomeu_de_Segalars');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158031,'22035','Sant Esteve d''Esplugafreda','iglesia','monumentos_osm','Sant Esteve d''Esplugafreda és l''església parroquial d''origen romànic del poble d''Esplugafreda, de l''antic terme del mateix nom, actualment pertanyent al de Tremp. És un edifici molt transformat al llarg dels segles.',42.2420657,0.7829864,'https://ca.wikipedia.org/wiki/Sant_Esteve_d''Esplugafreda');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158032,'22035','Sant Joan','iglesia','monumentos_osm','Sant Joan Baptista d''Escarlà era l''església romànica del poble d''Escarlà, del terme municipal de Tremp, dins de l''antic terme de Sapeira. L''església, com tot el poble d''Escarlà, estava unida a la parròquia de Sant Pere d''Espills, i, amb ella, estigué vinculada al monestir de Lavaix.',42.2195532,0.726736,'https://ca.wikipedia.org/wiki/Sant_Joan_d''Escarlà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158033,'22035','Sant Pere','iglesia','monumentos_osm','Sant Pere d''Orrit és l''església parroquial romànica del poble d''Orrit, pertanyent al terme municipal de Tremp, dins de l''antic terme de Sapeira. És un monument protegit com a bé cultural d''interès local.',42.2565889,0.7403494,'https://ca.wikipedia.org/wiki/Sant_Pere_d''Orrit');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158034,'22035','Santa Maria','iglesia','monumentos_osm','Santa Maria de Sapeira és l''església parroquial romànica del poble de Sapeira, de l''antic terme del mateix nom, actualment pertanyent al de Tremp. És un edifici molt transformat al llarg dels segles.',42.2539757,0.7898014,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Sapeira');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158035,'45113','Iglesia parroquial de San Sebastián','iglesia','monumentos_osm','La iglesia parroquial de San Sebastián es un templo católico de la localidad española de Los Navalucillos, en la provincia de Toledo. Es de estilo mudéjar sencillo.',39.6664553,-4.6415951,'https://es.wikipedia.org/wiki/Iglesia_de_San_Sebastián_(Los_Navalucillos)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158036,'17191','Església de Sant Iscle d''Empordà','iglesia','monumentos_osm','L''església de Sant Iscle d''Empordà, també coneguda com de Sant Iscle i Santa Victòria o Sant Iscle i Santa Julita, es troba al lloc més elevat de Serra de Daró, a l''extrem oposat de la torre medieval que també es conserva.',42.0322757,3.0569636,'https://ca.wikipedia.org/wiki/Sant_Iscle_i_Santa_Victòria_(Serra_de_Daró)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158037,'17191','Església de Sant Romà','iglesia','monumentos_osm','Sant Romà és una església a Llabià (Baix Empordà) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.0182638,3.0882448,'https://ca.wikipedia.org/wiki/Sant_Romà_de_Llabià');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158038,'17191','Església de Santa Maria','iglesia','monumentos_osm','Santa Maria és una església a la plaça de l''església de la Serra de Daró. Serra de Daró (Baix Empordà) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.0285842,3.0723108,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Serra_de_Daró');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158039,'04051','Convento de los Agustinos','iglesia','monumentos_osm','El convento de los Agustinos es el monumento más importante del municipio de Huécija situado en la provincia de Almería (Andalucía, España) y uno de los mejores ejemplos de arquitectura barroca de la provincia de Almería.',36.96794,-2.60848,'https://es.wikipedia.org/wiki/Convento_de_los_Agustinos_(Huécija)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158040,'04051','Iglesia de Nuestra Señora de la Anunciación','iglesia','monumentos_osm','La Iglesia de Nuestra Señora de la Anunciación es la iglesia parroquial de la localidad de Huécija (Almería-España).',36.9683397,-2.6102673,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Anunciación_(Huécija)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158041,'43114','Església de Sant Joan Evangelista','iglesia','monumentos_osm','Sant Joan Evangelista de Porrera és una església del municipi de Porrera (Priorat) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.1891604,0.8558562,'https://ca.wikipedia.org/wiki/Sant_Joan_Evangelista_de_Porrera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158042,'43114','ermita de Sant Antoni','iglesia','monumentos_osm','Sant Antoni és una ermita al municipi de Porrera (el Priorat) catalogada a l''Inventari del Patrimoni Arquitectònic de Catalunya. L''ermita fou bastida cap al 1610 i refeta el 1773.',41.1872195,0.8593793,'https://ca.wikipedia.org/wiki/Ermita_de_Sant_Antoni_(Porrera)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158043,'17126','Església de Sant Feliu','iglesia','monumentos_osm','L''església parroquial de Sant Feliu de Parlavà està situada al centre del municipi de Parlavà (Baix Empordà). És un monument declarat bé cultural d''interès nacional.',42.0222224,3.0300428,'https://ca.wikipedia.org/wiki/Sant_Feliu_de_Parlavà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158044,'50081','Iglesia de San Juan Bautista','iglesia','monumentos_osm','La iglesia de San Juan Bautista​ es templo parroquial católico de la villa y municipio aragónes de Cetina, en la Comunidad de Calatayud.',41.2932859,-1.964026,'https://es.wikipedia.org/wiki/Iglesia_de_San_Juan_Bautista_(Cetina)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158045,'17218','Ermita de Sant Baldiri','iglesia','monumentos_osm','Sant Baldiri de Galliners és una església gòtica de Vilademuls (Pla de l''Estany) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.151323,2.886316,'https://ca.wikipedia.org/wiki/Sant_Baldiri_de_Galliners');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158046,'17218','Ermita de Sant Pere de Juïgues','iglesia','monumentos_osm','L''església de Sant Pere de Juïgues, de l''antic lloc de Juïgues, únic topònim alt-medieval d''aquestes comarques que indica un establiment de població jueva, es troba a l''entitat de població de Vilamarí, del municipi de Vilademuls, al costat del mas Sobirà, avui conegut per Can Güell, en una petita vall regada pel…',42.1288527,2.8496602,'https://ca.wikipedia.org/wiki/Sant_Pere_de_Juïgues');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158047,'17218','Església de Sant Esteve de Guialbes','iglesia','monumentos_osm','L''església parroquial de Sant Esteve de Guialbes està situat al poble del mateix nom (Sant Esteve de Guialbes) del municipi de Vilademuls, damunt d''un petit pujol anomenat antigament Puig Blanquer.',42.1154817,2.8781887,'https://ca.wikipedia.org/wiki/Església_de_Sant_Esteve_de_Guialbes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158048,'17218','Església de Sant Joan Baptista de Vilademuls','iglesia','monumentos_osm','Sant Joan Baptista de Vilademuls és una l''església parroquial de Vilademuls (Pla de l''Estany) protegida com a Bé Cultural d''Interès Local. S''hi venera sant Joan Baptista, però no en la festivitat del seu naixement (24 de juny) sinó en la del seu martiri o degollació (29 d''agost).',42.1383033,2.8876038,'https://ca.wikipedia.org/wiki/Sant_Joan_Baptista_de_Vilademuls');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158049,'17218','Església de Sant Marçal de Quarantella','iglesia','monumentos_osm','L''església de Sant Marçal de la Quarantella, edificada al cim d''un serrat, es troba al llogarret del mateix nom, un conjunt de masies escampades en un territori de turons baixos, valls petites i fondalades, a la capçalera del riu Siriana.',42.125463,2.8681189,'https://ca.wikipedia.org/wiki/Església_de_Sant_Marçal_de_la_Quarantella');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158050,'42008','Església Nova de Sant Miquel','iglesia','monumentos_osm','Església Nova de Sant Miquel és una obra de l''Espluga de Francolí (Conca de Barberà) protegida com a Bé Cultural d''Interès Local.',41.3963593,1.102606,'https://ca.wikipedia.org/wiki/Església_Nova_de_Sant_Miquel_(l''Espluga_de_Francolí)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158051,'42008','Església Vella de Sant Miquel','iglesia','monumentos_osm','Sant Miquel de l''Espluga és una església de l''Espluga de Francolí (Conca de Barberà) declarada bé cultural d''interès nacional.',41.396717,1.1033498,'https://ca.wikipedia.org/wiki/Sant_Miquel_de_l''Espluga');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158052,'17054','Església de Sant Miquel','iglesia','monumentos_osm','Sant Miquel de Colera és una església parroquial del municipi de Colera (Alt Empordà) protegida com a Bé Cultural d''Interès Local.',42.4043959,3.1513631,'https://ca.wikipedia.org/wiki/Església_parroquial_de_Sant_Miquel_de_Colera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158053,'44108','Iglesia Parroquial de Santa María la Mayor','iglesia','monumentos_osm','La iglesia parroquial de Santa María la Mayor de La Fresneda (Teruel) está dedicada a Santa María la Mayor o Nuestra Señora de la Nieves. Su origen es del siglo XVII y propia del estilo barroco.',40.9295907,0.0739286,'https://es.wikipedia.org/wiki/Iglesia_de_Santa_María_la_Mayor_(La_Fresneda)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158054,'17069','Sant Cosme i Sant Damià de Queixans','iglesia','monumentos_osm','Sant Cosme i Sant Damià de Queixans és una església protegida com a bé cultural d''interès local del municipi de Fontanals de Cerdanya (Cerdanya).Rodejada del cementiri excepte la façana principal que forma un frontispici, encimat pel campanar quadrat piramidal. La portalada és de mig punt i s''hi pot llegir l''any 1775.',42.398537,1.9217445,'https://ca.wikipedia.org/wiki/Sant_Cosme_i_Sant_Damià_de_Queixans');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158055,'17069','Sant Martí','iglesia','monumentos_osm','Sant Martí d''Urtx és una església d''origen romànic al poble d''Urtx pertanyent al municipi de Fontanals de Cerdanya (Baixa Cerdanya).',42.3867578,1.9102234,'https://ca.wikipedia.org/wiki/Sant_Martí_d''Urtx');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158056,'17069','Sant Miquel de Soriguerola','iglesia','monumentos_osm','Sant Miquel de Soriguerola és una església romànica situada a l''entitat de població de Soriguerola pertanyent al municipi de Fontanals de Cerdanya a la comarca de la Baixa Cerdanya. És una obra protegida com a bé cultural d''interès local.',42.3972395,1.881395,'https://ca.wikipedia.org/wiki/Sant_Miquel_de_Soriguerola');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158057,'17206','Sant Climent','iglesia','monumentos_osm','Sant Climent d''Urús és una església protegida com a bé cultural d''interès local del municipi d''Urús (Cerdanya).',42.3499166,1.8542879,'https://ca.wikipedia.org/wiki/Sant_Climent_d''Urús');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158058,'17206','Sant Julià de Tartera','iglesia','monumentos_osm','Sant Julià de Tartera és una església del municipi de Das (Cerdanya) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.358643,1.8529596,'https://ca.wikipedia.org/wiki/Sant_Julià_de_Tartera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158059,'17082','Sant Esteve','iglesia','monumentos_osm','Sant Esteve de Guils, és l''església parroquial del poble i municipi de Guils de Cerdanya, a la comarca catalana de la Baixa Cerdanya, inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. L''any 2020 va ser declarada Bé Cultural d''Interès Nacional, en la categoria de Monument Històric.',42.447999,1.8780437,'https://ca.wikipedia.org/wiki/Sant_Esteve_de_Guils');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158060,'17082','Sant Vicenç','iglesia','monumentos_osm','Sant Vicenç de Saneja és una església romànica del nucli de població de Saneja a Guils de Cerdanya (Cerdanya), protegida com a bé cultural d''interès local.',42.4448776,1.9031758,'https://ca.wikipedia.org/wiki/Sant_Vicenç_de_Saneja');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158061,'25175','Sant Serni','iglesia','monumentos_osm','Sant Serni de Prats és un monument del municipi de Prats i Sansor (Cerdanya) protegit com a bé cultural d''interès local. Edifici d''una sola nau amb volta de canó bastant llarga i molt alta.',42.365837,1.8397404,'https://ca.wikipedia.org/wiki/Sant_Serni_de_Prats');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158062,'17153','Sant Martí','iglesia','monumentos_osm','Sant Martí és un edifici religiós al nucli de Caçà de Pelràs (Baix Empordà) catalogat a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.0079442,2.9946775,'https://ca.wikipedia.org/wiki/Sant_Martí_(Cassà_de_Pelràs)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158063,'17153','Sant Vicenç','iglesia','monumentos_osm','Sant Vicenç és una església parroquial al nucli de Rupià (Baix Empordà) protegida com a bé cultural d''interès local. La primera referència documental sobre l''església de sant Vicenç de Rupià data del 1139, com a part d''un conveni de vassallatge entre el bisbe de Girona i Arnau Gausfred.',42.0208327,3.0104869,'https://ca.wikipedia.org/wiki/Sant_Vicenç_de_Rupià');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158064,'17153','Santa Maria de La Sala','iglesia','monumentos_osm','Santa Maria és una església parroquial al veïnat de la Sala al terme de Foixà (el Baix Empordà). Forma part de l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.0329931,3.0167894,'https://ca.wikipedia.org/wiki/Santa_Maria_de_la_Sala_(Foixà)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158065,'25243','Glèsia de Sant Estèue','iglesia','monumentos_osm','Sant Esteve de Montcorbau és una església del poble de Montcorbau al municipi de Vielha e Mijaran (Vall d''Aran) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.7312411,0.7896627,'https://ca.wikipedia.org/wiki/Sant_Esteve_de_Montcorbau');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158066,'25243','Glèsia de Sant Pèir','iglesia','monumentos_osm','Sant Pere de Vila és una església de Vila al municipi de Vielha e Mijaran (Vall d''Aran) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. Aquesta església havia estat un fortí militar durant la guerra civil.',42.7365913,0.7764941,'https://ca.wikipedia.org/wiki/Sant_Pere_de_Vila');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158067,'25243','Mair de Diu de Montcorbau','iglesia','monumentos_osm','Mare de Déu dels Desamparats de Montcorbau és una capella de Montcorbau, al municipi de Vielha e Mijaran (Vall d''Aran), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.7332061,0.7897972,'https://ca.wikipedia.org/wiki/Mare_de_Déu_dels_Desamparats_de_Montcorbau');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158068,'25243','Mare de Déu del Roser d''Aubèrt','iglesia','monumentos_osm','Mare de Déu del Roser d''Aubèrt és una església amb elements romànics i renaixentistes del poble d''Aubèrt al municipi de Vielha e Mijaran (Vall d''Aran) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.7308433,0.7777216,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Roser_d''Aubèrt');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158069,'25243','Sant Feliu','iglesia','monumentos_osm','Sant Feliu de Vilac és una església romànica del poble de Vilac al municipi de Vielha e Mijaran a la Vall d''Aran protegida com a bé cultural d''interès local. És als afores del nucli, al lloc de l''antic castell, del qual el campanar era una torre de defensa.',42.7218965,0.7978671,'https://ca.wikipedia.org/wiki/Sant_Feliu_de_Vilac');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158070,'25048','Sant Miquel','iglesia','monumentos_osm','Sant Miquel de Bell-lloc d''Urgell és l''església parroquial de Bell-lloc d''Urgell a la comarca del Pla d''Urgell. És un monument protegit com a bé cultural d''interès local.',41.6295115,0.7811118,'https://ca.wikipedia.org/wiki/Sant_Miquel_de_Bell-lloc_d''Urgell');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158071,'25205','Sant Bartomeu','iglesia','monumentos_osm','Sant Bartomeu de Sidamon és un monument del municipi de Sidamon (Pla d''Urgell) inclòs en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.6295208,0.8317458,'https://ca.wikipedia.org/wiki/Sant_Bartomeu_de_Sidamon');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158072,'25158','Sant Joan Baptista','iglesia','monumentos_osm','L''Església parroquial de Sant Joan Baptista és una església que està situada al poble del Palau d''Anglesola a la comarca del Pla d''Urgell. D''estil neoclàssica i dedicada a Sant Joan Baptista l''església data de 1802.',41.6517444,0.8805236,'https://ca.wikipedia.org/wiki/Església_de_Sant_Joan_Baptista_del_Palau_d''Anglesola');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158073,'90897','Capella de Sant Medir','iglesia','monumentos_osm','Sant Medir del Pla és una església de Sant Martí de Llémena (Gironès) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.0198826,2.6908836,'https://ca.wikipedia.org/wiki/Sant_Medir_del_Pla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158074,'90897','Ermita de Sant Joan','iglesia','monumentos_osm','es mentida de vritat esdiu pla de sant joan Sant Joan del Pla és una obra de Sant Martí de Llémena (Gironès) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.0236454,2.6789746,'https://ca.wikipedia.org/wiki/Sant_Joan_del_Pla_(Sant_Martí_de_Llémena)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158075,'46020','Ermita del Crist del Calvari','iglesia','monumentos_osm','La Ermita del Cristo del Calvario es un templo situado en el municipio valenciano de Alcudia de Crespins (España) Es Bien de Relevancia Local con identificador número 46.23.020-001.​​',38.9742007,-0.5941921,'https://es.wikipedia.org/wiki/Ermita_del_Cristo_del_Calvario_(Alcudia_de_Crespins)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158076,'21054','Capilla de la Santa Cruz','iglesia','monumentos_osm','La Santa Cruz de la Calle Sevilla es una hermandad religiosa de la localidad de La Palma del Condado (Huelva) España. La imagen de la Cruz es una apreciada obra de orfebrería confeccionada en Alpaca y Bronce de ley en los talleres sevillanos de D. Manuel Seco Velasco.',37.3883129,-6.5492121,'https://es.wikipedia.org/wiki/Santa_Cruz_de_la_Calle_Sevilla_(La_Palma_del_Condado)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158077,'21054','Iglesia de Nuestra Señora del Valle','iglesia','monumentos_osm','La ermita de Nuestra Señora del Valle es un templo católico situado en la localidad de La Palma del Condado.',37.3881432,-6.5537241,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_del_Valle_(La_Palma_del_Condado)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158078,'21054','Iglesia de San Juan Baustista','iglesia','monumentos_osm','La iglesia de San Juan Bautista de La Palma del Condado (provincia de Huelva, España) se construye a consecuencia de la ruina producida en la primitiva iglesia como consecuencia del terremoto de Lisboa de 1755, que afectó especialmente al área onubense, donde la mayoría de las iglesias parroquiales quedaron…',37.3875794,-6.5527983,'https://es.wikipedia.org/wiki/Iglesia_de_San_Juan_Bautista_(La_Palma_del_Condado)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158079,'43041','Sant Joan d''Algars','iglesia','monumentos_osm','Sant Joan d''Algars és una església (avui ermita) del municipi de Batea (Terra Alta). Està situada a uns 7 km a l''oest del cap del municipi, i a tocar del riu d''Algars.',41.0928832,0.2275361,'https://ca.wikipedia.org/wiki/Sant_Joan_d''Algars');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158080,'43041','Santa Anna','iglesia','monumentos_osm','Santa Anna d''Almudèfer és un edifici de l''antic terme d''Almudèfer, al municipi de Caseres (Terra Alta) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.0260916,0.2752064,'https://ca.wikipedia.org/wiki/Santa_Anna_d''Almudèfer');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158081,'43032','Sant Josep','iglesia','monumentos_osm','L''Ermita de Sant Josep és una església del municipi de Bot (Terra Alta) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. És al sud-est del poble, dalt d''un turó al peu del riu Canaletes, envoltada per les muntanyes de la Plana, l''Agulla i la Migdia.',41.004242,0.3932297,'https://ca.wikipedia.org/wiki/Ermita_de_Sant_Josep_(Bot)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158082,'17143','Sant Julià de Rabós','iglesia','monumentos_osm','Sant Julià de Rabós és una església romànica al nucli urbà de Rabós (Alt Empordà). L''església és un edifici romànic d''una sola nau acabada a l''est per un absis semicircular.',42.378986,3.0287178,'https://ca.wikipedia.org/wiki/Sant_Julià_de_Rabós');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158083,'17143','Sant Quirc i Santa Julita','iglesia','monumentos_osm','Sant Quirc i Santa Julita és una església situada al nord del poble de Rabós (Alt Empordà), dins del veïnat de Sant Quirc de Colera, i a uns 3 km al sud-oest del monestir de Sant Quirze de Colera. Es tracta d''una nau amb absis semicircular i posseeix dues capelles laterals, de reduïdes dimensions, també semicirculars.',42.392764,3.0441002,'https://ca.wikipedia.org/wiki/Sant_Quirc_i_Santa_Julita_(Rabós)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158084,'17100','Església de Sant Pere','iglesia','monumentos_osm','Sant Pere de Vilarnadal és una església del municipi de Masarac i Vilarnadal (Alt Empordà) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.3412502,2.9530553,'https://ca.wikipedia.org/wiki/Sant_Pere_de_Vilarnadal');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158085,'17100','Santa Maria de l''Om','iglesia','monumentos_osm','Santa Maria de l''Om és una església i antic priorat del nucli del Priorat pertanyent al municipi de Masarac (Alt Empordà). Està inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.3516907,2.9807587,'https://ca.wikipedia.org/wiki/Santa_Maria_de_l''Om');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158086,'17106','Sant Cebrià de Mollet','iglesia','monumentos_osm','Sant Cebrià de Mollet és una església del municipi de Mollet de Peralada (Alt Empordà) protegida com a Bé Cultural d''Interès Local.',42.3606311,2.999792,'https://ca.wikipedia.org/wiki/Sant_Cebrià_de_Mollet');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158087,'46139','Iglesia de San Vicente Mártir','iglesia','monumentos_osm','La iglesia parroquial de San Vicente Mártir de Guadassuar, en la comarca de la Ribera Alta de la provincia de Valencia, está catalogada como Bien de interés cultural como queda constancia en la Dirección General de Patrimonio Cultural de la Consejería de Turismo, Cultura y Deportes de la Generalidad Valenciana, con…',39.1855483,-0.478214,'https://es.wikipedia.org/wiki/Iglesia_de_San_Vicente_Mártir_(Guadasuar)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158088,'17132','Església de Sant Martí de Peralada','iglesia','monumentos_osm','Sant Martí és una església al nucli de Peralada (Alt Empordà), inclòs en l''Inventari del Patrimoni Arquitectònic de Catalunya. l''església de Sant Martí és un edifici de grans dimensions, d''una nau amb capelles laterals, creuer amb cúpula i absis poligonal.',42.3083364,3.0084571,'https://ca.wikipedia.org/wiki/Sant_Martí_de_Peralada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158089,'17132','Sant Nazari de les Olives','iglesia','monumentos_osm','Sant Nazari de les Olives és una església del municipi de Peralada (Alt Empordà), inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.3221753,2.9953714,'https://ca.wikipedia.org/wiki/Sant_Nazari_de_les_Olives');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158090,'43105','Sant Joan','iglesia','monumentos_osm','L''església parroquial de Sant Joan de Biure, al terme de les Piles, és un edifici d''estil barroc construït al segle xviii. Forma part de l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.4901305,1.3506413,'https://ca.wikipedia.org/wiki/Sant_Joan_de_Biure');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158091,'43105','Sant Martí','iglesia','monumentos_osm','Sant Martí de les Piles és una església del municipi de les Piles. És una església construïda en el segle xviii sobre l''antiga església romànica del segle xii, dedicada a Sant Martí.',41.5036681,1.3422693,'https://ca.wikipedia.org/wiki/Sant_Martí_de_les_Piles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158092,'43105','Santa Eugènia','iglesia','monumentos_osm','Ermita de Santa Eugènia de les Piles és un edifici religiós del segle xix situat al municipi de les Piles que forma part de l''Inventari del Patrimoni Arquitectònic de Catalunya. Està compost d''una sola nau de planta rectangular i amb una coberta de doble vessant.',41.5019364,1.3430186,'https://ca.wikipedia.org/wiki/Ermita_de_Santa_Eugènia_de_les_Piles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158093,'43105','Santa Maria de Guialmons','iglesia','monumentos_osm','Santa Maria de Guialmons és l''església del nucli de Guialmons en el municipi de les Piles (Conca de Barberà). És una església romànica inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.5123427,1.3655914,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Guialmons');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158094,'43130','Sant Salvador','iglesia','monumentos_osm','Sant Salvador de Rocafort és un monument del municipi de Rocafort de Queralt (Conca de Barberà) protegit com a bé cultural d''interès local.',41.4776626,1.2814949,'https://ca.wikipedia.org/wiki/Sant_Salvador_de_Rocafort');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158095,'17074','Església de Sant Julià i Santa Basilissa','iglesia','monumentos_osm','Sant Julià i Santa Basilissa de Fortià és una església del municipi de Fortià (Alt Empordà) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.2420021,3.0410096,'https://ca.wikipedia.org/wiki/Sant_Julià_i_Santa_Basilissa_de_Fortià');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158096,'17151','Església de Sant Mamet','iglesia','monumentos_osm','Sant Mamet de Riumors és una església del municipi de Riumors (Alt Empordà) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.2274667,3.042272,'https://ca.wikipedia.org/wiki/Sant_Mamet_de_Riumors');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158097,'17128','Església de Sant Martí','iglesia','monumentos_osm','Sant Martí de Pau és una església del municipi de Pau (Alt Empordà) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.3158701,3.1166167,'https://ca.wikipedia.org/wiki/Sant_Martí_de_Pau');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158098,'08010','Mare de Déu de Mont-ros','iglesia','monumentos_osm','Les ruïnes de la capella de la Mare de Déu de Mont-ros es troben al cim del Mont-ros, al contrafort nord-occidental de la serra de Sant Julià del Mont, a l''extrem oriental del terme, dintre de la parròquia de Begudà. El 2012, l''Ajuntament de Sant Joan les Fonts va comprar el terreny on hi ha les restes del castell…',42.2067454,2.5503805,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Mont-ros');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158099,'08010','Santa Eulàlia de Begudà','iglesia','monumentos_osm','L''església de Santa Eulàlia de Begudà centra el poble de Begudà, entitat de població del municipi de Sant Joan les Fonts. Situat a la dreta de la riera del Turonell i format per unes quantes cases que envolten el temple i diverses masies disseminades pel terme.',42.1958061,2.5460535,'https://ca.wikipedia.org/wiki/Santa_Eulàlia_de_Begudà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158100,'25589','Sant Andreu','iglesia','monumentos_osm','Sant Andreu de València d''Àneu és l''església parroquial romànica del poble de València d''Àneu, al terme municipal d''Alt Àneu, a la comarca del Pallars Sobirà. Pertanyia a l''antic terme del mateix nom del poble.',42.6344,1.1107181,'https://ca.wikipedia.org/wiki/Sant_Andreu_de_València_d''Àneu');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158101,'17190','Sant Andreu','iglesia','monumentos_osm','Sant Andreu de Serinyà és una església romànica del municipi de Serinyà, a la comarca del Pla de l''Estany. És l''església parroquial i es troba al mig del nucli de Serinyà, al mig d''una àmplia plaça.',42.1689275,2.74468,'https://ca.wikipedia.org/wiki/Sant_Andreu_de_Serinyà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158102,'17190','Sant Cristòfol d''Usall','iglesia','monumentos_osm','Sant Cristòfol d''Usall és una església romànica de Porqueres a la comarca del Pla de l''Estany, inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.1487211,2.7571245,'https://ca.wikipedia.org/wiki/Sant_Cristòfol_d''Usall');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158103,'17190','Sant Martí de Dosquers','iglesia','monumentos_osm','Sant Martí de Dosquers és l''església parroquial del poble de Dosquers, dedicada a Sant Martí, al municipi de Maià de Montcal (Garrotxa) protegit com a bé cultural d''interès local.',42.1951811,2.7534819,'https://ca.wikipedia.org/wiki/Sant_Martí_de_Dosquers');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158104,'17190','Sant Miquel Sesvinyes','iglesia','monumentos_osm','L''església de Sant Miquel Sesvinyes és emplaçada en plena serra de la Boscarra al veïnat de Casals, a la part central del terme de Serinyà, a poc més d''un km. al sud-oest del nucli de Serinyà, sobre un petit turó i presidint el veïnat que és de cases disperses.',42.1603031,2.733029,'https://ca.wikipedia.org/wiki/Sant_Miquel_Sesvinyes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158105,'17190','Santa Maria de Fares','iglesia','monumentos_osm','Santa Maria de Fares és una església del municipi de Sant Ferriol (Garrotxa) inclòs en l''Inventari del Patrimoni Arquitectònic de Catalunya. Esglesiola dedicada a Santa Maria, havia estat l''església parroquial del poble de Fares fins que aquest fou agregat a la parròquia de Sant Vicenç de Besalú.',42.1865535,2.7356213,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Fares');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158106,'08228','Mare de Déu del Roser','iglesia','monumentos_osm','La Capella del Roser de Sant Martí Sesgueioles és una obra de Sant Martí Sesgueioles (Anoia) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7029051,1.4893105,'https://ca.wikipedia.org/wiki/Capella_del_Roser_de_Sant_Martí_Sesgueioles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158107,'08228','Sant Jaume','iglesia','monumentos_osm','Sant Jaume de la Guàrdia Pilosa és una església de Pujalt (Anoia) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7066157,1.470868,'https://ca.wikipedia.org/wiki/Sant_Jaume_de_la_Guàrdia_Pilosa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158108,'08228','Sant Martí','iglesia','monumentos_osm','Sant Martí és una església al nucli de Sant Martí Sesgueioles (Anoia) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. L''edifici fou començat pel rector Antoni Maimir l''any 1779 i fou fet a joves (és a dir, hi participa tot el poble, sense cobrar jornals).',41.7018693,1.4884314,'https://ca.wikipedia.org/wiki/Sant_Martí_(Sant_Martí_Sesgueioles)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158109,'17051','Església de Santa Maria de Cistella','iglesia','monumentos_osm','Santa Maria de Cistella és l''església parroquial de la vila de Cistella (Alt Empordà) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.2686234,2.8483437,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Cistella');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158110,'17051','Mare de Déu de Vida','iglesia','monumentos_osm','El Santuari de Nostra Senyora de Vida o Ermita de la Mare de Déu de Vida és un edifici religiós reconstruït el segle xvii i situat al municipi de Cistella (Alt Empordà). És una ermita situada dalt d''un turó situat a uns dos quilòmetres al nord-est del nucli de Cistella, al cim d''un turó cobert d''olivars, des d''on…',42.2665392,2.838476,'https://ca.wikipedia.org/wiki/Santuari_de_Nostra_Senyora_de_Vida');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158111,'17051','Sant Martí de Vilarig','iglesia','monumentos_osm','Sant Martí de Vilarig és una església del municipi de Cistella (Alt Empordà) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.2863717,2.833661,'https://ca.wikipedia.org/wiki/Sant_Martí_de_Vilarig');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158112,'17051','Sant Salvador de Coquells','iglesia','monumentos_osm','Sant Salvador de Coquells és una església romànica del segle xi al nord-oest del municipi de Vilanant (Alt Empordà), inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. És a uns 3 km de la població, en un bosc de pins i alzines.',42.2744014,2.8673608,'https://ca.wikipedia.org/wiki/Sant_Salvador_de_Coquells');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158113,'25565','Sant Antoni Abat de Mentui','iglesia','monumentos_osm','Sant Antoni Abat de Mentui és l''església parroquial del poble de Mentui, de l''antic terme municipal de Montcortès de Pallars, i de l''actual de Baix Pallars, a la comarca del Pallars Sobirà. Està situada en el mateix poble de Mentui, en el centre d''aquesta petita població.',42.3305146,0.9755729,'https://ca.wikipedia.org/wiki/Sant_Antoni_Abat_de_Mentui');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158114,'25565','Sant Esteve','iglesia','monumentos_osm','Sant Esteve d''Antist és l''antiga església parroquial del poble d''Antist, del terme municipal de la Torre de Cabdella a la comarca del Pallars Jussà. Fins al 1970 pertanyia a l''antic terme de la Pobleta de Bellveí.',42.3707352,0.9481603,'https://ca.wikipedia.org/wiki/Sant_Esteve_d''Antist');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158115,'25565','Sant Feliu','iglesia','monumentos_osm','L''església de Sant Feliu de la Pobleta de Bellveí és la parroquial de la vila de la Pobleta de Bellveí, de l''antic terme del mateix nom, actualment del terme municipal de la Torre de Cabdella, del Pallars Jussà. Està situada a l''angle nord-est del clos de la vila, que és alhora el punt més elevat de la plana on es…',42.3445409,0.9606664,'https://ca.wikipedia.org/wiki/Sant_Feliu_de_la_Pobleta_de_Bellveí');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158116,'25565','Sant Joan Evangelista de Beranui','iglesia','monumentos_osm','L''església de sant Joan Evangelista és un temple catòlic situat a la part alta del poble de Beranui, integrat des del 1970 al terme municipal de la Torre de Cabdella, i anteriorment, des del 1847, al de Mont-ros, a la vall Fosca, comarca del Pallars Jussà. La primera documentació d''aquesta església no arriba fins a…',42.374437,0.967521,'https://ca.wikipedia.org/wiki/Sant_Joan_Evangelista_de_Beranui');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158117,'25565','Sant Martí','iglesia','monumentos_osm','Sant Martí de Montcortès és l''església parroquial del poble de Montcortès, de l''antic terme municipal de Montcortès de Pallars, i de l''actual de Baix Pallars, a la comarca del Pallars Sobirà. Està situada en el mateix poble de Montcortès, a la part central d''aquesta població.',42.3289943,1.0046864,'https://ca.wikipedia.org/wiki/Sant_Martí_de_Montcortès');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158118,'34100','Iglesia de San Andrés','iglesia','monumentos_osm','La iglesia de San Andrés se encuentra en el municipio de Mantinos, en la provincia de Palencia, Castilla y León.',42.7512604,-4.8418004,'https://es.wikipedia.org/wiki/Iglesia_de_San_Andrés_(Mantinos)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158119,'43088','Sant Pere','iglesia','monumentos_osm','Sant Pere de Montbrió del Camp és l''església parroquial d''estil barroc de Montbrió del Camp (Baix Camp). Està protegida com a bé cultural d''interès local.',41.1200665,1.0035088,'https://ca.wikipedia.org/wiki/Sant_Pere_de_Montbrió_del_Camp');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158120,'43150','Església de Sant Jaume','iglesia','monumentos_osm','Sant Jaume és una església parroquial declarada bé cultural d''interès nacional davant la plaça Baranova, a l''extrem oest de l''antiga vila emmurallada de Tivissa (Ribera d''Ebre), que es formà sobre una petita elevació del terreny.',41.0435509,0.7321473,'https://ca.wikipedia.org/wiki/Església_de_Sant_Jaume_(Tivissa)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158121,'43150','Sant Blai','iglesia','monumentos_osm','Sant Blai és una ermita a 2,5 km a migdia de la vila de Tivissa, en un vessant del Coll del Ventall, que està coronat per les restes del castell de Sant Blai. Antigament, al lloc hi havia existit una capella, suposadament relacionada amb el castell al cim del turó, que rep el mateix nom.',41.0331131,0.7221115,'https://ca.wikipedia.org/wiki/Ermita_de_Sant_Blai_(Tivissa)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158122,'47074','Iglesia de San Miguel Arcángel','iglesia','monumentos_osm','La iglesia de San Miguel Arcángel es una iglesia de España localizada en el municipio de Hornillos de Eresma, en la provincia de Valladolid, comunidad autónoma de Castilla y León. Fue declarada bien de interés cultural con la categoría de monumento el 17 de octubre de 2013.​ Se trata de una singular construcción de…',41.3660996,-4.7200062,'https://es.wikipedia.org/wiki/Iglesia_de_San_Miguel_Arcángel_(Hornillos_de_Eresma)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158123,'04030','Iglesia Fortaleza de San Benito','iglesia','monumentos_osm','La iglesia de San Benito​ o iglesia-fortaleza, situada en el municipio de Vícar (Almería, España), es un edificio religioso con elementos defensivos, de arquitectura mudéjar. Data de la segunda mitad del siglo XVI, siendo construida durante el mandato de Don Antonio Corrionero de Babilafuente, obispo de la diócesis…',36.8309993,-2.6437882,'https://es.wikipedia.org/wiki/Iglesia_de_San_Benito_(Vícar)');
