INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158125,'25577','Sant Pere de l''Abadia','iglesia','monumentos_osm','Sant Pere de l''Abadia, o Sant Pere de Son, és una antiga església romànica del poble de Son, en el terme municipal d''Alt Àneu, a la comarca del Pallars Sobirà. Està desafectada des d''antic; durant molts anys serví d''escola, residència dels mestres, ajuntament, rectoria (d''on el nom d''Abadia).',42.6200891,1.0957868,'https://ca.wikipedia.org/wiki/Sant_Pere_de_l''Abadia');
