INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158166,'17057','Sant Julià','iglesia','monumentos_osm','Sant Julià de Corçà és una església situada al municipi de Corçà, al Baix Empordà, construïda entre els segles XVII i XVIII sobre les restes del temple anterior d''estil romànic. És un monument protegit i inventariat dins el Patrimoni Arquitectònic Català.',41.9894442,3.0172655,'https://ca.wikipedia.org/wiki/Sant_Julià_de_Corçà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158167,'17057','Santa Cristina de Corçà','iglesia','monumentos_osm','Santa Cristina de Corçà és una ermita d''origen medieval del municipi de Corçà (Baix Empordà), situada a uns cinc-cents metres als afores del nucli, en direcció sud. És un monument protegit amb categoria BCIL i inclòs en l''Inventari del Patrimoni Arquitectònic Català (IPAC 7018).',41.9809392,3.0096122,'https://ca.wikipedia.org/wiki/Santa_Cristina_de_Corçà');
