INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158171,'30038','Iglesia de Nuestra Señora de la Salceda','iglesia','monumentos_osm','La iglesia de Nuestra Señora de la Salceda es un templo católico español que se encuentra ubicado en la población de Las Torres de Cotillas, perteneciente a Murcia. Es de estilo barroco.',38.0295058,-1.2413958,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Salceda');
