INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158176,'43026','Ermita del Pilar','iglesia','monumentos_osm','La Mare de Déu del Pilar o ermita del Pilar és la capella del cementiri de la vila de Benissanet (Ribera d''Ebre) catalogada a l''Inventari del Patrimoni Arquitectònic de Catalunya. És als afores del nucli urbà de la població de Benissanet, a la banda de tramuntana del terme, al final del carrer del Calvari.',41.0618955,0.6322927,'https://ca.wikipedia.org/wiki/Ermita_del_Pilar');
