INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158178,'17133','Església parroquial de Sant Cristòfol de les Planes','iglesia','monumentos_osm','Sant Cristòfol és una església parroquial al nucli de les Planes d''Hostoles (la Garrotxa) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. L''església original podria ser anterior al segle X però va ser destruïda pels terratrèmols de 1427-1428.',42.055399,2.5368146,'https://ca.wikipedia.org/wiki/Sant_Cristòfol_de_les_Planes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158179,'17133','Sant Pere Sacosta','iglesia','monumentos_osm','Sant Pere Sacosta és un antic poble del municipi de les Planes d’Hostoles (Garrotxa), situat al sud del cap del municipi. També és una entitat singular de població del mateix municipi.',42.0516055,2.5157545,'https://ca.wikipedia.org/wiki/Sant_Pere_Sacosta');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158180,'46032','Església Parroquial del Santíssim Sagrament','iglesia','monumentos_osm','La iglesia del Santísimo Sacramento (en valenciano Església del Santíssim Sacrament) es un templo católico situado al borde de la plaza Mayor de Almácera (Valencia, España).​ Aunque comenzó a construirse en 1792, su construcción se alargó hasta 1875.​ Conserva la arqueta de plomo donde, según la tradición, se…',39.5121853,-0.355636,'https://es.wikipedia.org/wiki/Iglesia_del_Santísimo_Sacramento_(Almácera)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158181,'28100','Iglesia de San Francisco Javier','iglesia','monumentos_osm','La iglesia de San Francisco Javier se encuentra en el municipio madrileño de Nuevo Baztán. La iglesia se encuentra adyacente al Palacio de Goyeneche, ambos diseñados por el arquitecto José Benito Churriguera y construidos entre 1709 y 1713.​ La iglesia recibió la declaración de Monumento Histórico Artístico en el…',40.3657844,-3.2429305,'https://es.wikipedia.org/wiki/Iglesia_de_San_Francisco_Javier_(Nuevo_Baztán)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158182,'43065','Església nova','iglesia','monumentos_osm','Santa Maria és un església al carrer del Centre de Garcia (Ribera d''Ebre), adossada per un lateral i posterior a edificis urbans. Destruïda l''església vella el 1936, quan va acabar la guerra es va improvisar una capella a la part baixa del poble, fins que se''n va poder construir una de nova.',41.1359476,0.651229,'https://ca.wikipedia.org/wiki/Església_de_Garcia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158183,'47231','Iglesia de San Pedro Apóstol','iglesia','monumentos_osm','La iglesia parroquial de San Pedro Apóstol es un templo católico ubicado en la localidad de Zaratán, Provincia de Valladolid, Castilla y León, España.',41.6614765,-4.7827224,'https://es.wikipedia.org/wiki/Iglesia_de_San_Pedro_Apóstol_(Zaratán)');
