INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158188,'22142','Ermita de La Virgen del Llano','iglesia','monumentos_osm','Mare de Déu del Llano (o del Pla) és una ermita romànica de final de segle xii, situada al municipi de Capella (Ribagorça), dins de la Franja de Ponent a la comarca de la Ribagorça. La seva planta és una nau i absis cilíndric i capelles laterals, amb un campanar en espadanya de dos ulls centrats.',42.2042953,0.4722305,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Llano');
