INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158215,'43166','Mare de Déu de Paretdelgada','iglesia','monumentos_osm','L''ermita de Santa Maria de Paretdelgada és un edifici religiós situat al terme de la Selva del Camp i a uns 4 km del poble, a l''antic camí de Vilallonga. La primitiva imatge venerada era una marededeu romànica amb el Nen a la falda.',41.2136891,1.1754484,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Paretdelgada');
