INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158219,'25180','Església de Santa Maria Assumpta','iglesia','monumentos_osm','L''Assumpció és una església parroquial a la vila de Puiggròs (Garrigues) protegida com a bé cultural d''interès local.',41.550492,0.8901775,'https://ca.wikipedia.org/wiki/L''Assumpció_de_Puiggròs');
