INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158222,'44092','Ermita de San Pedro','iglesia','monumentos_osm','La ermita de San Pedro se encuentra en el municipio de El Cuervo, provincia de Teruel, (Comunidad de Aragón, España). Actualmente arruinada y sin culto, el emblemático edificio y el solar sobre el que se asienta son de propiedad particular.',40.1541397,-1.3281238,'https://es.wikipedia.org/wiki/Ermita_de_San_Pedro_(El_Cuervo)');
