INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158225,'17178','Església de Sant Pere','iglesia','monumentos_osm','L''Església parroquial de Sant Pere és una església que està situada al poble de Sant Pere Pescador a la comarca de l''Alt Empordà. Està situada a l''interior de l''antic recinte fortificat de la vila, davant la plaça de l''Església.',42.188383,3.0821387,'https://ca.wikipedia.org/wiki/Església_de_Sant_Pere_de_Sant_Pere_Pescador');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158226,'46126','Església de l''Assumpció de Nostra Senyora','iglesia','monumentos_osm','L''església de l''Assumpció de la Mare de Déu, sub invocatione Assumptionis Beatae Mariae Virginis, com era costum al S. XIII, és un temple catòlic situat a la plaça del Poble de Foios (Horta Nord, País Valencià). Va començar a construir-se en 1730 segons els plànols del mestre Joan Baptista Mingues (o Josep Minguez).',39.537957,-0.3566627,'https://ca.wikipedia.org/wiki/Església_de_l''Assumpció_de_Nostra_Senyora_(Foios)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158227,'43167','Sant Joan Baptista','iglesia','monumentos_osm','Sant Joan Baptista de Vilanova d''Escornalbou és una església de Vilanova d''Escornalbou (Baix Camp) protegida com a bé cultural d''interès local',41.1131694,0.9376245,'https://ca.wikipedia.org/wiki/Sant_Joan_Baptista_de_Vilanova_d''Escornalbou');
