INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158230,'46199','Parròquia de Sant Josep','iglesia','monumentos_osm','L''església parroquial de Sant Josep és un temple catòlic situat al municipi de La Pobla de Farnals. Està catalogada com a Bé d''interès cultural, amb número d''anotació RI-46.13.199-001, segons la llei del Patrimoni Cultural Valencià.',39.5805554,-0.3253939,'https://ca.wikipedia.org/wiki/Església_de_Sant_Josep_(La_Pobla_de_Farnals)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158231,'43122','Santa Llúcia','iglesia','monumentos_osm','Santa Llúcia de Renau és una església al municipi de Renau (Tarragonès) protegit com a bé cultural d''interès local.S''hi conserva una imatge de la Mare de Déu del Lloret, reproducció de la talla gòtica provinent del Santuari de Mare de Déu del Lloret. La pintura de l''interior sembla l''original.',41.2249643,1.311224,'https://ca.wikipedia.org/wiki/Santa_Llúcia_de_Renau');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158232,'90890','Església de Sant Genís','iglesia','monumentos_osm','L''església parroquial de Sant Genís de Casavells és un edifici romànic dins del nucli de Casavells, al municipi de Corçà, al Baix Empordà. És un monument protegit i inventariat dins el Patrimoni Arquitectònic Català.',41.9998447,3.0330761,'https://ca.wikipedia.org/wiki/Sant_Genís_de_Casavells');
