INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158237,'08257','Sant Romà','iglesia','monumentos_osm','L''església de Sant Romà és un temple al veïnat de Sant Romà (Anoia) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. L''antiga capella de Sant Romà, ara església parroquial, centra una caseria de poblament disseminat, el 1915 fou controvertida parròquia del lloc, restaurada (veure dates a la…',41.499116,1.5298505,'https://ca.wikipedia.org/wiki/Sant_Romà_(Santa_Maria_de_Miralles)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158238,'47154','Iglesia de San Juan Evangelista','iglesia','monumentos_osm','La iglesia de San Juan Evangelista o San Juan Apóstol es la iglesia parroquial de Santibáñez de Valcorba, provincia de Valladolid, España.',41.5699539,-4.4512477,'https://es.wikipedia.org/wiki/Iglesia_de_San_Juan_Evangelista_(Santibáñez_de_Valcorba)');
