INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158240,'17073','Sant Cugat de Fornells de la Selva','iglesia','monumentos_osm','Sant Cugat és l''església parroquial al nucli de Fornells de la Selva (Gironès), dedicada als màrtirs sant Cugat i sant Vidal. El temple actual és de la segona meitat del segle xvi, de tradició gòtica amb elements renaixentistes i fortificat.',41.9313115,2.8127384,'https://ca.wikipedia.org/wiki/Sant_Cugat_de_Fornells_de_la_Selva');
