INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158242,'46030','Església parroquial de Sant Vicent Ferrer','iglesia','monumentos_osm','L''Església de Sant Vicent Ferrer és un temple catòlic situat a Algímia d''Alfara. Es va construir sobre una antiga mesquita reconvertida en església que, fins a 1574 havia estat annexa de la parròquia de Torres-Torres.',39.7526007,-0.3626908,'https://ca.wikipedia.org/wiki/Església_parroquial_de_Sant_Vicent_Ferrer_(Algímia_d''Alfara)');
