INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158244,'47090','Iglesia de Santa María','iglesia','monumentos_osm','La iglesia de Santa María es un templo católico ubicado en la localidad de Mojados, Provincia de Valladolid, Castilla y León, España.',41.4328345,-4.6617005,'https://es.wikipedia.org/wiki/Iglesia_de_Santa_María_(Mojados)');
