INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158246,'17071','Església de la Mare de Déu de la font','iglesia','monumentos_osm','Mare de Déu de la Font de Fontcoberta és una obra de Fontcoberta (Pla de l''Estany) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. És una capella situada en una fondalada, al sud de Fontcoberta en el veïnat de la Farrés, a la capçalera de la riera del Garrumbert.',42.146411,2.7823975,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Font_de_Fontcoberta');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158247,'17071','Sant Bartomeu de Torres','iglesia','monumentos_osm','Sant Bartomeu de Torres és una església romànica de Fontcoberta (Pla de l''Estany) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.1220914,2.8176052,'https://ca.wikipedia.org/wiki/Sant_Bartomeu_de_Torres');
