INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158250,'17071','Sant Sadurní de Vilavenut','iglesia','monumentos_osm','Sant Sadurní de Vilavenut és una església amb elements romànics i barrocs del poble de Vilavenut, al municipi de Fontcoberta (Pla de l''Estany), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.1394622,2.8214861,'https://ca.wikipedia.org/wiki/Sant_Sadurní_de_Vilavenut');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158251,'49194','Iglesia de San Pedro de la Nave','iglesia','monumentos_osm','La iglesia de San Pedro de la Nave es un templo visigodo de la localidad española de El Campillo, término municipal de San Pedro de la Nave-Almendra, en la provincia de Zamora Castilla y León. Fue declarada Monumento Nacional el 22 de abril de 1912 (publicado en el BOE de 29 de abril de 1912).',41.5832129,-5.9641069,'https://es.wikipedia.org/wiki/Iglesia_de_San_Pedro_de_la_Nave_(El_Campillo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158252,'22067','Ermita de San Aventín','iglesia','monumentos_osm','La ermita de San Aventín pertenece al término de la localidad española de Bonansa, en la Ribagorza, provincia de Huesca, Aragón. Se encuentra en el pico de San Aventín, al nordeste del pueblo de Bonansa.',42.4283376,0.67013,'https://es.wikipedia.org/wiki/Ermita_de_San_Aventín_(Bonansa)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158253,'43101','Església parroquial de Sant Jaume de Passanant','iglesia','monumentos_osm','L''Església parroquial de Sant Jaume de Passanant és una església barroca del municipi de Passanant i Belltall (Conca de Barberà) construïda entre els anys 1770 i 1782. Forma part de l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.531942,1.1967141,'https://ca.wikipedia.org/wiki/Sant_Jaume_de_Passanant');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158254,'25907','Sant Amanç','iglesia','monumentos_osm','Sant Amanç de Torrefeta és l''església parroquial barroca de Torrefeta, al municipi de Torrefeta i Florejacs (Segarra), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7540569,1.2732339,'https://ca.wikipedia.org/wiki/Sant_Amanç_de_Torrefeta');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158255,'25907','Sant Jaume','iglesia','monumentos_osm','Sant Jaume de Bellveí és l''església parroquial de Bellveí, al municipi de Torrefeta i Florejacs (Segarra), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7549453,1.2915165,'https://ca.wikipedia.org/wiki/Sant_Jaume_de_Bellveí');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158256,'25907','Sant Salvador','iglesia','monumentos_osm','Sant Salvador de Concabella és una església romànica situada al nucli de la població de Concabella, al municipi dels Plans de Sió (Segarra). És un monument protegit i inventariat dins el Patrimoni Arquitectònic Català.',41.7518308,1.2355633,'https://ca.wikipedia.org/wiki/Sant_Salvador_de_Concabella');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158257,'25907','Sant Salvador de Gra','iglesia','monumentos_osm','L''església parroquial de Sant Salvador de Gra és a ponent de Gra, poble del terme de Torrefeta i Florejacs (Segarra), situat a la vall del torrent del Passerell. És una obra inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7663811,1.2509465,'https://ca.wikipedia.org/wiki/Sant_Salvador_de_Gra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158258,'25181','Sant Antoni Abat','iglesia','monumentos_osm','Sant Antoni Abat de Renant és una església de Renant, al municipi d''Oliola (Noguera) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7925022,1.1659808,'https://ca.wikipedia.org/wiki/Sant_Antoni_Abat_de_Renant');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158259,'25181','Església de Santa Maria','iglesia','monumentos_osm','Santa Maria d''Agramunt és una església romànica al municipi d''Agramunt a la comarca d''Urgel) declarada bé cultural d''interès nacional des del 1931. Les portalades de la façana oest i nord constitueixen un magnífic exemple de l''escultura romànica catalana del segle xiii de l''escola lleidatana, amb influències…',41.7872586,1.0992032,'https://ca.wikipedia.org/wiki/Santa_Maria_d''Agramunt');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158260,'25181','Sant Domènec','iglesia','monumentos_osm','Sant Domènec de les Puelles és una església neoclàssica d''Agramunt (Urgell) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.8005922,1.1294856,'https://ca.wikipedia.org/wiki/Sant_Domènec_de_les_Puelles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158261,'25181','Sant Miquel','iglesia','monumentos_osm','Sant Miquel de Montfalcó d''Ossó és una església barroca de Montfalcó d''Ossó, al municipi d''Ossó de Sió (Urgell) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7594894,1.1314103,'https://ca.wikipedia.org/wiki/Sant_Miquel_de_Montfalcó_d''Ossó');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158262,'25181','Sant Pere','iglesia','monumentos_osm','L''església de Sant Pere és un temple parroquial de Puigverd d''Agramunt (Urgell), inclòs a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7771602,1.121828,'https://ca.wikipedia.org/wiki/Sant_Pere_de_Puigverd_d''Agramunt');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158263,'49095','Iglesia de Santa María la Real','iglesia','monumentos_osm','La iglesia de Santa María la Real es una iglesia ubicada en el municipio zamorano de La Hiniesta.',41.5524388,-5.7988704,'https://es.wikipedia.org/wiki/Iglesia_de_Santa_María_la_Real_(La_Hiniesta)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158264,'17167','Mare de Déu del Prat','iglesia','monumentos_osm','La Mare de Déu del Prat és una capella de Sant Joan de les Abadesses (Ripollès) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. L''oratori de la Mare de Déu del Prat és una antiga capelleta o reposador situada a la vora de l''antic camí ral a Camprodon, és a dir al NE, molt a prop de la vila, erigida…',42.2371757,2.289274,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Prat');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158265,'25057','Mair de Diu dera Artiga de Lin','iglesia','monumentos_osm','La Capella de l''Artiga de Lin és una obra de Vielha e Mijaran (Vall d''Aran) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.6970693,0.707416,'https://ca.wikipedia.org/wiki/Capella_de_l''Artiga_de_Lin');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158266,'25057','Mair de Diu deth Rosèr','iglesia','monumentos_osm','La Mare de Déu del Roser de les Bordes, en aranès era Mair de Diu deth Roser, és l''església parroquial d''Es Bòrdes inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.737701,0.7193979,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Roser_de_les_Bordes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158267,'25057','Sant Martin de Benós','iglesia','monumentos_osm','Sant Martí de Benós és una església de Benòs al municipi d''Es Bòrdes inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.7395363,0.7284372,'https://ca.wikipedia.org/wiki/Sant_Martí_de_Benós');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158268,'17154','Sant Martí','iglesia','monumentos_osm','Sant Martí de Sales és una església del municipi de Sales de Llierca (Garrotxa) que forma part de l''Inventari del Patrimoni Arquitectònic de Catalunya. Als documents antics és anomenada Sant Martí de "Cabissono", que sembla el nom que porta el lloc on posteriorment fou bastida l''església.',42.235759,2.6496916,'https://ca.wikipedia.org/wiki/Sant_Martí_de_Sales');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158269,'17154','Sant Miquel de Monteia','iglesia','monumentos_osm','Sant Miquel de Monteia és una església romànica de principi del segle xiii que es troba al municipi de Sales de Llierca (Garrotxa), a prop del Mas Monteia, una casa de pagès rellevant d''aquesta zona de l''Alta Garrotxa.',42.2669357,2.6481797,'https://ca.wikipedia.org/wiki/Sant_Miquel_de_Monteia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158270,'17125','Santa Magdalena de Puigsac','iglesia','monumentos_osm','Santa Magdalena de Puigsac, també coneguda com a Santa Margarida de Pardines, és una capella isolada situada al nord de la Serra Cavallera, al nucli de Puigsac, al municipi de Pardines, a la comarca catalana del Ripollès. Santa Magdalena de Puigsac és una capella isolada situada a la serra Cavallera, prop del nucli…',42.3083052,2.2269995,'https://ca.wikipedia.org/wiki/Santa_Magdalena_de_Puigsac');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158271,'25911','Ermita de Sant Roc de Mont-roig','iglesia','monumentos_osm','L''Ermita de Sant Roc de Mont-roig és una capella de Mont-roig, al municipi dels Plans de Sió (Segarra), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7511629,1.1922396,'https://ca.wikipedia.org/wiki/Ermita_de_Sant_Roc_de_Mont-roig');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158272,'25911','Sant Esteve','iglesia','monumentos_osm','Sant Esteve de Pelagalls és una església romànica del municipi dels Plans de Sió (Segarra). Va ser declarada Bé Cultural d''Interès Nacional per decret publicat al DOGC el 05-11-1982.',41.7519482,1.2032968,'https://ca.wikipedia.org/wiki/Sant_Esteve_de_Pelagalls');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158273,'25911','Sant Gil','iglesia','monumentos_osm','L''església de Sant Gil de Riudovelles és al petit nucli de Riudovelles, situat en un turó al peu del qual es forma el torrent de Sant Gil. Riudovelles era un agregat de l''antic municipi de la Figuerosa, annexat a Tàrrega l''any 1969.',41.7144409,1.1954746,'https://ca.wikipedia.org/wiki/Sant_Gil_de_Riudovelles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158274,'25911','Sant Pere','iglesia','monumentos_osm','Sant Pere de Muller és una església de Muller, al municipi dels Plans de Sió (Segarra), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7082793,1.2088355,'https://ca.wikipedia.org/wiki/Sant_Pere_de_Muller');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158275,'47044','Iglesia de Santa María de la Concepción','iglesia','monumentos_osm','La iglesia de Santa María de la Concepción es un templo católico ubicado en la localidad de Castronuevo de Esgueva, Provincia de Valladolid, Castilla y León, España.',41.6815993,-4.5875875,'https://es.wikipedia.org/wiki/Iglesia_de_Santa_María_de_la_Concepción_(Castronuevo_de_Esgueva)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158276,'43016','Església de Sant Julià','iglesia','monumentos_osm','Sant Julià de l''Arboç és l''església parroquial del municipi de l''Arboç declarada bé cultural d''interès nacional.',41.2681316,1.6041597,'https://ca.wikipedia.org/wiki/Sant_Julià_de_l''Arboç');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158277,'25058','Sant Salvador','iglesia','monumentos_osm','Sant Salvador de les Borges Blanques és una ermita de les Borges Blanques (Garrigues) protegida com a bé cultural d''interès local.',41.4915154,0.8741289,'https://ca.wikipedia.org/wiki/Sant_Salvador_de_les_Borges_Blanques');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158278,'46164','Església de Sant Joan Apòstol i Evangelista','iglesia','monumentos_osm','L''església Parroquial de Sant Joan Apòstol i Evangelista, és un temple catòlic situat a la plaça de la Constitució de Massamagrell. El temple data del segle xviii.',39.5700477,-0.330536,'https://ca.wikipedia.org/wiki/Església_de_Sant_Joan_Apòstol_i_Evangelista_(Massamagrell)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158279,'90878','Sant Esteve de les Masuques','iglesia','monumentos_osm','Sant Esteve també Sant Esteve de Castellet és una església a prop del poble de les Masuques al municipi de Castellet i la Gornal (Alt Penedès) protegit com a bé cultural d''interès local. Sant Esteve de Castellet és l''antiga parroquial del poble, abans que aquest passés a dependre de l''església de Sant Pere.',41.2882781,1.6400086,'https://ca.wikipedia.org/wiki/Sant_Esteve_de_Castellet');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158280,'90878','Sant Pere','iglesia','monumentos_osm','Sant Pere de Castellet és una obra de Castellet i la Gornal (Alt Penedès) protegida com a bé cultural d''interès local. L''església parroquial de Sant Pere de Castellet està situada a la part més alta del poble, prop del castell.',41.2649203,1.6369575,'https://ca.wikipedia.org/wiki/Sant_Pere_de_Castellet');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158281,'17123','Església de Sant Miquel de Palol de Revardit','iglesia','monumentos_osm','L''església parroquial de Sant Miquel de Palol de Revardit és dins el conjunt format pel castell, aquesta església romànica i restes d''una muralla circular que constituïren el primitiu nucli d''un recinte medieval dels s. XII-XIV. Està protegida com a bé cultural d''interès local.',42.0697317,2.7963565,'https://ca.wikipedia.org/wiki/Sant_Miquel_de_Palol_de_Revardit');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158282,'17123','Sant Martí de Riudellots de la Creu','iglesia','monumentos_osm','Sant Martí de Riudellots de la Creu és la vella església parroquial del poble de Riudellots de la Creu, de cases disseminades, agregat al municipi de Palol de Revardit. És dedicada a Sant Martí.',42.0572966,2.8133869,'https://ca.wikipedia.org/wiki/Sant_Martí_de_Riudellots_de_la_Creu');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158283,'43120','Sant Jaume d''Esblada','iglesia','monumentos_osm','Sant Jaume d''Esblada és una obra del municipi de Querol (Alt Camp) protegida com a Bé Cultural d''Interès Local.',41.4446583,1.4403904,'https://ca.wikipedia.org/wiki/Sant_Jaume_d''Esblada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158284,'43120','Santa Maria de Querol','iglesia','monumentos_osm','Santa Maria de Querol és una església del municipi de Querol (Alt Camp) protegida com a bé cultural d''interès local.',41.4238991,1.399208,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Querol');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158285,'90893','Església de Sant Llorenç de les Arenes','iglesia','monumentos_osm','Sant Llorenç és l''església parroquial del poble de Sant Llorenç de les Arenes que vingué a substituir la parròquial de Sant Romanç de Cidillà, citada el 1065, que es va traslladar abans del 1313 a l''església de Sant Llorenç. És un monument protegit i inventariat dins el patrimoni arquitectònic català.',42.0611466,2.9778515,'https://ca.wikipedia.org/wiki/Església_de_Sant_Llorenç_de_les_Arenes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158286,'90893','Mare de Déu de l''Esperança','iglesia','monumentos_osm','La Mare de Déu de l''Esperança de Ferreres és una església de Ferreres, al municipi de Flaçà (Gironès), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.044962,2.9721058,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_l''Esperança_de_Ferreres');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158287,'17203','Santa Eulàlia d''Ultramort','iglesia','monumentos_osm','Santa Eulàlia d''Ultramort és una església romànica del municipi d''Ultramort inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.0361829,3.034428,'https://ca.wikipedia.org/wiki/Santa_Eulàlia_d''Ultramort');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158288,'43053','Santa Maria','iglesia','monumentos_osm','Santa Maria de Duesaigües és una església de Duesaigües (Baix Camp) protegida com a Bé Cultural d''Interès Local.',41.1459205,0.9309152,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Duesaigües');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158289,'17078','Sant Climent de Gréixer','iglesia','monumentos_osm','Sant Climent de Gréixer és una església romànica a l''entitat de població de Gréixer pertanyent al municipi de Ger a la comarca de la Baixa Cerdanya. Forma part de les moltes parròquies documentades a l''acta de consagració de la Seu d''Urgell l''any 839.',42.4127806,1.8244697,'https://ca.wikipedia.org/wiki/Sant_Climent_de_Gréixer');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158290,'17078','Santa Coloma de Ger','iglesia','monumentos_osm','Santa Coloma de Ger és una església d''estil romànic modificat de Ger (Baixa Cerdanya) protegida com a Bé Cultural d''Interès Local.',42.4112937,1.8439132,'https://ca.wikipedia.org/wiki/Santa_Coloma_de_Ger');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158291,'17078','Santa Eugènia de Saga','iglesia','monumentos_osm','Santa Eugènia és una petita església romànica que data del segle xi, a Saga, petit municipi de Ger, a la comarca de la Baixa Cerdanya, a pocs quilòmetres a l''oest de Puigcerdà.',42.4152493,1.8599093,'https://ca.wikipedia.org/wiki/Santa_Eugènia_de_Saga');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158292,'25253','Santa Maria del Vilosell','iglesia','monumentos_osm','L''església de Santa Maria es troba a la part alta del nucli del Vilosell. És un edifici d''origen romànic però que ha sofert múltiples transformacions al llarg dels temps, entre les quals hi ha la desaparició de l''absis semicircular primitiu i el trasllat de l''accés del mur de migdia al mur de ponent.',41.3840957,0.947015,'https://ca.wikipedia.org/wiki/Santa_Maria_del_Vilosell');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158293,'34036','Iglesia de San Miguel','iglesia','monumentos_osm','La actual ermita de San Miguel es lo que queda de la primera iglesia conocida que tuvo el pueblo de Brañosera. Su datación más aproximada y fidedigna corresponde al siglo XII, según atestigua la placa de consagración que aún se conserva, correspondiente al año 1118: Sin embargo, es probable que la escritura se…',42.9351714,-4.3077084,'https://es.wikipedia.org/wiki/Iglesia_de_San_Miguel_(Brañosera)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158294,'17085','Església de Sant Martí de Jafre','iglesia','monumentos_osm','Sant Martí de Jafre és una església parroquial a la vila homònima (Baix Empordà), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.0726155,3.0110018,'https://ca.wikipedia.org/wiki/Sant_Martí_de_Jafre');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158295,'17085','Santuari de la Font-Santa','iglesia','monumentos_osm','El Santuari de la Fontsanta també dit Mare de Déu de Gràcia de la Fontsanta és un edifici religiós al municipi de Jafre (Baix Empordà) catalogat a l''Inventari del Patrimoni Arquitectònic de Catalunya. Molt a prop hi ha la Font Santa de Jafre, inventariada de manera independent.',42.0758771,3.0091241,'https://ca.wikipedia.org/wiki/Santuari_de_la_Fontsanta');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158296,'50193','Iglesia de San Miguel Arcángel','iglesia','monumentos_osm','La iglesia de San Miguel Arcángel es una iglesia de España situada en la localidad de Alfajarín, perteneciente a la provincia de Zaragoza, en la comunidad autónoma de Aragón. Fue declarada bien de interés cultural en la categoría de monumento el 6 de noviembre de 2001.​ Es fruto de la remodelación en fases…',41.6149833,-0.7022418,'https://es.wikipedia.org/wiki/Iglesia_de_San_Miguel_Arcángel_(Alfajarín)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158297,'17087','Santuari Mare de Déu dels Angels','iglesia','monumentos_osm','El Santuari dels Àngels és un dels santuaris més visitats i de més devoció de les terres gironines, i s''hi venera la Mare de Déu dels Àngels. És al cim del Puig Alt al Massís de les Gavarres, al terme municipal de Sant Martí Vell (Gironès).',41.9847906,2.9087777,'https://ca.wikipedia.org/wiki/Santuari_dels_Àngels');
