INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158301,'17134','Sant Marcel de Planès','iglesia','monumentos_osm','Sant Marcel de Planès és una església romànica situada al poble de Planès, al municipi de Planoles, comarca del Ripollès. Se situa en un revolt del branc de la carretera N-260 que porta al nucli urbà de Planès, en el desnivell del terreny.',42.3197691,2.0980675,'https://ca.wikipedia.org/wiki/Sant_Marcel_de_Planès');
