INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158303,'22144','Ermita de la Fuensanta','iglesia','monumentos_osm','La ermita de la Fuensanta o ermita de la Fuente Santa es una ermita que se encuentra en una a 885 m, en las faldas de la Peña Montañesa, de entre los pueblos de Laspuña (en cuyo municipio se encuentra), San Lorenzo y Araguás. El nombre de la ermita según la tradición se debe a San Victorián, santo de origen…',42.4839204,0.1715897,'https://es.wikipedia.org/wiki/Ermita_de_Fuensanta');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158304,'90744','Iglesia de San Bartolomé','iglesia','monumentos_osm','La Iglesia Parroquial de San Bartolomé es un templo católico que se encuentra en el municipio de Beas, provincia de Huelva (España). Esta iglesia parroquial esta bajo el patrocinio de San Bartolomé Apóstol, patrón del municipio.',37.4263309,-6.7930664,'https://es.wikipedia.org/wiki/Iglesia_de_San_Bartolomé_(Beas)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158305,'43076','Santa Maria','iglesia','monumentos_osm','Santa Maria de Marçà és una església parroquial barroca del municipi de Marçà (Priorat) inclosa en l''Inventari del Patrimoni Arquitectònic Català. Va substituir a l''antiga església romànica de Santa Maria situada en el turó de la Miloquera.',41.1263311,0.8004471,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Marçà');
