INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158309,'12072','Ermita de Sant Antoni Abat','iglesia','monumentos_osm','L''Ermita de Sant Antoni Abat és a la sortida de la població de Llucena (Alcalatén, País Valencià) direcció a Castell de Villamalefa. La construcció d''aquest edifici data de 1785 i va ser aixecat en el solar d''un altre ermitori més antic, perquè es coneix l''existència de la Confraria de Sant Antoni de la Pedrenyera…',40.1360481,-0.2844258,'https://ca.wikipedia.org/wiki/Ermita_de_Sant_Antoni_Abat_(Llucena)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158310,'12902','Ermita de Sant Miquel','iglesia','monumentos_osm','L''ermita de Sant Miquel, es localitza en direcció a Vilafamés i a cinc quilòmetres de la població, en el vessant del tossal del Mollet. S''accedeix a la mateixa a través d''una pista forestal.',40.0771718,-0.0958161,'https://ca.wikipedia.org/wiki/Ermita_de_Sant_Miquel_(Vilafamés)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158311,'50139','Ermita de Nuestra Señora de los Dolores','iglesia','monumentos_osm','La ermita de la Virgen de los Dolores es una ermita barroca situada en la localidad zaragozana de Letux (España). Se encuentra fuera de la localidad, junto a la carretera entre Letux y Lagata.',41.2502941,-0.8023179,'https://es.wikipedia.org/wiki/Ermita_de_la_Virgen_de_los_Dolores_(Letux)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158312,'43044','Església parroquial de Sant Bartomeu','iglesia','monumentos_osm','L''església de Sant Bartomeu de la Sénia fou construïda al segle xviii seguint paràmetres d''estil barroc. De fet a la clau de volta que hi ha damunt el cor es conserva la data de 1701.',40.6348306,0.2799167,'https://ca.wikipedia.org/wiki/Sant_Bartomeu_de_la_Sénia');
