INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158337,'46023','Església de la Mare de Déu del Roser','iglesia','monumentos_osm','L''Església Parroquial de la Mare de Déu del Roser d''Alfauir és un monument religiós, que està ubicat al carrer Major s/n del municipi d''Alfauir, a la comarca de la Safor, província de València, que està declarat Bé de Rellevància Local, amb codi 46.25.023-003. Es tracta d''un edifici religiós construït durant la…',38.9278796,-0.2518773,'https://ca.wikipedia.org/wiki/Església_Parroquial_de_la_Mare_de_Déu_del_Roser_d''Alfauir');
