INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158339,'40905','Iglesia de la Vera Cruz','iglesia','monumentos_osm','La iglesia de la Invención de la Cruz, llamada también de la Vera Cruz, es un templo románico del municipio de Cuevas de Provanco, en la provincia de Segovia, Castilla y León, España. Tuvo una torre que se derrumbó en el año 1946 y que no se volvió a levantar sino que se aprovechó su primer cuerpo para ubicar en él…',41.5417945,-3.9611018,'https://es.wikipedia.org/wiki/Iglesia_de_la_Invención_de_la_Cruz_(Cuevas_de_Provanco)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158340,'22175','Ermita de la Virgen del Pla','iglesia','monumentos_osm','La ermita de Nuestra Señora del Plá (Pllà, en catalán bajorribagorzano) es una ermita situada en la localidad española de Purroy de la Solana, en Benabarre, Huesca, Aragón.​',42.0415185,0.4565763,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_del_Plá');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158341,'25220','Santa Maria','iglesia','monumentos_osm','Sant Joan de Térmens és una església de Térmens (Noguera) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7175878,0.7630649,'https://ca.wikipedia.org/wiki/Sant_Joan_de_Térmens');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158342,'09248','Monasterio de Santa María de Bujedo de Juarros','iglesia','monumentos_osm','El monasterio de Santa María de Bujedo de Juarros (Santa Cruz de Juarros, Burgos), perteneció a la orden del Císter y se encuentra situado en el fondo de un pequeño valle surcado por el río Seco, a escasos kilómetros de la ciudad de Burgos.',42.23747,-3.4962628,'https://es.wikipedia.org/wiki/Monasterio_de_Santa_María_de_Bujedo_de_Juarros');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158343,'09421','Monasterio de Santa María de la Vid','iglesia','monumentos_osm','El monasterio de Santa María de la Vid se encuentra en el municipio español de La Vid y Barrios, en la Provincia de Burgos. Fue en sus inicios un monasterio premostratense, pero hoy pertenece a los agustinos.',41.6289113,-3.4876848,'https://es.wikipedia.org/wiki/Monasterio_de_Santa_María_de_la_Vid');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158344,'34134','Abadía de Lebanza','iglesia','monumentos_osm','La abadía de Lebanza se encuentra a tres kilómetros de la localidad de Lebanza, en el término municipal de La Pernía, en la Montaña palentina (comunidad autónoma de Castilla y León, España).',42.9625689,-4.5531926,'https://es.wikipedia.org/wiki/Abadía_de_Lebanza');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158345,'17158','Església de Sant Climent','iglesia','monumentos_osm','Església de Sant Climent Sescebes és un temple del municipi de Sant Climent Sescebes (Alt Empordà) inclòs en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.3688121,2.9801738,'https://ca.wikipedia.org/wiki/Església_de_Sant_Climent_Sescebes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(158346,'43056','Església de Sant Andreu','iglesia','monumentos_osm','Sant Andreu de la Fatarella és una obra de la Fatarella inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.1625376,0.473234,'https://ca.wikipedia.org/wiki/Sant_Andreu_de_la_Fatarella');
